#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uint pcg(uint v) { v = v * 747796405u + 2891336453u; v = ((v >> ((v >> 28u) + 4u)) ^ v) * 277803737u; return (v >> 22u) ^ v; }
float hash2(vec2 ip, float seed) {
    uvec2 q = uvec2(ivec2(ip) + 32768);
    uint h = pcg(q.x ^ pcg(q.y ^ pcg(uint(int(seed)))));
    return float(h) * (1.0 / 4294967295.0);
}
float vnoise(vec2 p, float seed) {
    vec2 i = floor(p), f = fract(p);
    vec2 u2 = f * f * (3.0 - 2.0 * f);
    float a = hash2(i, seed), b = hash2(i + vec2(1, 0), seed);
    float c = hash2(i + vec2(0, 1), seed), d = hash2(i + vec2(1, 1), seed);
    return mix(mix(a, b, u2.x), mix(c, d, u2.x), u2.y);
}
float fbm(vec2 p, float seed) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 4; i++) { v += a * vnoise(p, seed + float(i) * 17.0); p *= 2.03; a *= 0.5; }
    return v;
}

uniform float u_amount;
uniform float u_scale;
uniform float u_speed;

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    vec2 p = v_texCoord * asp * u_scale;
    float t = u_time * u_speed;
    vec2 off = vec2(
        fbm(p + vec2(0.0, t), u_seed) - 0.5,
        fbm(p + vec2(5.2, t * 1.1), u_seed + 31.0) - 0.5
    ) * 2.0 * u_amount;
    fragColor0 = vec4(texture(u_image0, clamp(v_texCoord + off, 0.0, 1.0)).rgb, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_size;
uniform float u_angle;
uniform float u_softness;

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    float ang = radians(u_angle);
    mat2 R = mat2(cos(ang), -sin(ang), sin(ang), cos(ang));
    vec2 p = (v_texCoord - 0.5) * asp;
    vec2 g = (R * p) / u_size;
    vec2 cell = floor(g) + 0.5;
    vec2 cuv = (transpose(R) * (cell * u_size)) / asp + 0.5;
    vec3 col = texture(u_image0, clamp(cuv, 0.0, 1.0)).rgb;
    float lum = dot(col, vec3(0.299, 0.587, 0.114));
    float radius = sqrt(max(1.0 - lum, 0.0)) * 0.7071;
    float d = length(g - cell);
    float m = smoothstep(radius, radius - max(u_softness, 0.001) * 0.7071, d);
    fragColor0 = vec4(mix(vec3(1.0), col, m), 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_palette;      // enum: which Riso ink set
uniform float u_dotSize;      // halftone cell size (0 = continuous tone)
uniform float u_misreg;       // per-plate registration error
uniform float u_inkDensity;   // overall coverage multiplier
uniform float u_mottle;       // uneven ink coverage + roller streaks
uniform float u_grain;        // paper fibre showing through the ink
uniform float u_paperTone;    // white -> warm cream stock

// Riso spot inks, measured off the official ink chart. Note black is ~0.145,
// not 0.0 — a riso drum never lays down a true black, and faking one is the
// fastest way to make this look like a Photoshop filter instead of a print.
const vec3 INK_FPINK  = vec3(1.000, 0.282, 0.686);
const vec3 INK_BLUE   = vec3(0.000, 0.471, 0.749);
const vec3 INK_YELLOW = vec3(1.000, 0.910, 0.000);
const vec3 INK_RED    = vec3(1.000, 0.400, 0.369);
const vec3 INK_GREEN  = vec3(0.000, 0.663, 0.361);
const vec3 INK_TEAL   = vec3(0.000, 0.514, 0.541);
const vec3 INK_PURPLE = vec3(0.463, 0.357, 0.655);
const vec3 INK_ORANGE = vec3(1.000, 0.427, 0.184);
const vec3 INK_FEDBLU = vec3(0.239, 0.259, 0.541);
const vec3 INK_BLACK  = vec3(0.145, 0.145, 0.145);

const float EPS = 0.02;         // density floor; keeps -log() finite
const float TAU = 6.28318531;

// Classic separation angles, one per plate.
const float ANG0 = 0.261799388;  // 15deg
const float ANG1 = 0.785398163;  // 45deg
const float ANG2 = 1.308996939;  // 75deg

int inkSet(int idx, out vec3 a, out vec3 b, out vec3 c) {
    c = vec3(1.0);
    if (idx == 1)      { a = INK_FPINK;  b = INK_TEAL;   return 2; }
    else if (idx == 2) { a = INK_RED;    b = INK_BLUE;   return 2; }
    else if (idx == 3) { a = INK_YELLOW; b = INK_PURPLE; return 2; }
    else if (idx == 4) { a = INK_ORANGE; b = INK_FEDBLU; return 2; }
    else if (idx == 5) { a = INK_GREEN;  b = INK_FPINK;  return 2; }
    else if (idx == 6) { a = INK_BLACK;  b = INK_FPINK;  return 2; }
    else if (idx == 7) { a = INK_FPINK;  b = INK_BLUE;   c = INK_YELLOW; return 3; }
    else if (idx == 8) { a = INK_RED;    b = INK_YELLOW; c = INK_BLUE;   return 3; }
    else if (idx == 9) { a = INK_BLACK;  b = INK_RED;    c = INK_YELLOW; return 3; }
    a = INK_FPINK; b = INK_BLUE; return 2;
}

float hash11(float p) {
    p = fract(p * 0.1031);
    p *= p + 33.33;
    return fract(p * (p + p));
}
float hash21(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(i), hash21(i + vec2(1.0, 0.0)), f.x),
               mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0, 1.0)), f.x), f.y);
}
float fbm(vec2 p) {
    float v = 0.0, amp = 0.5;
    for (int i = 0; i < 4; i++) { v += amp * vnoise(p); p *= 2.02; amp *= 0.5; }
    return v;
}

// Least-squares coverage of two ink densities against a target density.
vec2 solve2(vec3 Da, vec3 Db, vec3 d) {
    float maa = dot(Da, Da), mab = dot(Da, Db), mbb = dot(Db, Db);
    float ba = dot(Da, d), bb = dot(Db, d);
    float det = maa * mbb - mab * mab;
    det = abs(det) < 1e-6 ? 1e-6 : det;
    float ca = (ba * mbb - bb * mab) / det;
    float cb = (maa * bb - mab * ba) / det;
    // Non-negativity refit: a plate can't lay down negative ink, so pin the
    // offender at zero and re-solve the other one alone.
    if (ca < 0.0) { ca = 0.0; cb = bb / max(mbb, 1e-6); }
    else if (cb < 0.0) { cb = 0.0; ca = ba / max(maa, 1e-6); }
    return max(vec2(ca, cb), vec2(0.0));
}

// Split a target density across 2 or 3 ink densities.
vec3 separate(vec3 d, vec3 D0, vec3 D1, vec3 D2, int n) {
    if (n == 2) return vec3(solve2(D0, D1, d), 0.0);

    mat3 M = mat3(D0, D1, D2);
    mat3 N = transpose(M) * M;
    N[0][0] += 1e-4; N[1][1] += 1e-4; N[2][2] += 1e-4;   // ridge, for near-collinear ink sets
    vec3 c = inverse(N) * (transpose(M) * d);

    if (c.x < 0.0)      return vec3(0.0, solve2(D1, D2, d));
    else if (c.y < 0.0) { vec2 r = solve2(D0, D2, d); return vec3(r.x, 0.0, r.y); }
    else if (c.z < 0.0) return vec3(solve2(D0, D1, d), 0.0);
    return c;
}

// Where plate `i` sits relative to the paper.
vec2 misOffset(int i) {
    float a = hash11(float(i) * 7.13 + u_seed * 0.017 + 0.31) * TAU;
    return vec2(cos(a), sin(a)) * u_misreg;
}

// Coverage -> screened coverage on a rotated dot grid. Area-correct (radius
// tracks sqrt of coverage) and derivative-free: fwidth() is the likeliest
// source of browser-vs-server drift and this has to hold the parity gate.
float screenDot(vec2 p, float cov, float ang, float cell) {
    if (cell <= 0.0) return cov;
    // Bare paper must stay bare: without this the smoothstep still resolves to
    // ~0.5 at each cell centre, stippling every unprinted area.
    if (cov <= 0.001) return 0.0;
    float s = sin(ang), c = cos(ang);
    vec2 g = (mat2(c, -s, s, c) * p) / cell;
    float d = length(fract(g) - 0.5);
    float r = sqrt(clamp(cov, 0.0, 1.0)) * 0.70710678;
    float px = 1.0 / max(cell * min(u_resolution.x, u_resolution.y), 1.0);
    // A cell only a pixel or two wide can't hold a dot: the AA band then spans
    // the whole cell and every plate settles at ~50% coverage, which reads as a
    // flat wash with the image gone. Below that size, fall back to continuous
    // tone — that's what a screen too fine to resolve actually looks like.
    float resolvable = 1.0 - smoothstep(0.2, 0.5, px);
    return mix(cov, smoothstep(r + min(px, 0.25), r - min(px, 0.25), d), resolvable);
}

// Blotchy density plus faint horizontal roller streaks, one field per plate.
float mottleField(vec2 uv, int i) {
    if (u_mottle <= 0.0) return 1.0;
    float fi = float(i);
    float blot = fbm(uv * 3.5 + vec2(fi * 11.7, u_seed * 0.013));
    float streak = vnoise(vec2(uv.x * 1.7 + fi * 3.1, uv.y * 190.0 + u_seed * 0.007));
    return mix(1.0, 0.62 + 0.76 * blot, u_mottle)
         * mix(1.0, 0.86 + 0.28 * streak, u_mottle * 0.6);
}

void main() {
    vec2 uv = v_texCoord;
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);

    vec3 ink0, ink1, ink2;
    int n = inkSet(int(u_palette + 0.5), ink0, ink1, ink2);

    vec3 D0 = -log(max(ink0, EPS));
    vec3 D1 = -log(max(ink1, EPS));
    vec3 D2 = -log(max(ink2, EPS));

    // Paper fibre: modulates how much ink takes, so grain reads as the stock
    // showing through rather than as noise laid over the top.
    float fib = hash21(floor(uv * u_resolution) + u_seed * 0.011);
    float clump = fbm(uv * u_resolution.y * 0.2 + u_seed * 0.019);
    float take = 1.0 + (fib - 0.5) * u_grain * 0.55 + (clump - 0.5) * u_grain * 0.35;

    // Each plate reads the source through its own registration error, so the
    // colour AND its screen shift together — that fringe is the whole tell.
    vec3 cov = vec3(0.0);
    for (int i = 0; i < 3; i++) {
        if (i >= n) break;
        vec2 off = misOffset(i);
        vec3 src = texture(u_image0, clamp(uv - off, 0.0, 1.0)).rgb;
        vec3 c = separate(-log(max(src, EPS)), D0, D1, D2, n);
        cov[i] = c[i];
    }

    cov *= u_inkDensity * take;
    cov = vec3(cov.x * mottleField(uv, 0), cov.y * mottleField(uv, 1), cov.z * mottleField(uv, 2));
    cov = clamp(cov, 0.0, 1.0);

    float cell = u_dotSize;
    vec3 scr = vec3(
        screenDot((uv - misOffset(0) - 0.5) * asp, cov.x, ANG0, cell),
        screenDot((uv - misOffset(1) - 0.5) * asp, cov.y, ANG1, cell),
        screenDot((uv - misOffset(2) - 0.5) * asp, cov.z, ANG2, cell)
    );

    // Separate hash from `fib`: if the paper's own texture and the ink's
    // take-up ride the same noise they cancel and the grain reads as flat.
    float tooth = hash21(floor(uv * u_resolution) + 91.7 + u_seed * 0.023);
    vec3 paper = mix(vec3(1.0), vec3(0.965, 0.945, 0.898), u_paperTone);
    paper *= 1.0 - (1.0 - tooth) * u_grain * 0.05;

    // Beer-Lambert stacking: the exact inverse of the separation above, which is
    // why a 3-ink set with no screen comes back to the source.
    vec3 outCol = paper;
    outCol *= pow(max(ink0, EPS), vec3(scr.x));
    outCol *= pow(max(ink1, EPS), vec3(scr.y));
    if (n > 2) outCol *= pow(max(ink2, EPS), vec3(scr.z));

    fragColor0 = vec4(clamp(outCol, 0.0, 1.0), 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_amplitude;
uniform float u_frequency;
uniform float u_speed;
uniform float u_angle;

void main() {
    float ang = radians(u_angle);
    vec2 dir = vec2(cos(ang), sin(ang));
    float phase = dot(v_texCoord, dir) * u_frequency * 6.2831853 + u_time * u_speed * 6.2831853;
    vec2 off = vec2(-dir.y, dir.x) * sin(phase) * u_amplitude;
    fragColor0 = vec4(texture(u_image0, clamp(v_texCoord + off, 0.0, 1.0)).rgb, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_strength;
uniform float u_radius;
uniform float u_speed;
uniform float u_centerX;
uniform float u_centerY;

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    vec2 c = vec2(u_centerX, u_centerY);
    vec2 p = (v_texCoord - c) * asp;
    float r = length(p);
    float fall = smoothstep(u_radius, 0.0, r);
    float a = u_strength * fall * (1.0 + 0.15 * sin(u_time * u_speed * 6.2831853));
    mat2 R = mat2(cos(a), -sin(a), sin(a), cos(a));
    vec2 uv = c + (R * p) / asp;
    fragColor0 = vec4(texture(u_image0, clamp(uv, 0.0, 1.0)).rgb, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_strength;
uniform float u_radius;
uniform float u_speed;
uniform float u_centerX;
uniform float u_centerY;

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    vec2 c = vec2(u_centerX, u_centerY);
    vec2 p = (v_texCoord - c) * asp;
    float r = length(p);
    float strength = u_strength * (1.0 + 0.2 * sin(u_time * u_speed * 6.2831853));
    if (r < u_radius && r > 0.0) {
        float k = r / u_radius;
        // exponent in (0.1, 3]: strength > 0 pinches (samples pull outward), < 0 bulges
        float r2 = u_radius * pow(k, clamp(1.0 + strength, 0.1, 3.0));
        p = (p / r) * r2;
    }
    vec2 uv = c + p / asp;
    fragColor0 = vec4(texture(u_image0, clamp(uv, 0.0, 1.0)).rgb, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_amplitude;
uniform float u_wavelength;
uniform float u_speed;
uniform float u_decay;
uniform float u_centerX;
uniform float u_centerY;

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    vec2 c = vec2(u_centerX, u_centerY);
    vec2 p = (v_texCoord - c) * asp;
    float r = length(p);
    float phase = (r / max(u_wavelength, 1e-4) - u_time * u_speed) * 6.2831853;
    float att = exp(-u_decay * r);
    vec2 dir = r > 0.0 ? p / r : vec2(0.0);
    vec2 off = dir * sin(phase) * u_amplitude * att;
    fragColor0 = vec4(texture(u_image0, clamp(v_texCoord + off / asp, 0.0, 1.0)).rgb, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_mode;        // 0 Glass, 1 Faceted, 2 Prism
uniform float u_facetStyle;  // 0 Voronoi, 1 Radial, 2 Shards, 3 Triangles
uniform float u_facetJitter; // Triangles: 0 regular equilateral -> 1 irregular
uniform float u_facetRefract;// per-facet rotate/zoom of each slice (cut-gem optics)
uniform float u_shading;     // per-facet flat shading + spec (3D low-poly look)
uniform float u_multiScale;  // Triangles: chance a facet subdivides into smaller ones
uniform float u_refraction;  // bend strength
uniform float u_dispersion;  // RGB / rainbow split
uniform float u_facets;      // cell density / wedge count
uniform float u_glint;       // facet-seam sparkle
uniform float u_shimmer;     // built-in drift speed (0 = static)
uniform float u_rotation;    // degrees
uniform float u_centerX;
uniform float u_centerY;

const float TAU = 6.28318530718;
const float PI  = 3.14159265359;

mat2 rot2(float a) { float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}
vec2 hash22(vec2 p) { float n = hash21(p); return vec2(n, hash21(p + n)); }

float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i), b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0)), d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p) {
    float s = 0.0, a = 0.5;
    for (int i = 0; i < 4; i++) { s += a * vnoise(p); p = p * 2.02 + 7.1; a *= 0.5; }
    return s;
}

// Visible-spectrum colour for a normalised wavelength w in [0,1] (Zucconi 6).
// Used to integrate a continuous prism spectrum instead of an RGB 3-tap.
vec3 bump3(vec3 x, vec3 y) { vec3 v = 1.0 - x * x; return clamp(v - y, 0.0, 1.0); }
vec3 spectral(float w) {
    vec3 c1 = vec3(3.54585104, 2.93225262, 2.41593945);
    vec3 x1 = vec3(0.69549072, 0.49228336, 0.27699880);
    vec3 y1 = vec3(0.02312639, 0.15225084, 0.52607955);
    vec3 c2 = vec3(3.90307140, 3.21182957, 3.96587128);
    vec3 x2 = vec3(0.11748627, 0.86755042, 0.66077860);
    vec3 y2 = vec3(0.84897130, 0.88445281, 0.73949448);
    return bump3(c1 * (w - x1), y1) + bump3(c2 * (w - x2), y2);
}

// Jittered position of an integer lattice corner (shared corners move alike).
vec2 jitterVert(vec2 P) { return P + (hash22(P + u_seed * 0.31) - 0.5) * (u_facetJitter * 0.7); }

// Barycentric weights of point s in triangle ABC (all >= 0 only if inside).
vec3 triBary(vec2 s, vec2 A, vec2 B, vec2 C) {
    vec2 v0 = B - A, v1 = C - A, v2 = s - A;
    float den = v0.x * v1.y - v1.x * v0.y;
    float a = (v2.x * v1.y - v1.x * v2.y) / den;
    float b = (v0.x * v2.y - v2.x * v0.y) / den;
    return vec3(1.0 - a - b, a, b);
}
float triWeight(vec2 s, vec2 A, vec2 B, vec2 C) { vec3 w = triBary(s, A, B, C); return min(min(w.x, w.y), w.z); }

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    vec2 center = vec2(u_centerX, u_centerY);
    vec2 p = (v_texCoord - center) * asp;   // centered, aspect-correct
    float shim = u_time * u_shimmer;
    float rot = radians(u_rotation) + shim * 0.3;
    vec2 pr = rot2(rot) * p;                 // rotated facet space

    int mode = int(u_mode + 0.5);
    int style = int(u_facetStyle + 0.5);
    float scale = max(u_facets, 1.0);

    vec2 warp = vec2(0.0);   // refraction displacement, texcoord space
    float seam = 0.0;        // 0..1 proximity to a facet edge (glint)
    float dispMul = 1.0;     // mode-specific dispersion weight
    vec2 cid = vec2(0.0);    // facet id (per-facet randomness)
    vec2 facetC = p;         // facet center in p-space (per-facet refraction)

    if (mode == 0) {
        // ---- Glass: smooth thick-glass refraction via FBM gradient ----
        vec2 q = pr * (scale * 0.35) + 13.0;
        vec2 off = vec2(fbm(q + vec2(0.0, 1.7)), fbm(q + vec2(4.2, 0.0))) - 0.5;
        warp = rot2(-rot) * off * u_refraction * 0.32 / asp;
        seam = smoothstep(0.34, 0.5, length(off) * 2.0);  // ridge lines glint
    } else if (mode == 1) {
        // ---- Faceted: per-cell constant refraction (flat facets) ----
        vec2 dir;
        if (style == 0) {
            // Voronoi gem cells
            vec2 g = pr * scale * 0.5;
            vec2 gi = floor(g), gf = g - gi;
            float f1 = 8.0, f2 = 8.0; vec2 featG = g;
            for (int j = -1; j <= 1; j++) {
                for (int i = -1; i <= 1; i++) {
                    vec2 o = vec2(float(i), float(j));
                    vec2 rnd = hash22(gi + o + u_seed * 0.137);
                    vec2 fp = o + 0.5 + 0.45 * sin(shim * 1.3 + TAU * rnd);
                    vec2 diff = fp - gf;
                    float d = dot(diff, diff);
                    if (d < f1) { f2 = f1; f1 = d; cid = gi + o + rnd; featG = gi + fp; }
                    else if (d < f2) { f2 = d; }
                }
            }
            seam = 1.0 - smoothstep(0.0, 0.14, sqrt(f2) - sqrt(f1));
            facetC = rot2(-rot) * (featG / (scale * 0.5));
        } else if (style == 1) {
            // Radial wedges + rings (cut round-brilliant)
            float ang = atan(pr.y, pr.x);
            float seg = TAU / scale;
            float wid = floor((ang + PI) / seg);
            float local = fract((ang + PI) / seg);
            float r = length(pr) * (scale * 0.25);
            float ring = floor(r);
            cid = vec2(wid, ring);
            float dAng = min(local, 1.0 - local);
            float dRing = min(fract(r), 1.0 - fract(r));
            seam = 1.0 - smoothstep(0.0, 0.10, min(dAng, dRing));
            float midAng = (wid + 0.5) * seg - PI;
            facetC = rot2(-rot) * (vec2(cos(midAng), sin(midAng)) * ((ring + 0.5) / (scale * 0.25)));
        } else if (style == 2) {
            // Shards: grid cells split on the diagonal (cracked glass)
            vec2 g = pr * scale * 0.5;
            vec2 gi = floor(g), gf = g - gi;
            float tri = gf.x + gf.y < 1.0 ? 0.0 : 1.0;
            cid = gi + vec2(tri * 0.5, 0.0);
            float dDiag = abs(gf.x + gf.y - 1.0) * 0.7071;
            float dEdge = min(min(gf.x, 1.0 - gf.x), min(gf.y, 1.0 - gf.y));
            seam = 1.0 - smoothstep(0.0, 0.07, min(dDiag, dEdge));
            facetC = rot2(-rot) * ((gi + (tri < 0.5 ? vec2(1.0 / 3.0) : vec2(2.0 / 3.0))) / (scale * 0.5));
        } else {
            // Triangles: equilateral lattice with JITTERED VERTICES. Edges stay
            // straight (low-poly) while triangles vary in size/shape toward a
            // Delaunay-style shatter — never the wavy "water" of a domain warp.
            // Each pixel is point-located in the *jittered* mesh so the facet
            // DISPLACEMENT follows the jittered edges, not the regular lattice.
            vec2 q = pr * scale * 0.6;
            mat2 SK = mat2(1.0, 0.0, -0.57735, 1.15470);  // screen -> skew lattice
            vec2 s = SK * q;
            vec2 base = floor(s);
            float best = -1e9;
            vec2 Aw = vec2(0.0), Bw = vec2(0.0), Cw = vec2(0.0);
            for (int j = -1; j <= 1; j++) {
                for (int i = -1; i <= 1; i++) {
                    vec2 c0 = base + vec2(float(i), float(j));
                    vec2 P00 = jitterVert(c0);
                    vec2 P10 = jitterVert(c0 + vec2(1.0, 0.0));
                    vec2 P11 = jitterVert(c0 + vec2(1.0, 1.0));
                    vec2 P01 = jitterVert(c0 + vec2(0.0, 1.0));
                    float wl = triWeight(s, P00, P10, P01);     // lower triangle
                    if (wl > best) { best = wl; cid = c0; Aw = P00; Bw = P10; Cw = P01; }
                    float wu = triWeight(s, P10, P11, P01);     // upper triangle
                    if (wu > best) { best = wu; cid = c0 + vec2(0.37, 0.0); Aw = P10; Bw = P11; Cw = P01; }
                }
            }
            // Multi-scale: some facets split once into 4 smaller ones (midpoint
            // subdivision, jittered) for a mix of large + small triangles.
            if (u_multiScale > 0.0 && hash21(cid + 17.0) < u_multiScale) {
                vec3 bc = triBary(s, Aw, Bw, Cw);
                float jm = u_facetJitter * 0.28;
                vec2 Mab = mix(Aw, Bw, 0.5) + (hash22(Aw + Bw + 33.0) - 0.5) * jm;
                vec2 Mbc = mix(Bw, Cw, 0.5) + (hash22(Bw + Cw + 33.0) - 0.5) * jm;
                vec2 Mca = mix(Cw, Aw, 0.5) + (hash22(Cw + Aw + 33.0) - 0.5) * jm;
                if (bc.x > 0.5) { Bw = Mab; Cw = Mca; cid += vec2(0.07, 0.0); }
                else if (bc.y > 0.5) { Aw = Mab; Cw = Mbc; cid += vec2(0.0, 0.07); }
                else if (bc.z > 0.5) { Aw = Mca; Bw = Mbc; cid += vec2(0.07, 0.07); }
                else { Aw = Mab; Bw = Mbc; Cw = Mca; cid += vec2(0.13, 0.13); }
                best = triWeight(s, Aw, Bw, Cw);
            }
            seam = 1.0 - smoothstep(0.0, 0.14, best);
            mat2 SKi = mat2(1.0, 0.0, 0.5, 0.8660254);   // skew -> screen
            facetC = rot2(-rot) * ((SKi * ((Aw + Bw + Cw) / 3.0)) / (scale * 0.6));
        }
        // per-cell magnitude varies so not every facet shifts the same
        float mag = 0.5 + 0.5 * hash21(cid + 4.0);
        dir = normalize(hash22(cid + u_seed * 0.21) * 2.0 - 1.0 + 1e-4);
        warp = rot2(-rot) * dir * u_refraction * 0.15 * mag / asp;
    } else {
        // ---- Prism: minimal displacement, dispersion dominates ----
        vec2 d = (length(p) > 1e-4) ? normalize(p) : vec2(0.0);
        warp = -d / asp * u_refraction * 0.04 * length(p);
        dispMul = 1.0;
    }

    // ---- Chromatic dispersion ----
    // Concentrated where the image actually bends (|warp|) and along seams, so
    // the rainbow reads as refraction rather than a global RGB shift. Prism adds
    // a smooth radial term so the whole frame disperses toward the edges.
    vec2 dir = (length(p) > 1e-4) ? normalize(p) : vec2(0.0);
    float bend = length(warp * asp);                       // refraction strength
    float spread = u_dispersion * (bend * 9.0 + seam * 0.5);
    if (mode == 2) spread += u_dispersion * (0.5 + length(p) * 1.4);
    vec2 dispDir = bend > 1e-5 ? normalize(warp) : (dir / asp);
    // Per-facet refraction: each facet rotates/zooms its own slice of the image
    // around the facet center — true cut-gem optics, not just a parallel shift.
    vec2 baseUv;
    if (mode == 1 && u_facetRefract > 0.0) {
        float fr = (hash21(cid + 7.0) - 0.5) * 2.0;
        float fz = 1.0 + (hash21(cid + 9.0) - 0.5);
        vec2 rel = p - facetC;
        rel = rot2(fr * u_facetRefract * 1.4) * rel * mix(1.0, fz, u_facetRefract * 0.8);
        baseUv = (facetC + rel) / asp + center + warp;
    } else {
        baseUv = v_texCoord + warp;
    }
    // Spectral dispersion: integrate the image across the visible spectrum, each
    // wavelength refracted by a slightly different amount along the bend. Bright
    // edges fan into a continuous red->violet rainbow (a real prism), not a flat
    // cyan/magenta RGB split. Weight-normalised so spread=0 returns the image.
    const int NSPEC = 14;
    vec3 col = vec3(0.0);
    vec3 wsum = vec3(0.0);
    for (int i = 0; i < NSPEC; i++) {
        float t = (float(i) + 0.5) / float(NSPEC);          // 0 red .. 1 violet
        vec3 sw = spectral(t);
        vec2 off = dispDir * spread * (t - 0.5) * 2.0;
        col += texture(u_image0, clamp(baseUv + off, 0.0, 1.0)).rgb * sw;
        wsum += sw;
    }
    col /= max(wsum, vec3(1e-4));

    // ---- Per-facet flat shading: each crystal face catches the light ----
    if (mode == 1 && u_shading > 0.0) {
        vec2 nt = (hash22(cid + 2.0) - 0.5) * 1.5;     // random face tilt
        vec3 nrm = normalize(vec3(nt, 1.0));
        vec3 L = normalize(vec3(0.5, 0.55, 0.7));
        float diff = clamp(dot(nrm, L), 0.0, 1.0);
        float spec = pow(diff, 22.0);
        col *= mix(1.0, 0.55 + 0.8 * diff + 0.7 * spec, u_shading);
    }

    // ---- Edge glint, tinted toward the dispersion rainbow ----
    float hue = atan(p.y, p.x) / TAU + 0.5 + shim * 0.1;
    vec3 rainbow = 0.5 + 0.5 * cos(TAU * (hue + vec3(0.0, 0.33, 0.66)));
    vec3 tint = mix(vec3(1.0), rainbow, clamp(u_dispersion * 8.0, 0.0, 1.0));
    col += seam * u_glint * tint;

    fragColor0 = vec4(col, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uint pcg(uint v) { v = v * 747796405u + 2891336453u; v = ((v >> ((v >> 28u) + 4u)) ^ v) * 277803737u; return (v >> 22u) ^ v; }
float hash2(vec2 ip, float seed) {
    uvec2 q = uvec2(ivec2(ip) + 32768);
    uint h = pcg(q.x ^ pcg(q.y ^ pcg(uint(int(seed)))));
    return float(h) * (1.0 / 4294967295.0);
}
float vnoise(vec2 p, float seed) {
    vec2 i = floor(p), f = fract(p);
    vec2 u2 = f * f * (3.0 - 2.0 * f);
    float a = hash2(i, seed), b = hash2(i + vec2(1, 0), seed);
    float c = hash2(i + vec2(0, 1), seed), d = hash2(i + vec2(1, 1), seed);
    return mix(mix(a, b, u2.x), mix(c, d, u2.x), u2.y);
}
float fbm(vec2 p, float seed) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 4; i++) { v += a * vnoise(p, seed + float(i) * 17.0); p *= 2.03; a *= 0.5; }
    return v;
}

uniform float u_amount;
uniform float u_scale;
uniform float u_speed;

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    vec2 p = v_texCoord * asp * u_scale;
    float t = u_time * u_speed;
    vec2 q = vec2(
        fbm(p + vec2(0.0, 0.0) + 0.30 * t, u_seed),
        fbm(p + vec2(5.2, 1.3) - 0.20 * t, u_seed + 7.0)
    );
    vec2 w = vec2(
        fbm(p + 2.0 * q + vec2(1.7, 9.2) + 0.15 * t, u_seed + 13.0),
        fbm(p + 2.0 * q + vec2(8.3, 2.8), u_seed + 29.0)
    );
    vec2 off = (w - 0.5) * 2.0 * u_amount;
    fragColor0 = vec4(texture(u_image0, clamp(v_texCoord + off, 0.0, 1.0)).rgb, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_size;

void main() {
    vec2 cellPx = vec2(max(u_size * u_resolution.y, 1.0));
    vec2 px = v_texCoord * u_resolution;
    vec2 cuv = (floor(px / cellPx) + 0.5) * cellPx / u_resolution;
    fragColor0 = vec4(texture(u_image0, clamp(cuv, 0.0, 1.0)).rgb, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_thickness;
uniform float u_threshold;
uniform float u_softness;
uniform float u_intensity;
uniform float u_background;

float lum(vec2 uv) {
    return dot(texture(u_image0, clamp(uv, 0.0, 1.0)).rgb, vec3(0.299, 0.587, 0.114));
}

void main() {
    vec2 s = vec2(max(u_thickness * u_resolution.y, 0.5)) / u_resolution;
    float tl = lum(v_texCoord + vec2(-s.x,  s.y)), t = lum(v_texCoord + vec2(0.0,  s.y)), tr = lum(v_texCoord + vec2(s.x,  s.y));
    float l  = lum(v_texCoord + vec2(-s.x,  0.0)),                                        r  = lum(v_texCoord + vec2(s.x,  0.0));
    float bl = lum(v_texCoord + vec2(-s.x, -s.y)), b = lum(v_texCoord + vec2(0.0, -s.y)), br = lum(v_texCoord + vec2(s.x, -s.y));
    float gx = (tr + 2.0 * r + br) - (tl + 2.0 * l + bl);
    float gy = (tl + 2.0 * t + tr) - (bl + 2.0 * b + br);
    float e = length(vec2(gx, gy));
    float m = smoothstep(u_threshold, u_threshold + max(u_softness, 1e-3), e) * u_intensity;
    vec3 base = texture(u_image0, v_texCoord).rgb * u_background;
    fragColor0 = vec4(clamp(base + vec3(m), 0.0, 1.0), 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uint pcg(uint v) { v = v * 747796405u + 2891336453u; v = ((v >> ((v >> 28u) + 4u)) ^ v) * 277803737u; return (v >> 22u) ^ v; }
float hash2(vec2 ip, float seed) {
    uvec2 q = uvec2(ivec2(ip) + 32768);
    uint h = pcg(q.x ^ pcg(q.y ^ pcg(uint(int(seed)))));
