        vec3 tinted = img * (0.4 + 1.2 * field);            // field modulates the image colour
        fragColor0 = vec4(clamp(mix(img, tinted, u_mix), 0.0, 1.0), 1.0);
    } else {
        // No input: the pure generative field.
        fragColor0 = vec4(field, 1.0);
