float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i), b = hash21(i + vec2(1.0, 0.0)), c = hash21(i + vec2(0.0, 1.0)), d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p) { float s = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { s += a * vnoise(p); p = p * 2.03 + 5.2; a *= 0.5; } return s; }

// Iridescent palette — smooth red->violet->red rainbow (oil-slick / thin film).
vec3 iridPalette(float t) {
    return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.66)));
}

void main() {
    vec2 texel = 1.0 / u_resolution;
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    vec2 p = (v_texCoord - 0.5) * asp;
    vec3 base = texture(u_image0, v_texCoord).rgb;
    float lum = dot(base, LUMA);

    // Pseudo-surface-normal from the luminance gradient → view-dependent shift.
    float lx = dot(texture(u_image0, clamp(v_texCoord + vec2(texel.x, 0.0), 0.0, 1.0)).rgb, LUMA)
             - dot(texture(u_image0, clamp(v_texCoord - vec2(texel.x, 0.0), 0.0, 1.0)).rgb, LUMA);
    float ly = dot(texture(u_image0, clamp(v_texCoord + vec2(0.0, texel.y), 0.0, 1.0)).rgb, LUMA)
             - dot(texture(u_image0, clamp(v_texCoord - vec2(0.0, texel.y), 0.0, 1.0)).rgb, LUMA);
    vec3 N = normalize(vec3(-lx, -ly, 0.5));

    float view = radians(u_angle) + u_time * u_shimmer;
    vec3 V = normalize(vec3(sin(view) * 0.7, cos(view) * 0.7, 1.0));
    float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 3.0);   // glancing-angle sheen

    // Foil-surface texture: a subtle modulation of the interference phase, NOT a
    // replacement for the image. Luminance always drives the main hue banding so
    // the subject stays readable under the sheen.
    int pat = int(u_pattern + 0.5);
    float field = 0.0;
    if (pat == 1)      field = fbm(vec2(p.x * 70.0, p.y * 2.5) + u_seed) - 0.5;       // brushed streaks
    else if (pat == 2) field = fbm(p * 11.0 + u_seed) - 0.5;                          // crinkled foil
    else if (pat == 3) field = sin(length(p) * 26.0 - view * 2.0) * 0.5;             // ripples

    float phase = (lum * 2.2 + field * 0.6 + fres * 1.0) * u_bands + view * 0.5 + u_seed;
    vec3 irid = iridPalette(phase);

    // Sheen = gloss: flat matte foil at 0, wet/shiny foil with a specular hotspot
    // at 1. Applies to BOTH the translucent and metallic looks.
    float g = 0.4 + u_sheen * 1.6;
    vec3 spec = vec3(pow(fres, 3.0) * u_sheen * 1.6);

    vec3 foilTranslucent = base + irid * (fres * 0.6 + 0.25) * g + spec;
    vec3 foilMetallic = irid * (0.3 + 1.15 * lum) * g + spec;
    vec3 col = mix(base, mix(foilTranslucent, foilMetallic, u_metallic), u_iridescence);

    // Shimmer = holographic glitter: a static sparkle (so the slider responds on a
    // still frame) that re-twinkles over time, layered on the hue drift via `view`.
    if (u_shimmer > 0.0) {
        float tw = fbm(p * 130.0 + floor(u_time * 6.0) * 1.7 + u_seed);
        float spark = smoothstep(0.52, 0.82, tw) * u_shimmer;
        col += spark * mix(vec3(1.0), irid, 0.4) * (1.0 + u_iridescence);
    }

    fragColor0 = vec4(clamp(col, 0.0, 1.0), 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_hasInput;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_surface;     // 0 soft sweep, 1 watercolour bloom, 2 sweep+sparkle, 3 defined bands
uniform float u_scale;       // size of the bend / bloom / sparkle field
uniform float u_iridescence; // how strongly the rainbow tints the silver
uniform float u_bands;       // hue cycles across the sheet
uniform float u_angle;       // which way the sheet is tilted: rotates sweep + sheen
uniform float u_shimmer;     // time drift of the hue + a fine twinkle
uniform float u_metallic;    // REPURPOSED -> "Silver wash": how much neutral foil breaks through
uniform float u_sheen;       // matte -> polished: strength of the broad light band
uniform vec3  u_tint;        // the pale foil under the rainbow
uniform float u_crinkle;     // crumpled-foil facet texture (0 = smooth sheet)
uniform float u_mix;         // blend the input back in (0 = pure foil)
uniform float u_glow;        // paint look (0) <-> pearlescent light look (1): bright AND saturated

// Look constants settled against the reference photos. Not dials: each was tried as one
// and the reference sat at a single value.
const float OVERLAP = 0.7;      // how much the second and third rainbows show through the first
const float BAND_SHAPE = 0.8;   // 0 = rounded blooms, 1 = long wavy parallel bands
const float CRINKLE_MAX = 0.4;  // full dial = this much facet texture; more reads as wet stone

// TARGET, from the user's reference photographs of holographic STICKER VINYL --
// the pale iridescent sheet stock that die-cut stickers and laminates are printed
// on (a stack of holographic discs, a roll of security-hologram labels, a fan of
// blank sheet stock). The three things those photographs share:
//
//   HIGH KEY      a pale silver-white base carries the whole image; very little dark
//   LOW SATURATION  pastel blooms, ~0.15-0.35 mean saturation, not neon
//   BROAD, SMOOTH   few large features, essentially no small detail
//
// This is close to the inverse of the diffraction foil this file used to hold
// (Crumple / Grating / Flakes / Slick -- CD undersides and glitter vinyl), which
// was built, rendered and rejected: "none of it looks like what I'm looking for."
// That version derived every colour from a SURFACE NORMAL and a fresnel, and a
// "make it read as metal" pass had driven luminance p1 to 0.087 -- directly away
// from the target. None of that machinery survives; these four surfaces are smooth
// colour fields floating over a silver base, which is what the reference actually is.

const float TAU = 6.28318530718;

// hash21 / vnoise / iridPalette are still lifted verbatim from holographic.frag, so
// the two effects remain literally the same noise and the same palette -- siblings,
// not lookalikes.
float hash21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i), b = hash21(i + vec2(1.0, 0.0)), c = hash21(i + vec2(0.0, 1.0)), d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
// TWO octaves, where the rejected version ran four. The reference photographs have
// almost no small detail in them: every octave past the second reads as grain, and
// grain is what made the first attempt look like static rather than like vinyl.
float softfbm(vec2 p) { return 0.72 * vnoise(p) + 0.28 * vnoise(p * 2.03 + 5.2); }

// Cellular facets. Returns (distance to nearest site, border distance F2-F1, cell hash).
vec3 facets(vec2 x) {
    vec2 n = floor(x), f = fract(x);
    float d1 = 8.0, d2 = 8.0, id = 0.0;
    for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
        vec2 g = vec2(float(i), float(j));
        vec2 o = vec2(hash21(n + g), hash21(n + g + 19.1));
        vec2 r = g + o - f;
        float d = dot(r, r);
        if (d < d1) { d2 = d1; d1 = d; id = hash21(n + g + 3.3); }
        else if (d < d2) { d2 = d; }
    }
    return vec3(sqrt(d1), sqrt(d2) - sqrt(d1), id);
}
vec3 iridPalette(float t) { return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.66))); }

// The core move of the whole look. The rainbow TINTS a pale foil; it does not
// replace it. Two steps, and both are needed:
//   1. whiten the hue hard (0.62 toward white) so the palette lands in the pastel
//      range the reference sits in rather than at full cosine-palette chroma;
//   2. mix that pastel over the silver by only a moderate amount.
// Written the obvious way instead -- palette straight into the output -- the surface
// measures ~0.6 mean saturation and reads as a printed rainbow, which is precisely
// the note the user rejected.
vec3 vinyl(vec3 hue, float tintAmount, float shade, vec3 silverBase) {
    vec3 silver = silverBase * shade;
    // The reference has no neutral grey anywhere: the calmest areas carry a pale cyan or
    // lavender, and a truly neutral silver reads as a dead zone against that. So the silver
    // takes on a PALE version of the local hue -- normalised to full value so the tint is
    // colour and not darkening, then whitened hard. Still silver; silver that remembers
    // which rainbow is passing over it.
    vec3 hueN = hue / max(max(hue.r, hue.g), max(hue.b, 1e-3));
    silver *= mix(vec3(1.0), hueN, 0.30);
    // "Paint" look (u_glow = 0): pastel mixed toward white, moderate value,
    // desaturated. Reads matte.
    vec3 pastel = mix(vec3(1.0), hue, 0.58);
    vec3 paintLook = mix(silver, pastel * shade, tintAmount);
    // "Light" look (u_glow = 1): the rainbow is LIGHT added onto the silver, at full
    // chroma. This is how a pearlescent film actually works (interference adds
    // light), and it is the only way colour can be bright AND saturated at once.
    // The silver stays grey underneath; the colour rises above it instead of
    // diluting it. Two alternatives were tried and rejected first: linear-additive
    // light on the silver base clipped every channel to white and DESATURATED
    // (measured: sat 0.26 -> 0.08 as glow rose); a plain lerp toward the raw hue
    // just diluted the silver the same way the paint look already does. Bright-and-
    // saturated has to be built the other way: push the palette colour to high
    // VALUE while keeping its chroma ratios -- normalise to its max channel, then
    // scale to 0.96 -- and mix the silver toward THAT. No channel ever exceeds
    // 0.96, so nothing clips and the hue stays fully saturated.
    float mx = max(hue.r, max(hue.g, hue.b));
    vec3 bright = hue / max(mx, 1e-3) * 0.96;
    vec3 lightLook = mix(silver, bright * shade, tintAmount);
    return mix(paintLook, lightLook, u_glow);
}

// SILVER WASH-OUT. The reference is not tinted edge to edge: the rainbow retreats
// across whole regions and leaves neutral foil behind, and that retreat is most of
// what separates "foil catching a rainbow" from "printed rainbow gradient".
//
// The window has to be TIGHT, and it has to sit ON softfbm's actual mid-range.
// softfbm concentrates hard around 0.5 (measured std ~0.115), so a wide window such
// as smoothstep(0.28, 0.72, n) never reaches zero anywhere in the frame -- the mask
// floors out around 0.2, every pixel stays tinted, and no silver appears at all.
// That was the first probe's failure. `wash` slides a narrow 0.15-wide window up
// through the distribution: at 0 it sits below the whole field (everything tinted),
// at 1 it sits above most of it (mostly bare foil).
float silverMask(vec2 q, float wash) {
    float n = softfbm(q * 1.15 + 7.3);
    float lo = mix(0.14, 0.64, wash);
    return smoothstep(lo, lo + 0.14, n);
}

// SHEEN. Broad luminance variation across the sheet, so it reads as a physical
// surface lying under a light rather than as a printed gradient. The first probe
// round spanned only 0.64 -> 0.82 and looked printed for exactly this reason. Two
// gaussian bands, both wide: a main one through the middle and a weaker secondary
// off to one side, the way a sheet of laminate picks up a window and its reflection.
float sheenBand(vec2 r, float gloss) {
    float t = r.y * 0.92 + r.x * 0.34;
    float core = exp(-t * t * 5.0);
    float second = exp(-(t - 0.60) * (t - 0.60) * 14.0);
    float amp = 0.24 + 0.30 * gloss;
    return 0.79 + amp * core + (0.06 + 0.10 * gloss) * second;
}

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    vec2 p = (v_texCoord - 0.5) * asp;

    int mode = int(u_surface + 0.5);
    float ang = radians(u_angle);
    // Rotate into the sheet's own frame once, and let everything downstream work in
    // it. Tilting a holographic sheet turns the whole optical structure together --
    // sweep, bands and sheen -- so one rotation here is more faithful than rotating
    // each feature separately, and it keeps u_angle live in the bloom mode too,
    // which has no direction of its own to rotate.
    float ca = cos(ang), sa = sin(ang);
    vec2 r = vec2(p.x * ca + p.y * sa, -p.x * sa + p.y * ca);

    // Two-part fold: the residue keeps the field inputs small (hash21 quantises once its
    // inputs pass ~2^24 -- the app sends seed % 10000, and seeds above ~5000 used to collapse
    // the field to a flat plane), and the quotient, scaled by an irrational-ish step, keeps
    // every seed in 0..9999 distinct instead of repeating every 97. Seed 42 folds to 42.0.
    float sd = mod(u_seed, 97.0) + floor(u_seed / 97.0) * 0.3711;
    vec2 q = r * (u_scale * 0.52) + vec2(sd * 0.137, sd * 0.311);

    // One slow undulation, used only to bend the sweep and to shade very slightly.
    float f = softfbm(q * 0.55);
    // Time drift of the hue. On a still frame this is zero, which is why the twinkle
    // below exists as well -- otherwise Shimmer would be a dead control everywhere
    // the app renders a single frame.
    float drift = u_time * u_shimmer * 0.22;

    float sheen = sheenBand(r, u_sheen);
    float shade = (0.91 + 0.09 * (f - 0.5)) * sheen;
    float silver = silverMask(q, u_metallic);
    float tintAmount = u_iridescence * 0.92 * silver;
    // The foil itself. Lifted 18% toward white so a mid-value Foil tint still lands in
    // the high-key range the reference lives in; the control stays live because the
    // remaining 82% carries the colour through (measured: swapping the pale default
    // for a warm #c88a6a moves the frame by 0.12-0.13 mean).
    vec3 silverBase = mix(u_tint, vec3(1.0), 0.18);
    // u_bands is hue cycles across the sheet, as in the sibling effect.
    float cycles = u_bands * 0.28;

    vec3 col;

    if (mode == 1) {
        // WATERCOLOUR BLOOM -- the dreamier mint-and-pink areas of the blank sheet
        // stock. Two slow noise fields at different scales and no direction at all:
        // soft blooms that drift into one another with barely any structure.
        float a = softfbm(q * 0.80 + 3.1);
        float b = softfbm(q * 0.55 - 1.7);
        vec3 hue = iridPalette((a * 1.30 + b * 0.72) * cycles * 0.85 + drift);
        col = vinyl(hue, tintAmount * 0.90, shade * 0.96, silverBase);
    } else if (mode == 3) {
        // DEFINED BANDS -- the banding across the stack of sticker discs: the same
        // sweep at tighter repeats, and shaped so the colours sit in distinct runs.
        // The shaping term is a sine of the phase added back to it, which widens the
        // plateaus and narrows the crossings; a hard quantise gives the same runs but
        // with stair-stepped edges the reference does not have.
        float t = (r.x * 0.95 + r.y * 0.28) * 2.9 + (f - 0.5) * 0.40;
        float phase = t * cycles + drift;
        phase += 0.17 * sin(TAU * phase);
        col = vinyl(iridPalette(phase), tintAmount * 1.05, shade, silverBase);
    } else {
        // SOFT SWEEP (0) and SWEEP AND SPARKLE (2) share the field: one broad rainbow
        // band running across the sheet, bent gently by the slow noise.
        // The reference colour comes in LONG, soft, roughly parallel bands with a gentle
        // waver -- a stretched diagonal spectrum -- not rounded blooms. Blooms come from an
        // isotropic fbm bend that pushes the sweep equally in every direction. Bands need
        // the displacement small ACROSS the band and long ALONG it: sample the bend field
        // stretched along the band axis so the waver is slow and elongated.
        vec2 band = vec2(r.x * 1.05 + r.y * 0.30, -r.x * 0.30 + r.y * 1.05);  // across, along
        float wav = softfbm(vec2(band.y * 0.9, band.x * 3.4) * (u_scale * 0.52) + sd * 0.2) - 0.5;
        float bend = mix((f - 0.5) * 0.55, wav * 0.42, BAND_SHAPE);
        float t = band.x + bend;
        float phase = t * cycles + 0.15 + drift;
        vec3 hue = iridPalette(phase);
        // A single hue ramp gives every colour its own zone -- a perfect gradient, which
        // the reference is not. Real holographic film reads as two or three OFFSET rainbows
        // laid over each other semi-transparently: a pink bloom sits over a cyan one and
        // both are visible. So: two more rainbow layers, each bent by its OWN slow field so
        // it does not track the first, screen-blended in -- screen keeps both colours where
        // they overlap and pales the mix instead of averaging them to mud. The glow path
        // re-normalises brightness afterwards, so screen raising the value cannot blow out.
        {
            float f2 = softfbm(q * 0.50 + 17.3);
            float wav2 = softfbm(vec2(band.y * 0.8, band.x * 3.0) * (u_scale * 0.52) + 17.3) - 0.5;
            float t2 = (r.x * 0.95 + r.y * 0.42) + mix((f2 - 0.5) * 0.55, wav2 * 0.40, BAND_SHAPE);
            vec3 hue2 = iridPalette(t2 * cycles * 0.85 + 0.42 + drift);
            float f3 = softfbm(q * 0.62 - 9.1);
            float wav3 = softfbm(vec2(band.y * 1.1, band.x * 3.8) * (u_scale * 0.52) - 9.1) - 0.5;
            float t3 = (r.x * 1.12 - r.y * 0.18) + mix((f3 - 0.5) * 0.50, wav3 * 0.36, BAND_SHAPE);
            vec3 hue3 = iridPalette(t3 * cycles * 1.10 + 0.71 + drift);
            vec3 layered = 1.0 - (1.0 - hue) * (1.0 - hue2 * 0.85);
            layered = 1.0 - (1.0 - layered) * (1.0 - hue3 * 0.55);
            hue = mix(hue, layered, OVERLAP);
        }
        col = vinyl(hue, tintAmount, shade, silverBase);
        if (mode == 2) {
            // SWEEP AND SPARKLE -- the security-hologram label roll. Fine, SPARSE and
            // TINTED, not white: real prismatic glitter takes its colour from the film
            // it sits in. The rejected version's grain was dense and neutral and read
            // as sensor noise over the picture.
            // Tied to the PIXEL grid, not to `p`: at a fixed multiple of p the dot
            // pitch falls below one pixel on any sizeable render and the glitter
            // degenerates into aliasing hash, whose character then changes with the
            // output size. Anchored to u_resolution it is a ~3px sparkle at every
            // size, which is what fine prismatic glitter reads as on screen.
            vec2 gp = p * (u_resolution.y / 3.2);
            // Per-CELL hash with a round falloff, not vnoise: interpolated value noise
            // clusters its peaks, so a threshold over it gives drifts and clumps of
            // specks that read as dust on the sheet. Glitter is independent flakes
            // scattered evenly, which is what one hash per cell gives.
            vec2 cell = floor(gp);
            float grain = hash21(cell + sd * 13.0);
            // Jittered off the cell centre, or the flakes sit on a visible lattice.
            vec2 jit = (vec2(hash21(cell + 5.1), hash21(cell + 9.3)) - 0.5) * 0.70;
            // descending smoothstep is undefined in GLSL ES; written as 1 - ascending
            float flake = (1.0 - smoothstep(0.0, 0.55, length(fract(gp) - 0.5 - jit)));
            float spark = smoothstep(0.90, 0.998, grain) * flake;
            col += spark * mix(vec3(1.0), iridPalette(phase + 0.35), 0.72)
                         * (0.18 + 0.22 * u_sheen);
        }
    }

    // Shimmer's still-frame half: a twinkle that re-rolls over time, so the slider
    // does something on a single frame -- most of the app renders one -- and so an
    // animated fill has some life in its highlights. It is the COVERAGE that carries
    // the slider, not the brightness: the threshold slides from very sparse to broad,
    // which lets the default sit almost invisible (0.024 of range over ~3% of the
    // frame) while the top of the range is unmistakable. Driving amplitude alone
    // instead measured a mean difference of 0.0008 end to end -- a dead control on
    // any still frame. Pitched at ~2.5px; at 5px it read as dust lying on the sheet,
    // and the reference has essentially no small detail outside the sparkle surface.
    if (u_shimmer > 0.0) {
        // Fold the same way as the seed above: hash21 quantises once its inputs pass
        // ~2^24, and a wall-clock driver like Shape Studio can run for hours, so the
        // raw unfolded index would eventually overflow float precision and flatten.
        float tw = vnoise(p * (u_resolution.y / 2.6) + mod(floor(u_time * 6.0) * 1.7, 97.0) + sd * 7.0);
        float glint = smoothstep(mix(0.95, 0.60, u_shimmer), 0.995, tw)
                    * u_shimmer * (0.05 + 0.09 * u_sheen);
        col += glint * mix(vec3(1.0), iridPalette(f * 2.0 + drift), 0.45);
    }

    // Broad soft sheen: a gentle lift that follows the sweep direction, never a
    // hotspot. Exponent 1.4 spans most of the frame (broad); a tight streak at
    // exponent 90 was tried and rejected for looking like a hotspot rather than
    // the sheet catching light.
    if (u_glow > 0.0) {
        vec2 sdir = vec2(cos(radians(u_angle + 90.0)), sin(radians(u_angle + 90.0)));
        float ts = dot(p, sdir) + (f - 0.5) * 0.6;
        col *= 1.0 + u_glow * 0.18 * exp(-ts * ts * 1.4);
    }
    // Crinkle: the dense fine texture of crumpled foil. Foil is FACETED -- small flat planes,
    // each catching the light a bit differently, with thin bright/dark crease lines where they
    // meet -- so this is cellular, not noise (a noise grid at this density reads as pixels).
    // Two facet scales: the small folds, and the finer crease network inside them. The colour
    // field underneath is untouched; facets modulate brightness plus a faint per-facet hue
    // shift, which is what a tilted facet does to a thin film. Isotropic by construction.
    float crinkle = u_crinkle * CRINKLE_MAX;
    if (crinkle > 0.0) {
        vec3 fa = facets(p * 22.0 + sd * 3.0);
        vec3 fb = facets(p * 58.0 + sd * 5.0 + 11.0);
        float tiltA = fa.z - 0.5, tiltB = fb.z - 0.5;                 // per-facet flat tilt, +-0.5
        float tilt = tiltA * 0.55 + tiltB * 0.45;
        float crease = (1.0 - smoothstep(0.0, 0.10, fb.y)) * 0.6 + (1.0 - smoothstep(0.0, 0.07, fa.y)) * 0.4;
        float catching = smoothstep(0.20, 0.40, tilt);                // facets that catch the light
        col *= 1.0 + crinkle * (0.30 * tilt + 0.14 * catching);       // pits darken, facets brighten
        col += crinkle * crease * (0.24 * tiltB + 0.06);                     // creases: some bright, some dark
        // a tilted facet shifts the film's hue slightly: nudge toward the neighbouring colour
        vec3 shifted = 1.0 - (1.0 - col) * (1.0 - iridPalette(tilt * 1.6 + 0.4) * 0.35);
        col = mix(col, shifted, crinkle * catching * 0.6);
    }
    col = clamp(col, 0.0, 1.0);
    if (u_hasInput > 0.5 && u_mix > 0.0) {
        col = mix(col, texture(u_image0, v_texCoord).rgb, u_mix);
    }
    fragColor0 = vec4(col, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_hasInput;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// PRISM: a thin white beam enters at the source, runs to the split point, then
// fans out into a rainbow that widens and fades with distance. A port of the
// Shaders.com "Prism" component (default preset "Fluid Chrome").
//
// Coordinates: v_texCoord.y = 1 is the visual TOP, so Source/Split Y follow the
// same convention as every other centre handle in the catalog.

uniform float u_sourceX;      // where the beam starts
uniform float u_sourceY;
uniform float u_splitX;       // where the white beam breaks into colour
uniform float u_splitY;
uniform float u_beamWidth;    // thickness of the white core
uniform float u_intensity;    // brightness; above 1 blows the core to white
uniform vec3  u_beamColor;    // colour of the beam before it splits
uniform float u_startFalloff; // how softly the beam fades in at its source
uniform float u_endFalloff;   // how quickly the rainbow fades with distance
uniform float u_spread;       // how wide the rainbow fans past the split
uniform float u_softness;     // length of the white-to-rainbow transition
uniform float u_saturation;   // 0 = stays white, 1 = full colour

const float HUE_DRIFT = 0.1;  // hue rotation per second of u_time (the wrapper Speed scales it)

vec3 hue2rgb(float h) {
    vec3 k = mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0);
    return clamp(abs(k - 3.0) - 1.0, 0.0, 1.0);
}

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    vec2 p   = v_texCoord * asp;
    vec2 src = vec2(u_sourceX, u_sourceY) * asp;
    vec2 spl = vec2(u_splitX,  u_splitY)  * asp;

    // Beam axis: along = signed distance from the source, across = perpendicular offset.
    vec2 axis = spl - src;
    float len = max(length(axis), 1e-4);
    vec2 dir  = axis / len;
    vec2 rel  = p - src;
    float along  = dot(rel, dir);
    float across = dot(rel, vec2(-dir.y, dir.x));

    float soft = max(u_softness, 0.001);

    // How far past the split point we are, in axis lengths, eased in over the softness.
    float t = along / len;
    float past = max(t - 1.0, 0.0) * smoothstep(1.0 - soft * 0.6, 1.0 + soft * 0.6, t);

    // Lengthwise envelope: fade in from the source, fade out beyond the split.
    float longEnv = smoothstep(0.0, max(u_startFalloff, 0.001), along)
                  * exp(-past / max(u_endFalloff, 0.001));

    // The beam widens as it travels past the split.
    float width = max(u_beamWidth + past * u_spread, 0.001);
    float an    = across / width;
    float core  = exp(-pow(abs(an), 2.5));

    // Colour: white core, rainbow across the fan once past the split.
    float colourIn = smoothstep(len, len + soft * len, along);
    float hue = an * 0.42 + u_time * HUE_DRIFT;
    vec3 rgb = mix(u_beamColor, hue2rgb(fract(hue)), colourIn * clamp(u_saturation, 0.0, 1.0));

    float amt = core * longEnv;
    vec3 beam = rgb * amt * u_intensity;
    float a   = clamp(amt, 0.0, 1.0);

    if (u_hasInput > 0.5) {
        // Light adds over whatever sits beneath.
        vec4 base = texture(u_image0, v_texCoord);
        fragColor0 = vec4(clamp(base.rgb + beam, 0.0, 1.0), max(base.a, a));
    } else {
        fragColor0 = vec4(clamp(beam, 0.0, 1.0), a);
    }
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// GLASS LENS: a round pane of thick glass over the input. The rim refracts what is
// beneath (pulling the picture inward the way a lens edge does), splits the colours
// along the bend, and carries a directional highlight and a soft fresnel rim.
// A port of the Shaders.com "Glass" component (circle shape); its default preset
// is the "Fluid Chrome" design.
//
// Used as a Frame lens, the whole backdrop is the input and the Frame also hands
// over the layer's silhouette as a soft height field (u_shape), so the rim, bend and
// highlight follow the real shape; Center and Radius then describe only the
// stand-alone circle (u_hasShape = 0).

uniform float u_centerX;         // lens centre
uniform float u_centerY;
uniform float u_radius;          // lens radius as a fraction of the shorter side
uniform float u_refraction;      // how hard the rim bends what is beneath
uniform float u_thickness;       // how far inward from the rim the bend reaches
uniform float u_aberration;      // colour split along the bend
uniform float u_innerZoom;       // magnification of the picture seen through the glass
uniform float u_edgeSoftness;    // fade width at the boundary
uniform float u_blur;            // frosting inside the glass, in pixels
uniform float u_lightAngle;      // where the light comes from, degrees
uniform float u_highlight;       // strength of the rim highlight facing the light
uniform float u_highlightSoftness;
uniform vec3  u_highlightColor;
uniform float u_fresnel;         // even glow around the rim
uniform float u_fresnelSoftness; // how far the glow reaches inward
uniform vec3  u_fresnelColor;
uniform float u_cutout;          // 0 keep the input outside the glass, 1 make it transparent

// Supplied by the Frame when the effect follows a layer's shape (manifest followsShape):
// a blurred silhouette (0 outside, 1 deep inside, 0.5 on the edge), plus the shape's
// centre (texture space, y up) and its half short side as a fraction of the shorter
// canvas side, which stands in for Radius.
uniform sampler2D u_shape;
uniform float u_hasShape;
uniform float u_shapeCX;
uniform float u_shapeCY;
uniform float u_shapeSize;

vec3 sampleLens(vec2 uv, float px) {
    // A small disc blur for frosting; a single tap when clear.
    if (px < 0.25) return texture(u_image0, uv).rgb;
    vec2 s = px / u_resolution;
    vec3 acc = texture(u_image0, uv).rgb * 2.0;
    acc += texture(u_image0, uv + vec2( 1.0,  0.0) * s).rgb;
    acc += texture(u_image0, uv + vec2(-1.0,  0.0) * s).rgb;
    acc += texture(u_image0, uv + vec2( 0.0,  1.0) * s).rgb;
    acc += texture(u_image0, uv + vec2( 0.0, -1.0) * s).rgb;
    acc += texture(u_image0, uv + vec2( 0.7,  0.7) * s).rgb;
    acc += texture(u_image0, uv + vec2(-0.7,  0.7) * s).rgb;
    acc += texture(u_image0, uv + vec2( 0.7, -0.7) * s).rgb;
    acc += texture(u_image0, uv + vec2(-0.7, -0.7) * s).rgb;
    return acc / 10.0;
}

void main() {
    vec4 base = texture(u_image0, v_texCoord);
    // Aspect-corrected space where a circle is round and the shorter side is 1.
    float shortSide = min(u_resolution.x, u_resolution.y);
    vec2 asp = u_resolution / shortSide;
    vec2 p = v_texCoord * asp;
    vec2 c, n, rel;
    float R, cover, depth;
    if (u_hasShape > 0.5) {
        // Shape mode: the height field carries the edge. Its blur radius is the glass
        // thickness, so 0.5 is the rim and 1.0 is one thickness inside.
        c = vec2(u_shapeCX, u_shapeCY) * asp;
        R = max(u_shapeSize, 0.001);
        rel = p - c;
        vec4 sh = texture(u_shape, v_texCoord);
        float h = sh.r;
        vec2 px = 1.5 / u_resolution;
        float gx = texture(u_shape, v_texCoord + vec2(px.x, 0.0)).r - texture(u_shape, v_texCoord - vec2(px.x, 0.0)).r;
        float gy = texture(u_shape, v_texCoord + vec2(0.0, px.y)).r - texture(u_shape, v_texCoord - vec2(0.0, px.y)).r;
        vec2 g = vec2(gx, gy) / asp;        // gradient in the round space; points inward
        float gl = length(g);
        n = gl > 1e-6 ? -g / gl : vec2(0.0, 1.0);
        depth = clamp((h - 0.5) * 2.0, 0.0, 1.0);
        // Coverage reads the true distance field (G), not the blurred rim: a thin
        // arm of a star blurs below the halfway level and would otherwise drop out.
        // Paint solid: the compositor clips this fill to the layer's FULL-RES silhouette
        // (destination-in in applyGlassFromLayer), so that crisp clip IS the outline. A cover that
        // fades near the edge here renders at LIVE_FIELD_PX, upscales soft, and then multiplies the
        // crisp clip — softening the edge (see chrome). Let the clip cut it.
        cover = 1.0;
    } else {
        c = vec2(u_centerX, u_centerY) * asp;
        R = max(u_radius, 0.001);
        rel = p - c;
        float r = length(rel);
        n = r > 1e-5 ? rel / r : vec2(0.0, 1.0);
        float d = r - R;                      // signed distance to the rim, negative inside

        // Coverage: solid inside, fading over the edge softness.
        float soft = max(u_edgeSoftness, 0.001) * R;
        cover = 1.0 - smoothstep(0.0, soft, d);

        // Bend: zero at the centre, strongest at the rim, over the glass thickness.
        depth = clamp(-d / (max(u_thickness, 0.001) * R), 0.0, 1.0);
    }
    float bend = 1.0 - depth;
    bend = bend * bend;

    // Refract: pull the sample inward along the normal, plus the inner zoom about the centre.
    float pull = bend * u_refraction * R * 0.5;
    vec2 q = c + rel / max(u_innerZoom, 0.1);
    vec2 baseUv = q / asp;
    vec2 shift = -n * pull / asp;
    float ab = u_aberration * 0.25;
    vec3 col;
    col.r = sampleLens(clamp(baseUv + shift * (1.0 + ab), 0.0, 1.0), u_blur).r;
    col.g = sampleLens(clamp(baseUv + shift,              0.0, 1.0), u_blur).g;
    col.b = sampleLens(clamp(baseUv + shift * (1.0 - ab), 0.0, 1.0), u_blur).b;

    // Directional highlight: a band just inside the rim, on the side facing the light.
    float ang = radians(u_lightAngle);
    // Degrees run clockwise from the right as on screen; v_texCoord.y = 1 is the visual top.
    vec2 L = vec2(cos(ang), -sin(ang));
    float facing = max(dot(n, L), 0.0);
    float hs = mix(24.0, 2.0, clamp(u_highlightSoftness, 0.0, 1.0));
    float rimBand = smoothstep(0.0, 0.35, bend) * (1.0 - smoothstep(0.9, 1.0, bend));
    float glint = pow(facing, hs) * rimBand * u_highlight * 4.0;
    col += u_highlightColor * glint;

    // Fresnel: an even glow that grows toward the rim, reaching inward by its softness.
    float fw = max(u_fresnelSoftness, 0.001);
    float fres = pow(clamp(1.0 - depth, 0.0, 1.0), 1.0 / fw) * u_fresnel;
    col += u_fresnelColor * fres;

    vec3 outside = u_cutout > 0.5 ? vec3(0.0) : base.rgb;
    float aOut = u_cutout > 0.5 ? 0.0 : base.a;
    fragColor0 = vec4(mix(outside, clamp(col, 0.0, 1.0), cover), mix(aOut, 1.0, cover));
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// CRYSTAL: a cut gem over the picture. Flat facets radiate from the centre in
// rings, each one bending the picture its own way, splitting it into a spectrum
// and catching the light on the faces that turn toward it. A port of the
// Shaders.com "Crystal" component (polygon shape); its default preset is the
// "Fluid Chrome" design.
//
// Stand-alone the gem is a regular polygon (Sides, Radius, Center). As a Frame
// lens the Frame hands over the layer's silhouette as a soft height field
// (u_shape, manifest followsShape), so the facets fill whatever shape the layer is.

uniform float u_centerX;
uniform float u_centerY;
uniform float u_radius;          // gem radius as a fraction of the shorter side
uniform float u_sides;           // polygon sides, stand-alone only
uniform float u_facets;          // how many times the facet pattern repeats around the centre
uniform float u_refraction;      // how strongly each facet bends the picture
uniform float u_dispersion;      // spectral split along the bend
uniform float u_innerZoom;       // magnification seen through the gem
uniform float u_edgeSoftness;    // fade at the boundary
uniform float u_lightAngle;      // where the light comes from, degrees clockwise from the right
uniform float u_highlights;      // brightening on faces toward the light, never darkens
uniform float u_shadows;         // darkening on faces away from the light, never brightens
uniform float u_brightness;      // overall push toward brilliant white
uniform float u_fresnel;         // even glow around the rim
uniform float u_fresnelSoftness; // how far the glow reaches inward
uniform vec3  u_fresnelColor;
uniform float u_cutout;          // 0 keep the picture outside the gem, 1 make it transparent

// Supplied by the Frame when the effect follows a layer's shape (see glass_lens).
uniform sampler2D u_shape;
uniform float u_hasShape;
uniform float u_shapeCX;
uniform float u_shapeCY;
uniform float u_shapeSize;

const float TAU = 6.28318530718;
const float PI  = 3.14159265359;

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}
vec2 hash22(vec2 p) { float n = hash21(p); return vec2(n, hash21(p + n)); }

// Visible-spectrum colour for a normalised wavelength (the Zucconi fit crystal_prism uses).
vec3 bump3(vec3 x, vec3 y) { vec3 v = 1.0 - x * x; return clamp(v - y, 0.0, 1.0); }
vec3 spectral(float w) {
    vec3 c1 = vec3(3.54585104, 2.93225262, 2.41593945);
    vec3 x1 = vec3(0.69549072, 0.49228336, 0.27699880);
    vec3 y1 = vec3(0.02312639, 0.15225084, 0.52607955);
    vec3 c2 = vec3(3.90307140, 3.21182957, 3.96587128);
    vec3 x2 = vec3(0.11748627, 0.86755042, 0.66077860);
    vec3 y2 = vec3(0.84897130, 0.88445281, 0.73949448);
    return bump3(c1 * (w - x1), y1) + bump3(c2 * (w - x2), y2);
}

// Signed distance to a regular polygon of circumradius R with n sides, flat side down.
float polygonSDF(vec2 q, float R, float n) {
    float a = atan(q.x, q.y) + PI;
    float seg = TAU / n;
    float d = cos(floor(0.5 + a / seg) * seg - a) * length(q);
    return d - R * cos(seg * 0.5);
}

void main() {
    vec4 base = texture(u_image0, v_texCoord);
    float shortSide = min(u_resolution.x, u_resolution.y);
    vec2 asp = u_resolution / shortSide;
    vec2 p = v_texCoord * asp;

    vec2 c, rel;
    float R, cover, depth;
    if (u_hasShape > 0.5) {
        // Shape mode. R is the rim field (0.5 on the outline, blurred inward); G is
        // the true distance to the outline, 0 on the edge and 1 at the deepest point.
        // Coverage and the facet rings read G, so a star's thin arms are covered
        // and ringed like the rest; the fresnel rim reads R.
        c = vec2(u_shapeCX, u_shapeCY) * asp;
        R = max(u_shapeSize, 0.001);
        rel = p - c;
        vec4 sh = texture(u_shape, v_texCoord);
        depth = clamp((sh.r - 0.5) * 2.0, 0.0, 1.0);
        // Paint solid: the compositor clips this fill to the layer's FULL-RES silhouette
        // (destination-in in applyGlassFromLayer), so that crisp clip IS the outline. A cover that
        // fades near the edge here renders at LIVE_FIELD_PX, upscales soft, and then multiplies the
        // crisp clip — softening the edge (see chrome). Let the clip cut it.
        cover = 1.0;
    } else {
        c = vec2(u_centerX, u_centerY) * asp;
        R = max(u_radius, 0.001);
        rel = p - c;
        float d = polygonSDF(rel, R, max(floor(u_sides + 0.5), 3.0));
        float soft = max(u_edgeSoftness, 0.001) * R;
        cover = 1.0 - smoothstep(0.0, soft, d);
        depth = clamp(-d / (0.35 * R), 0.0, 1.0);   // 0 at the rim, 1 a third of the way in
    }

    // ---- Facets: a kaleidoscope of ringed triangles ----
    // The angle is folded into `facets` mirrored sectors, so the pattern repeats
    // around the centre the way a cut stone does. Inside a sector the space is
    // ringed (rings tighter near the centre) and each ring is split into cells,
    // more of them the further out, each cell cut on its diagonal into two flat
    // triangular faces. A face's normal is seeded, then turned back into the world
    // by the sector it sits in, so the light falls on one side of the gem.
    float r = length(rel);
    // How far out this pixel sits, 0 at the middle and 1 on the outline: the
    // circle's own radius stand-alone, the silhouette's depth when following a shape.
    float rn = u_hasShape > 0.5 ? clamp(1.0 - texture(u_shape, v_texCoord).g, 0.0, 1.0) : clamp(r / R, 0.0, 1.0);
    float ang = atan(rel.y, rel.x);
    float n = max(floor(u_facets + 0.5), 3.0);
    float seg = TAU / n;
    float aw = ang + PI;
    float sector = floor(aw / seg);
    float af = aw - sector * seg;                // 0 .. seg
    float mirror = af > seg * 0.5 ? -1.0 : 1.0;  // second half of the sector is a mirror
    af = min(af, seg - af);                      // folded: 0 .. seg/2

    const float RINGS = 10.0;
    float rk = sqrt(rn) * RINGS;                 // rings tighter toward the centre
    float ring = min(floor(rk), RINGS - 1.0);
    float fr = rk - ring;
    // Cells per half-sector: as many as keep a cell about as wide as its ring is tall,
    // so the faces come out roughly equilateral rather than as thin spokes.
    float rMid = pow((ring + 0.5) / RINGS, 2.0) * R;
    float ringH = ((ring + 1.0) * (ring + 1.0) - ring * ring) / (RINGS * RINGS) * R;
    float m = max(floor(2.0 * rMid * seg * 0.5 / ringH + 0.5), 1.0);
    float u = af / (seg * 0.5) * m;
    float ci = floor(u);
    float fu = u - ci;
    float tri = (fu + fr < 1.0) ? 0.0 : 1.0;
    vec2 cid = vec2(ring * 37.0 + ci, tri + u_seed * 0.173);

    // Face normal in the sector's own frame (radial, tangential), leaning outward
    // more on the outer rings, with a seeded tilt so no two faces match.
    vec2 jit = (hash22(cid) - 0.5) * 1.6;
    float lean = mix(0.1, 0.6, ring / (RINGS - 1.0));
    vec2 nLocal = vec2(lean + jit.x, jit.y * mirror);   // (radial, tangential)
    vec2 outDir = vec2(cos(ang), sin(ang));
    vec2 tanDir = vec2(-outDir.y, outDir.x);
    vec3 nrm = normalize(vec3(outDir * nLocal.x + tanDir * nLocal.y, 1.0));

    // ---- Refraction: each face shifts its slice of the picture along its normal ----
    float mag = 0.6 + 0.4 * hash21(cid + 4.0);
    vec2 shift = -nrm.xy * u_refraction * R * 0.18 * mag;
    vec2 q = c + rel / max(u_innerZoom, 0.1);
    vec2 baseUv = (q + shift) / asp;

    // ---- Dispersion: integrate across the spectrum, each wavelength bent a little differently ----
    vec2 dispDir = length(shift) > 1e-5 ? normalize(shift) / asp : vec2(0.0);
    float spread = u_dispersion * R * 0.1 * mag;
    const int NSPEC = 12;
    vec3 col = vec3(0.0);
    vec3 wsum = vec3(0.0);
    for (int i = 0; i < NSPEC; i++) {
        float t = (float(i) + 0.5) / float(NSPEC);
        vec3 sw = spectral(t);
        vec2 off = dispDir * spread * (t - 0.5) * 2.0;
        col += texture(u_image0, clamp(baseUv + off, 0.0, 1.0)).rgb * sw;
        wsum += sw;
    }
    col /= max(wsum, vec3(1e-4));

    // ---- Lighting: faces toward the light brighten, faces away darken ----
    float la = radians(u_lightAngle);
    vec3 L = normalize(vec3(cos(la), -sin(la), 0.9));      // degrees clockwise as on screen
    float ndl = dot(nrm, L);
    float lit = max(ndl, 0.0);
    float spec = pow(lit, 20.0);
    col += u_highlights * (0.08 * lit + 1.8 * spec);
    col *= 1.0 - u_shadows * max(-ndl, 0.0);
    col *= u_brightness;

    // Seams: a thin light line where faces meet (cell walls, ring walls, the diagonal).
    float cellW = seg * 0.5 / m * r;                      // a cell's angular width in units
    float ringW = ringH;
    float dU = min(fu, 1.0 - fu) * cellW;
    float dR = min(fr, 1.0 - fr) * ringW;
    float dD = abs(fu + fr - 1.0) * 0.7071 * min(cellW, ringW);
    float seamPx = 1.2 / shortSide;
    float seam = 1.0 - smoothstep(0.0, seamPx * 1.5, min(min(dU, dR), dD));
    col += seam * 0.08 * u_brightness;

    // ---- Fresnel rim ----
    float fw = max(u_fresnelSoftness, 0.001);
    float fres = pow(clamp(1.0 - depth, 0.0, 1.0), 1.0 / fw) * u_fresnel;
    col += u_fresnelColor * fres;

    vec3 outside = u_cutout > 0.5 ? vec3(0.0) : base.rgb;
    float aOut = u_cutout > 0.5 ? 0.0 : base.a;
    fragColor0 = vec4(mix(outside, clamp(col, 0.0, 1.0), cover), mix(aOut, 1.0, cover));
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_hasInput;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// STUDIO BACKDROP: a photographer's cove — a wall that curves down into a floor —
// lit by an overhead key light pooling on the stage, two side fills, an upward
// back wash on the wall, an ambient level, and soft ambient lights that drift.
// A port of the Shaders.com "StudioBackground" component (the "Fluid Chrome"
// design's values are the defaults). Generative: it ignores its input.
//
// v_texCoord.y = 1 is the visual top. Percent dials keep the component's 0–100
// ranges so a design's numbers carry over as they are.

uniform vec3  u_surface;         // base surface colour
uniform vec3  u_keyColor;        // overhead key light
uniform float u_keyIntensity;    // 0–100
uniform float u_keySoftness;     // 0–100, how diffuse the key is
uniform vec3  u_fillColor;       // the two side fills
uniform float u_fillIntensity;   // 0–100
uniform float u_fillSoftness;    // 0–100
uniform float u_fillSpread;      // 0–100, how far apart the fills sit
uniform vec3  u_backColor;       // upward wash on the wall
uniform float u_backIntensity;   // 0–100
uniform float u_backSoftness;    // 0–100
uniform float u_ambient;         // 0–100, overall ambient level
uniform float u_vignette;        // 0–100, edge darkening
uniform float u_centerX;         // where the key light meets the floor
uniform float u_centerY;
uniform float u_lightDepth;      // 0–100, spotlights aim at the wall (0) .. the floor (100)
uniform float u_wallCurvature;   // 0–100, how rounded the cove is
uniform float u_ambientDetail;   // 0–100, drifting ambient lights

const float PI = 3.14159265359;

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}
float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i), b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0)), d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p) {
    float s = 0.0, a = 0.5;
    for (int i = 0; i < 4; i++) { s += a * vnoise(p); p = p * 2.03 + 11.7; a *= 0.5; }
    return s;
}

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    vec2 uv = v_texCoord;
    float x = uv.x * asp.x;                    // aspect-corrected
    float v = 1.0 - uv.y;                      // 0 at the visual top, 1 at the bottom
    float sx = u_centerX * asp.x;              // stage centre
    float sv = 1.0 - u_centerY;

    // ---- The cove: wall above the fold, floor below, a soft fold between ----
    float fold = sv - 0.05;                                        // where wall meets floor
    float cw = mix(0.01, 0.16, u_wallCurvature / 100.0);           // how rounded the fold is
    float isFloor = smoothstep(fold - cw, fold + cw, v);
    float wallT = clamp(v / max(fold, 1e-3), 0.0, 1.0);            // 0 top of wall .. 1 fold

    // ---- Key light: a beam widening up the wall, pooling on the floor ----
    float depthT = u_lightDepth / 100.0;                           // 0 aims at the wall, 1 at the floor
    float softK = mix(0.3, 1.6, u_keySoftness / 100.0);
    float dx = x - sx;
    float wBeam = mix(0.11, 0.38, 1.0 - wallT) * softK;            // wider toward the top
    float beam = exp(-(dx * dx) / (wBeam * wBeam));
    float beamV = mix(0.6, 1.0, pow(wallT, 1.5));                  // brighter near the pool
    beamV *= mix(1.0, 0.75, depthT * (1.0 - wallT));               // aimed at the floor: the top dims
    float keyWall = beam * beamV * (1.0 - isFloor) * 0.62;
    float poolV = (v - sv) / (0.06 * softK + 0.03);
    float poolX = dx / (0.22 * softK);
    float pool = exp(-(poolX * poolX + poolV * poolV)) * mix(0.5, 1.4, depthT);
    float floorGlow = exp(-(dx * dx) / (0.5 * 0.5)) * exp(-abs(v - sv) / 0.22) * 0.5;
    float keyFloor = (pool + floorGlow) * isFloor;
    float key = (keyWall + keyFloor) * (u_keyIntensity / 100.0) * 2.2;

    // ---- Two side fills: soft blobs low on the wall, either side of the stage ----
    float spread = mix(0.15, 0.95, u_fillSpread / 100.0) * asp.x * 0.5;
    float softF = mix(0.12, 0.42, u_fillSoftness / 100.0);
    float fill = 0.0;
    for (int i = 0; i < 2; i++) {
        float fx = sx + (i == 0 ? -spread : spread);
        float fv = fold - 0.22;
        float ddx = (x - fx) / softF, ddv = (v - fv) / (softF * 1.4);
        fill += exp(-(ddx * ddx + ddv * ddv));
    }
    fill *= (u_fillIntensity / 100.0) * 4.0;

    // ---- Back wash: light climbing the wall from the fold, and the floor's near edge ----
    float softB = mix(0.05, 0.5, u_backSoftness / 100.0);
    float back = (1.0 - isFloor) * exp(-max(fold - v, 0.0) / softB)
               + isFloor * exp(-max(v - fold, 0.0) / (softB * 1.5)) * 0.6;
    back *= (u_backIntensity / 100.0) * 0.9;

    // ---- Drifting ambient lights: broad, faint, slowly wandering ----
    vec2 drift = vec2(u_time * 0.04, -u_time * 0.025);
    float seedFold = mod(u_seed, 97.0) + floor(u_seed / 97.0) * 0.3711;
    float blobs = fbm(vec2(x, v) * 1.4 + drift + seedFold * 3.1);
    float detail = (blobs - 0.5) * (u_ambientDetail / 100.0) * 0.16;

    // ---- Compose: the surface under each light ----
    float ambient = 0.14 + (u_ambient / 100.0) * 1.5;
    vec3 col = u_surface * ambient;
    // The set falls away from the stage: corners sit darker even with no vignette.
    vec2 away = vec2((x - sx) / asp.x, (v - sv) * 1.1);
    col *= 1.0 - 0.28 * smoothstep(0.35, 1.3, length(away));
    col *= 1.0 + detail;
    col += u_surface * u_keyColor * key;
    col += u_surface * u_fillColor * fill;
    col += u_surface * u_backColor * back;
    // The floor sits a touch darker than the wall away from the lights, and the far
    // bottom edge falls off.
    col *= mix(1.0, 0.92, isFloor) * (1.0 - 0.25 * smoothstep(sv + 0.05, 1.05, v));

    // ---- Vignette ----
    vec2 vq = uv * 2.0 - 1.0;
    float vig = 1.0 - (u_vignette / 100.0) * smoothstep(0.45, 1.6, dot(vq, vq));
    col *= vig;

    fragColor0 = vec4(clamp(col, 0.0, 1.0), 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// NEBULA: a volumetric gas nebula sealed inside polished glass. Billowing emission clouds with
// hot glowing cores and hollow dark cavities, star fields drifting at real depth behind the gas,
// all refracted through the curved glass walls and dressed with a studio reflection. A port of the
// Shaders.com "Nebula" component (the "Fluid Chrome" preview's current design). Sailor renders it
// clipped to the layer's silhouette (the glass shape), raymarching a virtual depth per pixel.
//
// A material coats whatever it is applied to; the Frame hands over the layer's silhouette
// (u_shape: R rim field, G distance to the outline) so the glass bevel and refraction follow the
// shape. With no silhouette it fills the tile as a round glass lens of nebula.

uniform vec3  u_coreColor;         // the hot colour the densest gas cores glow with
uniform vec3  u_gasColor;          // the main emission colour of the gas body (H-alpha rose)
uniform vec3  u_veilColor;         // thin outer veils + the deep-space background behind the gas
uniform float u_density;           // optical density: how strongly clouds occlude what is behind
uniform float u_cavity;            // how hollowed-out: high carves large dark voids
uniform float u_dust;              // cold dark dust lanes threading the gas (absorb-only, redden)
uniform float u_gasScale;          // feature size of the gas: higher = finer, busier detail
uniform float u_billow;            // turbulent folding: 0 smooth banks, 1 heavily churned billows
uniform float u_glow;              // hot emission bloom of the dense cores
uniform float u_gasSeed;           // pans the gas field for a new cloud composition
uniform float u_stars;             // brightness of the star fields at depth
uniform float u_starScale;         // density of the star fields (higher = smaller, busier)
uniform float u_twinkle;           // star twinkle intensity
uniform float u_refraction;        // how strongly the glass walls bend the interior near the edges
uniform float u_environment;       // strength of the studio softboxes reflected in the glass
uniform float u_highlight;         // sharp key-light glint on the glass
uniform float u_highlightSoftness; // specular softness: lower is a tighter glint
uniform float u_lightAngle;        // direction of the key light and studio, degrees
uniform float u_edgeSoftness;      // softness of the shape boundary
uniform float u_speed;             // churn/twinkle speed

// Supplied by the Frame when the effect follows a layer's shape.
uniform sampler2D u_shape;
uniform float u_hasShape;
uniform float u_shapeCX;
uniform float u_shapeCY;
uniform float u_shapeSize;

const float PI = 3.14159265359;

// ---- Hash + 3D value noise (stand-in for the component's mxNoiseFloat3) ----
float hash13(vec3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
vec3 grad3(vec3 p) {
    return normalize(vec3(hash13(p + 11.0), hash13(p + 47.0), hash13(p + 83.0)) * 2.0 - 1.0);
}
// 3D gradient (Perlin-style) noise, in [-1,1] — the natural flowing structure the component's
// MaterialX noise gives, in place of the earlier blobby value noise.
float vnoise3(vec3 p) {
    vec3 i = floor(p), f = fract(p);
    vec3 u = f * f * (3.0 - 2.0 * f);
    float n000 = dot(grad3(i + vec3(0.0, 0.0, 0.0)), f - vec3(0.0, 0.0, 0.0));
    float n100 = dot(grad3(i + vec3(1.0, 0.0, 0.0)), f - vec3(1.0, 0.0, 0.0));
    float n010 = dot(grad3(i + vec3(0.0, 1.0, 0.0)), f - vec3(0.0, 1.0, 0.0));
    float n110 = dot(grad3(i + vec3(1.0, 1.0, 0.0)), f - vec3(1.0, 1.0, 0.0));
    float n001 = dot(grad3(i + vec3(0.0, 0.0, 1.0)), f - vec3(0.0, 0.0, 1.0));
    float n101 = dot(grad3(i + vec3(1.0, 0.0, 1.0)), f - vec3(1.0, 0.0, 1.0));
    float n011 = dot(grad3(i + vec3(0.0, 1.0, 1.0)), f - vec3(0.0, 1.0, 1.0));
    float n111 = dot(grad3(i + vec3(1.0, 1.0, 1.0)), f - vec3(1.0, 1.0, 1.0));
    return mix(mix(mix(n000, n100, u.x), mix(n010, n110, u.x), u.y),
               mix(mix(n001, n101, u.x), mix(n011, n111, u.x), u.y), u.z) * 1.6;
}

// The gas field at a point: domain-warped fbm folded by Billow (port of the component's `zze`).
// Returns density (signed-ish), plus the mid/fine octaves the shading reads for dust and grain.
void gasField(vec3 pos, float freq, float drift, float seed, float billow,
              out float density, out float mid, out float fine) {
    vec3 q = vec3(pos.x * freq, pos.y * freq * (-0.7), pos.z * freq * 1.25)
           + vec3(drift, drift * 0.53, drift * 0.79) + vec3(seed * 0.37, seed * 0.61, seed);
    vec3 warp = vec3(vnoise3(q * 0.5 + vec3(drift * 1.4, 0.0, drift * -0.9)));
    vec3 qw = q + vec3(warp.x, warp.x * -0.73, warp.x * 0.41) * billow;
    mid  = vnoise3(qw * 2.13 + vec3(5.2, 1.3, 8.4));
    fine = vnoise3(qw * 4.31 + vec3(9.1, 3.7, 1.2));
    density = (vnoise3(qw) + mid * 0.5 + fine * 0.27) * 0.57;
}

// sRGB <-> linear, and linear-RGB <-> OKLab (the exact matrices the component blends in). The
// veil -> gas -> core ramp is mixed in OKLab so the midtones stay vivid instead of muddying.
vec3 srgbToLinear(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c)); }
vec3 linearToSrgb(vec3 c) { c = max(c, 0.0); return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c)); }
vec3 linearToOklab(vec3 c) {
    float l = 0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b;
    float m = 0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b;
    float s = 0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b;
    float l_ = pow(max(l, 0.0), 1.0 / 3.0), m_ = pow(max(m, 0.0), 1.0 / 3.0), s_ = pow(max(s, 0.0), 1.0 / 3.0);
    return vec3(0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
                1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
                0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_);
}
vec3 oklabToLinear(vec3 lab) {
    float l_ = lab.x + 0.3963377774 * lab.y + 0.2158037573 * lab.z;
    float m_ = lab.x - 0.1055613458 * lab.y - 0.0638541728 * lab.z;
    float s_ = lab.x - 0.0894841775 * lab.y - 1.2914855480 * lab.z;
    float l = l_ * l_ * l_, m = m_ * m_ * m_, s = s_ * s_ * s_;
    return vec3( 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
                -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
                -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s);
}
// veil -> gas -> core, blended in OKLab, returned as LINEAR rgb.
vec3 nebulaRamp(vec3 oklVeil, vec3 oklGas, vec3 oklCore, float a, float b) {
    vec3 lab = mix(mix(oklVeil, oklGas, clamp(a, 0.0, 1.0)), oklCore, clamp(b, 0.0, 1.0));
    return max(oklabToLinear(lab), 0.0);
}

// Globals set in main() so the raymarch can read the pre-converted colours and drift without a
// long parameter list (it is called several times per pixel when supersampling the refracted rim).
vec3 g_oklVeil, g_oklGas, g_oklCore, g_veilLin, g_coreLin;
float g_drift;

// One volumetric raymarch of the gas from a given sample point (6 steps, front to back). Returns
// the accumulated emission and, via `transmit`, how much light makes it through.
vec3 marchGas(vec2 bent, float freq, float cav, out float transmit) {
    const int STEPS = 6;
    float macro = vnoise3(vec3(bent * 1.3, g_drift * 0.6 + u_gasSeed * 0.37)) * 0.45;
    vec3 emission = vec3(0.0);
    transmit = 1.0;
    for (int s = 0; s < STEPS; s++) {
        float t = (float(s) + 0.5) / float(STEPS);
        float z = t * 2.0 + u_gasSeed * 7.31;
        float density, mid, fine;
        gasField(vec3(bent, z), freq, g_drift, u_gasSeed * 7.31, u_billow * 0.9, density, mid, fine);
        float endFade = smoothstep(0.0, 0.11, min(t, 1.0 - t));
        float grain = 1.0 - clamp(abs(fine) * 1.6, 0.0, 1.0);
        float dens = smoothstep(0.40, 0.90, density + macro - cav) * endFade * (0.55 + grain * 0.8);
        float dust = smoothstep(0.45, 0.75, mid) * endFade * u_dust;
        vec3 col = nebulaRamp(g_oklVeil, g_oklGas, g_oklCore, smoothstep(0.05, 0.75, dens), smoothstep(0.68, 1.0, dens));
        float be = 1.0 - t * 0.45;
        float veilTerm = smoothstep(-0.7, 0.3, density) * 0.05 * endFade;
        vec3 emit = col * (dens * be * 0.85)
                  + g_coreLin * (pow(dens, 2.4) * (0.5 + u_glow * 1.3) * be)
                  + g_veilLin * (veilTerm * be);
        float aGain = (0.5 + t * 2.2) * u_density * 0.5;
        vec3 absorb = vec3(dens * aGain) + vec3(1.5, 1.0, 0.55) * (dust * aGain * 2.2);
        float eGain = (0.3 + t * 0.9);
        emission += emit * eGain * transmit;
        transmit *= exp(-(absorb.r + absorb.g + absorb.b) * 0.5);
    }
    return emission;
}

// A drifting star field at one depth: bright points on a hashed grid, with a soft radius and a
// per-star twinkle (port of the component's `vO`, simplified). Returns premultiplied colour.
vec3 starField(vec2 uv, float freq, float twinkleRate, float gain, vec3 tintFrom, vec3 tintTo, float t) {
    vec2 g = uv * freq;
    vec2 cell = floor(g), f = fract(g);
    vec3 acc = vec3(0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        vec2 o = vec2(float(i), float(j));
        vec2 id = cell + o;
        float h = hash13(vec3(id, 3.0));
        if (h < 0.35) continue;                                  // only some cells hold a star
        vec2 pos = o + vec2(hash13(vec3(id, 1.0)), hash13(vec3(id, 2.0)));
        float d = length(f - pos);
        float r = mix(0.03, 0.09, hash13(vec3(id, 5.0)));
        float star = smoothstep(r, 0.0, d);
        float tw = 1.0 - u_twinkle * (0.5 + 0.5 * sin(t * twinkleRate + h * 40.0));
        float br = mix(0.3, 1.2, hash13(vec3(id, 7.0))) * tw;
        vec3 tint = mix(tintFrom, tintTo, hash13(vec3(id, 9.0)));
        acc += tint * star * br;
    }
    return acc * gain * 9.0;
}

// The reflected studio: a couple of soft softboxes looked up by the glass reflection direction.
float studio(vec2 d, float angle) {
    float c = cos(angle), s = sin(angle);
    vec2 r = vec2(d.x * c - d.y * s, d.x * s + d.y * c);
    float box1 = smoothstep(0.6, 0.12, abs(r.y - 0.4)) * smoothstep(1.3, 0.2, abs(r.x + 0.2));
    float box2 = smoothstep(0.4, 0.08, abs(r.y + 0.5)) * smoothstep(1.2, 0.3, abs(r.x - 0.3)) * 0.6;
    return clamp(box1 + box2, 0.0, 1.4);
}

vec3 tonemap(vec3 c) { return vec3(1.0) - exp(-c); }

void main() {
    float shortSide = min(u_resolution.x, u_resolution.y);
    vec2 asp = u_resolution / shortSide;
    vec2 p = v_texCoord * asp;

    // ---- Shape: coverage, distance field, and the outward (glass-wall) normal ----
    vec2 c, rel, outward;
    float cover, edgeD;
    if (u_hasShape > 0.5) {
        c = vec2(u_shapeCX, u_shapeCY) * asp;
        rel = p - c;
        vec4 sh = texture(u_shape, v_texCoord);
        vec2 px = 1.5 / u_resolution;
        float gx = texture(u_shape, v_texCoord + vec2(px.x, 0.0)).r - texture(u_shape, v_texCoord - vec2(px.x, 0.0)).r;
        float gy = texture(u_shape, v_texCoord + vec2(0.0, px.y)).r - texture(u_shape, v_texCoord - vec2(0.0, px.y)).r;
        vec2 g = vec2(gx, gy) / asp;
        float gl = length(g);
        outward = gl > 1e-6 ? -g / gl : vec2(0.0, 1.0);
        // Blur the distance field (a 256px thumbnail upscaled) so the glass terms that key off it
        // do not band into contour streaks near the wall.
        vec2 e0 = 6.0 / u_resolution;
        edgeD = (texture(u_shape, v_texCoord).g * 2.0
               + texture(u_shape, v_texCoord + vec2(e0.x, 0.0)).g + texture(u_shape, v_texCoord - vec2(e0.x, 0.0)).g
               + texture(u_shape, v_texCoord + vec2(0.0, e0.y)).g + texture(u_shape, v_texCoord - vec2(0.0, e0.y)).g
               + texture(u_shape, v_texCoord + e0).g + texture(u_shape, v_texCoord - e0).g) / 8.0;
        cover = 1.0;                          // the compositor clips to the crisp silhouette
    } else {
        c = 0.5 * asp;
        rel = p - c;
        float r = length(rel) / max(u_shapeSize, 0.42);
        outward = length(rel) > 1e-5 ? normalize(rel) : vec2(0.0, 1.0);
        edgeD = clamp(1.0 - r, 0.0, 1.0);
        cover = 1.0 - smoothstep(0.99, 1.0, r);
    }
    float unit = u_hasShape > 0.5 ? max(u_shapeSize, 0.05) : 0.42;
    vec2 relN = rel / unit;                    // shape-normalised, ~[-1,1] across the shape

    float time = u_time * u_speed;
    float drift = time * 0.14;

    // The three nebula colours are sRGB; work in linear, and pre-convert to OKLab for the ramp.
    vec3 veilLin = srgbToLinear(u_veilColor), gasLin = srgbToLinear(u_gasColor), coreLin = srgbToLinear(u_coreColor);
    vec3 oklVeil = linearToOklab(veilLin), oklGas = linearToOklab(gasLin), oklCore = linearToOklab(coreLin);

    // ---- Smooth glass shell normal (computed up here so it can REFRACT the interior) ----
    // Heavily blur the distance field so the glass normal is smooth (no faceted rings), read as a
    // sphere: flat at the centre, curving steeply only near the rim.
    float gd = 0.0;
    {
        vec2 gr1 = 7.0 / u_resolution, gr2 = 14.0 / u_resolution;
        gd = texture(u_shape, v_texCoord).g * 3.0;
        gd += (texture(u_shape, v_texCoord + vec2(gr1.x, 0.0)).g + texture(u_shape, v_texCoord - vec2(gr1.x, 0.0)).g
             + texture(u_shape, v_texCoord + vec2(0.0, gr1.y)).g + texture(u_shape, v_texCoord - vec2(0.0, gr1.y)).g
             + texture(u_shape, v_texCoord + gr1).g + texture(u_shape, v_texCoord - gr1).g
             + texture(u_shape, v_texCoord + vec2(gr1.x, -gr1.y)).g + texture(u_shape, v_texCoord + vec2(-gr1.x, gr1.y)).g) * 2.0;
        gd += texture(u_shape, v_texCoord + vec2(gr2.x, 0.0)).g + texture(u_shape, v_texCoord - vec2(gr2.x, 0.0)).g
            + texture(u_shape, v_texCoord + vec2(0.0, gr2.y)).g + texture(u_shape, v_texCoord - vec2(0.0, gr2.y)).g
            + texture(u_shape, v_texCoord + gr2).g + texture(u_shape, v_texCoord - gr2).g
            + texture(u_shape, v_texCoord + vec2(gr2.x, -gr2.y)).g + texture(u_shape, v_texCoord + vec2(-gr2.x, gr2.y)).g;
        gd = u_hasShape > 0.5 ? gd / 27.0 : edgeD;
    }
    float la = radians(u_lightAngle);
    float rr = clamp(1.0 - gd, 0.0, 1.0);                     // 0 at the centre, 1 at the rim
    float theta = pow(rr, 2.6) * 1.5;                         // flat centre, steep only at the rim
    vec3 Ng = normalize(vec3(outward * sin(theta), cos(theta)));

    // ---- Refraction: the curved glass walls BEND the interior. Pull the sampled point inward
    // toward the centre near the rim — a lens that magnifies the nebula behind the glass wall. The
    // displacement uses a smoothstep falloff that is FLAT at both ends (max at the rim, zero at the
    // centre), so its gradient never spikes and the magnified gas does not alias. ----
    float refr = u_refraction * 0.45 * (1.0 - smoothstep(0.0, 1.0, gd));
    vec2 bent = relN - outward * refr;

    // ---- Volumetric raymarch of the gas, supersampled where the glass compresses it ----
    g_oklVeil = oklVeil; g_oklGas = oklGas; g_oklCore = oklCore; g_veilLin = veilLin; g_coreLin = coreLin; g_drift = drift;
    // Coarsen the gas a little where the glass magnifies it (near the rim), then SUPERSAMPLE: near
    // the rim the lens compresses many noise-lattice cells into a pixel, which aliases into a grid;
    // averaging a ring of samples across the pixel's footprint (fwidth(bent)) resolves it. The flat
    // interior (no compression) takes a single exact sample.
    float freq = u_gasScale * 6.0 * (1.0 - clamp(refr * 1.6, 0.0, 0.62));
    float cav = mix(-0.35, 0.5, u_cavity);
    vec3 emission; float transmit;
    if (refr > 0.03) {
        vec2 fw = fwidth(bent);
        vec3 em = vec3(0.0); float tr = 0.0;
        const int SS = 4;
        for (int k = 0; k < SS; k++) {
            float a = (float(k) + 0.5) / float(SS) * 6.2831853;
            float trk;
            em += marchGas(bent + vec2(cos(a), sin(a)) * fw * 0.7, freq, cav, trk);
            tr += trk;
        }
        emission = em / float(SS); transmit = tr / float(SS);
    } else {
        emission = marchGas(bent, freq, cav, transmit);
    }

    // ---- Star fields at two depths, drifting and twinkling behind/through the gas ----
    float sf = u_starScale * 34.0;
    vec3 farStars  = starField(bent * 0.9 + vec2(drift * 0.3, 0.0), sf,       1.7, u_stars, vec3(0.72, 0.82, 1.0), vec3(1.0, 0.92, 0.82), time);
    vec3 nearStars = starField(bent * 1.4 + vec2(-drift * 0.2, 0.1), sf * 0.56, 2.3, u_stars, vec3(0.75, 0.85, 1.0), vec3(1.0, 0.95, 0.88), time);

    // ---- Glass surface shading (the shell normal Ng was computed up top for the refraction) ----
    float fres = pow(1.0 - clamp(Ng.z, 0.0, 1.0), 3.0);      // grazing → the bright glass rim
    vec3 Rg = reflect(vec3(0.0, 0.0, -1.0), Ng);             // reflection direction off the glass
    float envG = studio(Rg.xy * 1.5, la);                    // soft studio reflection
    vec2 lightv = vec2(cos(la), -sin(la));
    float ndh = clamp(dot(Ng.xy, lightv) + Ng.z * 0.15, 0.0, 1.0);
    float glint = pow(ndh, mix(240.0, 30.0, u_highlightSoftness)) * u_highlight;

    // ---- Composite: veil bg, gas volume, stars, then the glass shell on top ----
    vec3 col = veilLin * 0.03 * transmit;                     // deep-space veil behind everything
    col += emission;                                          // the gas
    float interior = smoothstep(0.0, 0.08, edgeD);
    col += farStars * transmit * interior;
    col += nearStars * mix(transmit, 1.0, 0.35) * interior;
    col *= 1.0 - fres * 0.55;                                 // at the rim the glass turns reflective
    col += vec3(0.72, 0.80, 1.0) * fres * (0.25 + 0.35 * u_environment);   // bright Fresnel rim
    col += vec3(0.85, 0.92, 1.08) * envG * u_environment * 0.5;            // soft studio reflection
    col += vec3(1.0, 0.98, 0.95) * glint;                                  // sharp key glint
    col = linearToSrgb(tonemap(col));

    fragColor0 = vec4(clamp(col, 0.0, 1.0), 1.0) * cover;
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// HEATMAP: thermal-camera heat flowing through a shape. Heat gathers inside the
// silhouette (Inner glow), radiates just past its edge (Outer glow) and concentrates
// along the outline (Contour); cool waves travel across it in the Angle direction, and
// the whole field is read through a colour ramp interpolated in OKLab. A port of the
// Shaders.com "Heatmap" component (Paper Shaders); its default is a centred disc.
//
// A material dresses whatever it is applied to. With no silhouette handed over — a 3D
// surface, a Space Type / Shape fill, the catalog preview — the heat maps over a centred
// disc that fills the tile and radiates onto transparency. In the Frame the layer hands
// over its silhouette (u_shape: R the rim field, G the depth inward), so the heat flows
// through the layer's own shape. The compositor clips the result to the crisp full-res
// silhouette, so the outer glow reads as an edge bloom on a Frame and radiates fully only
// on the no-shape tile (there is no "outside" to glow into once clipped).

#define MAXS 8
uniform vec3  u_ramp[MAXS];       // the heat colour ramp, cold -> hot
uniform float u_rampPos[MAXS];
uniform float u_rampCount;
uniform float u_innerGlow;        // heat filling the inside of the shape
uniform float u_outerGlow;        // heat radiating beyond the silhouette
uniform float u_contour;          // heat concentrated along the outline
uniform float u_angle;            // direction the heat waves travel, degrees
uniform float u_scale;            // size of the heat field, 1 = default
uniform float u_edgeSoftness;     // softness of the boundary

// Supplied by the Frame when the effect follows a layer's shape (see glass_lens).
uniform sampler2D u_shape;
uniform float u_hasShape;
uniform float u_shapeCX;
uniform float u_shapeCY;
uniform float u_shapeSize;

// ---- noise (the source's 2D noise, `G7e`): value noise ----
float hash21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i), b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0)), d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ---- OKLab, so the heat ramp interpolates the way the source does (colorSpace: oklab) ----
vec3 srgbToLinear(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c)); }
vec3 linearToSrgb(vec3 c) { c = max(c, 0.0); return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c)); }
vec3 linearToOklab(vec3 c) {
    float l = 0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b;
    float m = 0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b;
    float s = 0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b;
    l = pow(l, 1.0 / 3.0); m = pow(m, 1.0 / 3.0); s = pow(s, 1.0 / 3.0);
    return vec3(0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
                1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
                0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s);
}
vec3 oklabToLinear(vec3 lab) {
    float l = lab.x + 0.3963377774 * lab.y + 0.2158037573 * lab.z;
    float m = lab.x - 0.1055613458 * lab.y - 0.0638541728 * lab.z;
    float s = lab.x - 0.0894841775 * lab.y - 1.2914855480 * lab.z;
    l = l * l * l; m = m * m * m; s = s * s * s;
    return vec3( 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
                -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
                -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s);
}

// The heat scalar (0 cold -> 1 hot) read through the ramp, interpolated in OKLab.
vec3 heatRamp(float t) {
    int n = max(1, int(u_rampCount + 0.5));
    t = clamp(t, 0.0, 1.0);
    if (t <= u_rampPos[0]) return linearToSrgb(oklabToLinear(linearToOklab(srgbToLinear(u_ramp[0]))));
    for (int i = 0; i < MAXS - 1; i++) {
        if (i + 1 >= n) break;
        float p0 = u_rampPos[i], p1 = u_rampPos[i + 1];
        if (t >= p0 && t <= p1) {
            float f = p1 > p0 ? (t - p0) / (p1 - p0) : 0.0;
            vec3 l0 = linearToOklab(srgbToLinear(u_ramp[i]));
            vec3 l1 = linearToOklab(srgbToLinear(u_ramp[i + 1]));
            return linearToSrgb(oklabToLinear(mix(l0, l1, f)));
        }
    }
    return linearToSrgb(oklabToLinear(linearToOklab(srgbToLinear(u_ramp[clamp(n - 1, 0, MAXS - 1)]))));
}

// The chamfer distance (u_shape.g) is built from a 256px silhouette thumbnail and
// upscaled, so its iso-contours are POLYGONAL — read raw, the hot rim and contour band
// (both narrow bands riding an iso-contour) trace those facets and the sharp ramp turns
// them into a jagged bright edge (liquid_metal/chrome hit the same thumbnail stair-step).
// A small disc blur, sized in texture space (~1.5 thumbnail texels, resolution-independent),
// rounds the contour before it drives an edge-critical feature.
float shapeDepth(vec2 uv) {
    const float r = 1.5 / 256.0;
    const float d = r * 0.70710678;
    float s = texture(u_shape, uv).g;
    s += texture(u_shape, uv + vec2(r, 0.0)).g + texture(u_shape, uv + vec2(-r, 0.0)).g;
    s += texture(u_shape, uv + vec2(0.0, r)).g + texture(u_shape, uv + vec2(0.0, -r)).g;
    s += texture(u_shape, uv + vec2(d, d)).g + texture(u_shape, uv + vec2(-d, d)).g;
    s += texture(u_shape, uv + vec2(d, -d)).g + texture(u_shape, uv + vec2(-d, -d)).g;
    return s / 9.0;
}

// Sw: a soft Gaussian heat band whose centre sweeps across the travel direction as its
// phase runs 0 -> 1, its edge wobbled by noise, fading in and out over its life. Three
// staggered layers carve the cool streaks that flow through the hot interior.
float wave(float along, float across, float s, float layer) {
    float o = mix(-0.6, 0.6, s);
    float n = vnoise(vec2(across * 4.0 + layer * 13.7, s * 3.0 + layer * 7.1)) - 0.5;
    float a = (along - o) + n * 0.12;
    return clamp(exp(-a * a / 0.0256) * (smoothstep(0.0, 0.15, s) * (1.0 - smoothstep(0.85, 1.0, s))), 0.0, 1.0);
}

void main() {
    vec4 base = texture(u_image0, v_texCoord);
    float shortSide = min(u_resolution.x, u_resolution.y);
    vec2 asp = u_resolution / shortSide;
    vec2 p = v_texCoord * asp;

    float sc = max(u_scale, 0.05);
    // Edge softness the USER dials in (0 = a razor edge, left to the screen-space AA
    // below; 1 = a broad fade). Scaled down because the raw 0..1 range was so wide the
    // no-shape disc read as an all-over blur — on a Frame the compositor's silhouette
    // clip hides this, but the bare material tile has only the shader to define its edge.
    float soft = u_edgeSoftness * 0.06;

    // ---- The signed distance field the heat is measured from ----
    // i < 0 inside, ~0 at the outline, > 0 outside. `inside` is a soft 0..1 mask.
    vec2 c, rel;
    float i, inside;
    if (u_hasShape > 0.5) {
        c = vec2(u_shapeCX, u_shapeCY) * asp;
        rel = p - c;
        // G (the chamfer field) is 0 at the outline and rises to 1 at the deepest point.
        // There is no true outside distance once the compositor clips to the silhouette,
        // so i only goes negative (inward); the outer glow becomes an inner edge bloom.
        float depth = shapeDepth(v_texCoord);       // blurred: rounds the thumbnail facets
        i = -depth / sc;
        inside = smoothstep(0.0, max(soft, fwidth(depth) * 1.5), depth);
    } else {
        c = 0.5 * asp;
        rel = p - c;
        i = (length(rel) - 0.35) / sc;              // the source default: a disc, radius 0.35
        // A crisp, screen-space antialiased edge (~1px) plus whatever softness the user
        // dials — so the disc has a defined boundary instead of fading over ~20px.
        float w = fwidth(i) * 1.5 + soft;
        inside = 1.0 - smoothstep(-w, w, i);
    }

    // ---- Where the heat waves travel ----
    float ang = radians(u_angle);
    vec2 tangent = vec2(cos(ang), sin(ang));
    vec2 perp = vec2(-sin(ang), cos(ang));
    float along = dot(rel, tangent);
    float across = -dot(rel, perp);

    float time = u_time;                            // fill.shader.speed already scales the clock
    float m = 0.1 * time - 0.3;

    // ---- Inner heat: edge-weighted fill, cool waves carved through it, a contour band ----
    float depthIn = max(-i, 0.0);
    float inner = 0.8 + 0.8 * exp(-depthIn / 0.12);
    inner = mix(inner, 0.0, wave(along, across, fract(m),             1.0));
    inner = mix(inner, 0.0, wave(along, across, fract(m + 1.0 / 3.0), 2.0));
    inner = mix(inner, 0.0, wave(along, across, fract(m + 2.0 / 3.0), 3.0));
    inner *= 2.0 * u_innerGlow;
    inner += (u_contour * 2.0) * exp(-abs(i) / 0.03);
    inner = min(inner, 1.0) * inside;
    inner = pow(max(inner, 0.0), 1.2);

    // ---- Outer heat: a travelling glow radiating past the edge ----
    float outAmt = 0.05 + 0.15 * u_outerGlow;
    float v = exp(-max(i, 0.0) / outAmt);
    float g = fract(3.0 * m - 0.1);
    float bb = fract(1.2 * along - g);
    float y = 0.5 + smoothstep(0.3, 0.65, bb) * (1.0 - smoothstep(0.65, 1.0, bb));
    float outer = 0.9 * pow(v, 0.8) * y * 5.0 * u_outerGlow * u_outerGlow * (1.0 - inside);

    float heat = clamp(inner + outer, 0.0, 1.0);
    heat += 0.005 * (hash21(rel * vec2(991.3, 787.7)) - 0.5);   // tiny dither breaks the banding
    heat = clamp(heat, 0.0, 1.0);

    float alpha = clamp(inside + outer, 0.0, 1.0);
    vec3 col = heatRamp(heat);

    fragColor0 = vec4(mix(base.rgb, col, alpha), max(base.a, alpha));
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// CHROME: a precision-machined mirror-metal shape with a photographic studio reflected in
// it — one big frontal softbox, black side flags, and thin warm/cool strip lights that fringe
// the reflections amber above the horizon and ice-blue below. A polished bevel runs round the
// edge, the faces dome gently, and a slow orbit slides the whole studio across the surface.
// A port of the Shaders.com "Chrome" component (the "Fluid Chrome" design's values).
//
// A material coats whatever it is applied to. In the Frame the Frame hands over the layer's
// silhouette (u_shape: R the rim field, G the distance to the outline), so the bevel and dome
// follow the shape. Elsewhere — a 3D surface, a Space Type / Shape fill, the catalog preview —
// there is no silhouette, so it fills the whole tile as a domed chrome sheet (no edge bevel:
// a UV-border bevel would seam a sphere or a wrapped glyph).

uniform vec3  u_tint;            // metal tint multiplied into the reflection (white = silver)
uniform vec3  u_warmColor;       // the warm strip light hugging the studio horizon
uniform vec3  u_coolColor;       // the cool wash below the horizon
uniform float u_bevelWidth;      // width of the polished edge bevel, relative to the shape
uniform float u_bevelShape;      // 0 one round fillet, 1 machined: fillet, chamfer, knee
uniform float u_curvature;       // convex doming of the faces
uniform float u_waviness;        // pressed-metal imperfection: bends reflections, wobbles edges
uniform float u_environment;     // exposure of the reflected studio
uniform float u_envRotation;     // rotates the whole reflected studio, degrees
uniform float u_softness;        // 0 razor polished, 1 satin diffusion
uniform float u_spectral;        // strength of the amber + ice-blue accent lights
uniform float u_dispersion;      // prismatic RGB fringing along the fast-curving bevel
uniform float u_shadows;         // depth of the dark studio reflections
uniform float u_speed;           // speed of the studio orbit
uniform float u_edgeSoftness;    // softness of the shape boundary

// Supplied by the Frame when the effect follows a layer's shape (see glass_lens/liquid_metal).
uniform sampler2D u_shape;
uniform float u_hasShape;
uniform float u_shapeCX;
uniform float u_shapeCY;
uniform float u_shapeSize;

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}
float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i), b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0)), d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// The bevel light profile, driven by t (0 at the outline, 1 where the flat face begins).
// shape 0 = one smooth round fillet (1 - t); shape 1 = machined: a steep outer fillet, a
// chamfer plateau, then an inner knee. A faithful port of the component's `bevelSin`.
float bevelSin(float t, float shape) {
    float round = 1.0 - t;
    float o = smoothstep(0.0, 0.14, t);
    float n = smoothstep(0.68, 0.92, t);
    float machined = mix(1.0, 0.72 * (1.0 - n), o);
    return mix(round, machined, shape);
}

// The silhouette's distance field (G channel), heavily blurred to erase the 128px thumbnail's
// facets. The distance field is low-frequency, so a wide two-ring 21-tap blur is safe and makes
// the dome and bevel read as one smooth pillow instead of a bilinear-upscaled terrace.
float dfield(vec2 uv) {
    vec2 r = 11.0 / u_resolution;
    vec2 d = r * 0.70711;                         // diagonal taps at the same radius
    float s = texture(u_shape, uv).g * 2.0;
    s += texture(u_shape, uv + vec2(r.x, 0.0)).g + texture(u_shape, uv - vec2(r.x, 0.0)).g
       + texture(u_shape, uv + vec2(0.0, r.y)).g + texture(u_shape, uv - vec2(0.0, r.y)).g
       + texture(u_shape, uv + d).g + texture(u_shape, uv - d).g
       + texture(u_shape, uv + vec2(d.x, -d.y)).g + texture(u_shape, uv + vec2(-d.x, d.y)).g;
    return s / 10.0;
}

// The surface HEIGHT as a function of distance-from-edge d (0 at the outline, 1 deepest). A
// convex dome: rises from the edge and levels at the interior. The normal comes from this
// height's SCREEN-space gradient (below), which stays smooth across the shape's medial axis —
// where the raw distance-field gradient flips and would crease the surface into a fan.
float domeH(float d) {
    d = clamp(d, 0.0, 1.0);
    return 1.0 - (1.0 - d) * (1.0 - d);          // parabolic dome: monotonic slope, smooth reflection
}

// The reflected studio, looked up by a reflection direction d (a unit-ish vec3). A dark
// graphite room, a bright frontal softbox, a warm strip light at the softbox edge, a cool wash
// below the horizon, a floor bounce and a lower cool card. A faithful port of the component's
// `Aw` environment. softEff/soft = edge softness, spectral = accent-light strength,
// shadows = how hard the darks crush, warmC/coolC = the two accent colours.
vec3 studio(vec3 d, float softEff, float soft, float spectral, float shadows, vec3 warmC, vec3 coolC) {
    float ex = d.x, ey = d.y, ez = d.z;
    float horiz = ex / (length(vec2(ex, ey)) + 1e-4);
    float warmSide = 0.35 + 0.65 * smoothstep(-0.7, 0.7, horiz);
    float coolSide = 0.45 + 0.55 * smoothstep(-0.7, 0.7, -horiz);
    float up = smoothstep(-0.65, 1.0, ey);

    vec3 g = coolC * 0.03 + vec3(0.003, 0.003, 0.004);
    vec3 b = mix(mix(vec3(0.17, 0.175, 0.19), g, clamp(shadows, 0.0, 1.0)),
                 vec3(0.56, 0.57, 0.6), clamp(up * up, 0.0, 1.0));
    b += vec3(0.55, 0.55, 0.56) * smoothstep(0.3, 0.9, ey);

    // Cool wash hugging just below the horizon band.
    float cd = (ey + 0.45) / 0.2;
    b += coolC * (exp(-(cd * cd)) * spectral * 0.2) * coolSide;

    // The frontal softbox, seen only by faces reflecting toward the viewer (ez negative).
    float facing = 1.0 - smoothstep(-0.1, 0.18, ez);
    float pz = max(0.32 - ez, 0.06);
    float px = ex / pz, py = ey / pz;
    float boxC = abs(px) - 0.62;
    float boxK = abs(py - 0.3) - 0.28;
    float U = length(max(vec2(boxC, boxK), vec2(0.0))) + min(max(boxC, boxK), 0.0);
    float boxSoft = 0.05 + soft * 0.4;
    float box = (1.0 - smoothstep(boxSoft * -0.6, boxSoft, U)) * facing;
    b += vec3(2.9, 2.87, 2.82) * box;

    // Side vignette: darken toward the left/right edges of the reflection.
    float vig = smoothstep(0.5, 0.92, abs(ex));
    b *= mix(vec3(1.0), vec3(mix(0.55, 0.07, shadows)), vig);

    // The warm strip light hugging the softbox edge (an amber fringe).
    float gw = 0.065 + softEff * 0.05;
    float jd = max(U, 0.0);
    float strip = exp(-((jd / gw) * (jd / gw))) * smoothstep(-0.06, 0.1, U);
    b += warmC * (strip * spectral * 1.3) * warmSide * facing;

    // A warm floor bounce along the bottom horizon.
    float fb = (ey + 0.12) / 0.05;
    b += warmC * (exp(-(fb * fb)) * spectral * 0.5) * warmSide * (1.0 - facing);

    // A dim cool card below.
    float cardX = abs(px) - 0.7;
    float cardY = abs(py + 0.78) - 0.05;
    float dCard = length(max(vec2(cardX, cardY), vec2(0.0))) + min(max(cardX, cardY), 0.0);
    float card = (1.0 - smoothstep(boxSoft * -0.6, boxSoft, dCard)) * facing;
    b += vec3(0.5, 0.5, 0.52) * card;

    return b;
}

void main() {
    vec4 base = texture(u_image0, v_texCoord);
    float shortSide = min(u_resolution.x, u_resolution.y);
    vec2 asp = u_resolution / shortSide;
    vec2 p = v_texCoord * asp;

    // ---- Where the shape is, how far from its edge, and the outward edge direction ----
    vec2 c, rel, outward;
    vec2 domeGrad = vec2(0.0);    // screen-space gradient of the height field (the dome)
    float cover, edgeD;            // edgeD: 0 on the outline, 1 at the deepest interior point
    if (u_hasShape > 0.5) {
        c = vec2(u_shapeCX, u_shapeCY) * asp;
        rel = p - c;
        // edgeD from the BLURRED distance field (dfield erases the thumbnail's steps). Four
        // neighbour samples serve BOTH the outward direction (raw distance gradient) and the dome
        // (gradient of the height field domeH) — one set of taps, so the shape branch is 5 dfield
        // reads, not nine.
        edgeD = dfield(v_texCoord);
        vec2 e0 = 16.0 / u_resolution;
        float dpx = dfield(v_texCoord + vec2(e0.x, 0.0));
        float dnx = dfield(v_texCoord - vec2(e0.x, 0.0));
        float dpy = dfield(v_texCoord + vec2(0.0, e0.y));
        float dny = dfield(v_texCoord - vec2(0.0, e0.y));
        vec2 grd = vec2(dpx - dnx, dpy - dny) / asp;
        float gl = length(grd);
        outward = gl > 1e-6 ? -grd / gl : vec2(0.0, 1.0);    // toward the nearest edge
        domeGrad = vec2(domeH(dpx) - domeH(dnx), domeH(dpy) - domeH(dny)) / asp;
        // The compositor clips this fill to the layer's FULL-RESOLUTION silhouette (destination-in
        // in applyGlassFromLayer), so that crisp clip is the outline. Live fields render at
        // LIVE_FIELD_PX and are upscaled, so ANY cover that fades near the edge here upscales soft
        // and then multiplies the crisp clip — softening it. Paint solid; let the clip cut the edge.
        cover = 1.0;
    } else {
        // As a material with no silhouette handed over — a 3D surface, a Space Type / Shape fill,
        // or the catalog preview — the chrome coats the whole tile: full cover, deep interior
        // (edgeD = 1, so no edge bevel), the dome measured radially from the tile centre.
        c = 0.5 * asp;
        rel = p - c;
        outward = length(rel) > 1e-5 ? normalize(rel) : vec2(0.0, 1.0);
        cover = 1.0;
        edgeD = 1.0;
    }
    // Everything below is measured in SHAPE-NORMALISED coordinates: `rel` divided by the
    // shape's own half-extent (u_shapeSize in the Frame, half the short side otherwise), so
    // relN spans about [-1, 1] across the shape at ANY size. A small chip and a frame-filling
    // clover then dome and reflect identically — measuring in absolute frame units made a large
    // shape over-tilt into a flat top-to-bottom gradient, the "just cut, not applied" look.
    float unit = u_hasShape > 0.5 ? max(u_shapeSize, 0.05) : 0.5;
    vec2 relN = rel / unit;
    float flenN = length(relN);
    vec2 rdir = flenN > 1e-5 ? relN / flenN : vec2(0.0, 1.0);

    // ---- The polished bevel + convex dome, both inflated from the distance field ----
    // The bevel is a machined rim profile over the outer edgeD band; the dome puffs the whole
    // face from every edge and lies flat at the deepest interior (where it faces the viewer and
    // catches the softbox). Both lean along `outward` (the smoothed distance-field gradient), so
    // the surface reads as one pillow that follows the shape. No waviness on the rim line and no
    // fade onto the face — those flattened and scraggled the earlier version.
    float bw = max(u_bevelWidth, 0.005) * 3.0;           // bevel width in edgeD units
    float t0 = clamp(edgeD / bw, 0.0, 1.0);              // 0 at the outline, 1 at the flat face
    float sBev = bevelSin(t0, u_bevelShape);             // the machined rim profile, 0 past the bevel

    vec2 txy;
    if (u_hasShape > 0.5) {
        // The dome is the SCREEN-space gradient of the height field domeH(distance): it puffs the
        // whole shape and follows the outline (cleft and lobes), yet stays smooth across the
        // medial axis — where domeH is a rounded ridge, so its gradient tapers to zero instead of
        // flipping like the raw distance gradient (that flip was the fan-crease).
        vec2 domeXY = -domeGrad * (u_curvature * 2.6);
        // The bevel rim leans outward on top of the dome.
        txy = domeXY + outward * (sBev * 0.6);
    } else {
        // Bare material (no silhouette): a radial dome sweeps the studio across the flat tile.
        float sSphere = u_curvature * 0.75 * smoothstep(0.0, 2.3, flenN);
        txy = rdir * sSphere;
    }
    float tl = min(length(txy), 0.9995);
    vec2 tn = length(txy) > 1e-4 ? txy * (tl / length(txy)) : vec2(0.0);
    float nz = sqrt(max(1.0 - tl * tl, 0.0));
    // The normal points AWAY from the eye (−z): the studio sits on the far side and is seen by
    // reflection, so a flat face pointing at the viewer catches the big frontal softbox.
    vec3 N = vec3(tn, -nz);

    // ---- Waviness: a broad, slowly drifting tilt so the surface reads as pressed metal ----
    float time = u_time * u_speed;
    vec2 wg = vec2(vnoise(relN * 0.23 + vec2(time * 0.08, 3.1)) - 0.5,
                   vnoise(relN * 0.23 + vec2(-1.7, time * 0.08 + 8.4)) - 0.5);
    N = normalize(N + vec3(wg, 0.0) * u_waviness * 0.6);

    // ---- Reflect a slightly perspective view ray, then orbit the studio around ----
    // The perspective is in shape units (relN) so the reflection sweep is the same across sizes.
    vec3 T = normalize(vec3(relN * 0.12, 1.0));          // view ray toward the eye, mild perspective
    vec3 R = reflect(T, N);
    float fres = clamp(abs(dot(N, T)), 0.0, 1.0);

    float rotA = radians(u_envRotation) + sin(time * 0.23) * 0.05;
    float ec = cos(rotA), es = sin(rotA);
    float upY = -R.y;
    float rx0 = R.x * ec - upY * es;
    float ry0 = R.x * es + upY * ec;
    float orbit = sin(time * 0.5) * 0.4 + sin(time * 0.19 + 1.7) * 0.2;
    float oc = cos(orbit), os = sin(orbit);
    float rx = rx0 * oc + R.z * os;
    float rz0 = R.z * oc - rx0 * os;
    float nod = sin(time * 0.31 + 0.9) * 0.12;
    float nc = cos(nod), ns = sin(nod);
    float ry = ry0 * nc - rz0 * ns;
    float rz = rz0 * nc + ry0 * ns;
    vec3 dir = vec3(rx, ry, rz);

    float grazing = smoothstep(0.75, 1.0, 1.0 - abs(N.z));   // high at the rim, where |N.z| is small
    float softEff = u_softness + grazing * 0.2;

    // ---- Studio reflection, with prismatic dispersion on the fast-curving bevel ----
    vec3 env = studio(dir, softEff, u_softness, u_spectral, u_shadows, u_warmColor, u_coolColor);
    float delta = u_dispersion * (0.004 + fres * fres * 0.06);
    vec3 envR = studio(vec3(dir.x, dir.y + delta, dir.z), softEff, u_softness, u_spectral, u_shadows, u_warmColor, u_coolColor);
    vec3 envB = studio(vec3(dir.x, dir.y - delta, dir.z), softEff, u_softness, u_spectral, u_shadows, u_warmColor, u_coolColor);
    vec3 col = vec3(envR.x, env.y, envB.z);

    col = col * u_environment * u_tint;
    col = vec3(1.0) - exp(-col);                          // gentle exposure tonemap, keeps chrome brilliance

    fragColor0 = vec4(mix(base.rgb, clamp(col, 0.0, 1.0), cover), mix(base.a, 1.0, cover));
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// LIQUID METAL: a pool of molten chrome in a shape. Flowing folds bend a reflected
// studio across the surface, a bevel runs round the edge catching its own line of
// light, and the picture beneath shows faintly in the reflection. A port of the
// Shaders.com "LiquidMetal" component (circle shape); its defaults are the
// "Fluid Chrome" design.
//
// A material coats whatever it is applied to. On a 3D surface, a Space Type / Shape fill,
// or the catalog preview it fills the ENTIRE tile; in the Frame the Frame hands over the
// layer's silhouette (u_shape: R the rim field, G the distance to the outline), so the pool
// and its bevel fill whatever shape the layer is.

uniform vec3  u_lightColor;      // the bright tone of the chrome
uniform vec3  u_darkColor;       // the tone the reflection falls to in shadow
uniform float u_turbulence;      // how molten: depth of the flowing folds
uniform float u_ripple;          // scale of the folds, higher = busier
uniform float u_warp;            // swirl: domain-warps the folds into curls
uniform float u_environment;     // strength of the reflected studio
uniform float u_envRotation;     // turns the reflected studio, degrees
uniform float u_sharpness;       // 1 = razor glints, 0 = soft satin
uniform float u_dispersion;      // colour fringing along the reflection edges
uniform float u_lightAngle;      // key light direction, degrees clockwise from the right
uniform float u_bevelWidth;      // width of the edge bevel, relative to the shape
uniform float u_bevelShape;      // 0 one round fillet, 1 machined: fillet, chamfer, knee
uniform float u_edgeSoftness;    // softness of the boundary

// Supplied by the Frame when the effect follows a layer's shape (see glass_lens).
uniform sampler2D u_shape;
uniform float u_hasShape;
uniform float u_shapeCX;
uniform float u_shapeCY;
uniform float u_shapeSize;

const float PI = 3.14159265359;

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}
float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i), b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0)), d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p) {
    // Three octaves only: molten metal has broad folds, not grain.
    float s = 0.0, a = 0.55;
    for (int i = 0; i < 3; i++) { s += a * vnoise(p); p = p * 1.9 + 11.7; a *= 0.45; }
    return s;
}
mat2 rot2(float a) { float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }

// The molten surface height at a point: folds, domain-warped into curls, drifting.
float surface(vec2 q, float t) {
    vec2 w = vec2(fbm(q * 0.6 + vec2(0.0, t * 0.35)), fbm(q * 0.6 + vec2(5.2, -t * 0.28)));
    q += (w - 0.5) * u_warp * 2.2;
    return fbm(q + vec2(t * 0.22, -t * 0.17));
}

// The reflected studio: a dark room with two softboxes and a horizon, looked up by
// the surface normal's tilt.
float studio(vec2 d) {
    vec2 r = rot2(radians(u_envRotation)) * d;
    // Two wide softboxes above and a floor glow below: a fold catches a white line
    // where its normal sweeps through a box, and falls to black between them.
    float box1 = smoothstep(0.55, 0.12, abs(r.y - 0.45)) * smoothstep(1.3, 0.2, abs(r.x + 0.2));
    float box2 = smoothstep(0.35, 0.05, abs(r.y + 0.5)) * smoothstep(1.4, 0.3, abs(r.x - 0.3)) * 0.7;
    float side = smoothstep(0.5, 0.15, abs(r.x - 0.9)) * smoothstep(0.9, 0.1, abs(r.y)) * 0.6;
    return clamp(box1 + box2 + side, 0.0, 1.5);
}

void main() {
    vec4 base = texture(u_image0, v_texCoord);
    float shortSide = min(u_resolution.x, u_resolution.y);
    vec2 asp = u_resolution / shortSide;
    vec2 p = v_texCoord * asp;

    // ---- Where the pool is, and how far from its edge ----
    vec2 c, rel, outward;
    float cover, edgeD;            // edgeD: distance inward from the outline, 0 on the edge, 1 at the deepest point
    if (u_hasShape > 0.5) {
        c = vec2(u_shapeCX, u_shapeCY) * asp;
        rel = p - c;
        vec4 sh = texture(u_shape, v_texCoord);
        // The outward direction comes from the RIM field (R): it is blurred at full
        // resolution, so its gradient is smooth along the edge, where the distance
        // field (G) is upscaled from a thumbnail and would stair-step the bevel.
        vec2 px = 1.5 / u_resolution;
        float gx = texture(u_shape, v_texCoord + vec2(px.x, 0.0)).r - texture(u_shape, v_texCoord - vec2(px.x, 0.0)).r;
        float gy = texture(u_shape, v_texCoord + vec2(0.0, px.y)).r - texture(u_shape, v_texCoord - vec2(0.0, px.y)).r;
        vec2 g = vec2(gx, gy) / asp;
        float gl = length(g);
        outward = gl > 1e-6 ? -g / gl : vec2(0.0, 1.0);
        // Paint solid: the compositor clips this fill to the layer's FULL-RES silhouette
        // (destination-in in applyGlassFromLayer), so that crisp clip IS the outline. A cover that
        // fades near the edge here renders at LIVE_FIELD_PX, upscales soft, and then multiplies the
        // crisp clip — softening the edge (see chrome). Let the clip cut it.
        cover = 1.0;
        edgeD = sh.g;                                   // the distance field, deepest point = 1
    } else {
        // As a MATERIAL with no silhouette handed over — a 3D surface, a Space Type / Shape
        // fill, or the catalog preview — the molten chrome coats the ENTIRE surface. A material
        // fills whatever it is applied to, so there is no stand-alone circle and no border
        // bevel (a bevel at the UV border would seam a sphere or a wrapped glyph). The mesh's
        // own edges are its outline: every texel is deep interior — full cover, edgeD = 1 (flat
        // top, the molten surface at full strength) — and the ripple is measured from the centre.
        c = 0.5 * asp;
        rel = p - c;
        outward = vec2(0.0, 1.0);
        cover = 1.0;
        edgeD = 1.0;
    }

    // ---- The bevel round the edge: a height profile over the bevel width ----
    float bw = max(u_bevelWidth, 0.005) * 2.0;           // bevel width in edgeD units
    float t = clamp(edgeD / bw, 0.0, 1.0);               // 0 at the edge, 1 where the flat top begins
    float round = sqrt(max(1.0 - (1.0 - t) * (1.0 - t), 0.0));       // one smooth fillet
    float machined = smoothstep(0.0, 0.25, t) * 0.55 + smoothstep(0.35, 0.6, t) * 0.25 + smoothstep(0.75, 1.0, t) * 0.2;
    float prof = mix(round, machined, u_bevelShape);
    // Slope of the profile → how far the normal leans outward at the bevel.
    float dt = 0.02;
    float t2 = clamp(t + dt, 0.0, 1.0);
    float round2 = sqrt(max(1.0 - (1.0 - t2) * (1.0 - t2), 0.0));
    float machined2 = smoothstep(0.0, 0.25, t2) * 0.55 + smoothstep(0.35, 0.6, t2) * 0.25 + smoothstep(0.75, 1.0, t2) * 0.2;
    float slope = (mix(round2, machined2, u_bevelShape) - prof) / dt;   // 0 on the flat top
    float bevelLean = clamp(slope * 0.9, 0.0, 3.0) * (1.0 - step(1.0, t));

    // ---- The molten surface: normal from the height field ----
    float time = u_time * 0.5;
    vec2 q = rel * u_ripple * 0.65;
    float e = 0.012 * u_ripple;
    float h0 = surface(q, time);
    float hx = surface(q + vec2(e, 0.0), time);
    float hy = surface(q + vec2(0.0, e), time);
    vec2 grad = vec2(hx - h0, hy - h0) / e;
    float molten = u_turbulence * 1.1 * smoothstep(0.0, 0.35, t);     // the bevel stays smooth
    vec3 N = normalize(vec3(-grad * molten + outward * bevelLean, 1.0));

    // ---- Chrome: the studio reflected in the surface, the picture beneath faintly ----
    float sharp = mix(4.0, 48.0, u_sharpness);
    vec2 look = N.xy * 1.6;                                            // where the reflection looks
    float disp = u_dispersion * 0.12;
    vec3 env = vec3(studio(look * (1.0 + disp)), studio(look), studio(look * (1.0 - disp))) * u_environment;
    vec2 refl = v_texCoord + N.xy * 0.18 / asp;
    // GLOSSY reflection of the layers behind (only the brightness is used, to shade the chrome):
    // sample the backdrop through a small disc blur, WIDENED where the reflection compresses — the
    // fast-curving bevel, where fwidth(refl) is large. A sharp mirror of a busy background aliases
    // into scraggle there; the blur turns it into soft chrome. Base radius eases with Sharpness.
    float gloss = mix(0.02, 0.004, clamp(u_sharpness, 0.0, 1.0)) + (fwidth(refl.x) + fwidth(refl.y)) * 1.5;
    vec2 gx = vec2(gloss, 0.0), gy = vec2(0.0, gloss), gd = vec2(gloss, gloss) * 0.70711;
    vec3 sc = texture(u_image0, clamp(refl, 0.0, 1.0)).rgb * 2.0;
    sc += texture(u_image0, clamp(refl + gx, 0.0, 1.0)).rgb + texture(u_image0, clamp(refl - gx, 0.0, 1.0)).rgb;
    sc += texture(u_image0, clamp(refl + gy, 0.0, 1.0)).rgb + texture(u_image0, clamp(refl - gy, 0.0, 1.0)).rgb;
    sc += texture(u_image0, clamp(refl + gd, 0.0, 1.0)).rgb + texture(u_image0, clamp(refl - gd, 0.0, 1.0)).rgb;
    sc += texture(u_image0, clamp(refl + vec2(gd.x, -gd.y), 0.0, 1.0)).rgb
        + texture(u_image0, clamp(refl + vec2(-gd.x, gd.y), 0.0, 1.0)).rgb;
    sc /= 10.0;
    float sceneLum = dot(sc, vec3(0.299, 0.587, 0.114));
    float shade = clamp(env.g * 0.85 + sceneLum * 0.35 * u_environment, 0.0, 1.0);
    shade = smoothstep(0.02, 0.9, shade);                              // chrome contrast
    vec3 col = mix(u_darkColor, u_lightColor, shade);
    col += (env - env.g) * 0.5 * u_lightColor;                         // the dispersion fringe
    // Key light: a specular glint on the folds and along the bevel.
    float la = radians(u_lightAngle);
    vec3 L = normalize(vec3(cos(la), -sin(la), 0.7));
    vec3 H = normalize(L + vec3(0.0, 0.0, 1.0));
    float spec = pow(max(dot(N, H), 0.0), sharp);
    col += u_lightColor * spec * (0.6 + 0.6 * u_environment);
    // Fresnel-ish lift where the surface turns away.
    float rim = pow(1.0 - max(N.z, 0.0), 3.0);
    col += u_lightColor * rim * 0.25;

    fragColor0 = vec4(mix(base.rgb, clamp(col, 0.0, 1.0), cover), mix(base.a, 1.0, cover));
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_lineSize;
uniform float u_scanline;
uniform float u_curvature;
uniform float u_vignette;

void main() {
    // Barrel curvature.
    vec2 cc = v_texCoord * 2.0 - 1.0;
    cc *= 1.0 + u_curvature * 0.25 * dot(cc, cc);
    vec2 uv = cc * 0.5 + 0.5;
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        fragColor0 = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    vec3 col = texture(u_image0, uv).rgb;

    // Scanlines (resolution-independent: spacing is a fraction of height).
    float sl = sin(uv.y / max(u_lineSize, 0.003) * 3.14159);
    col *= 1.0 - u_scanline * (1.0 - sl * sl);

    // Soft RGB aperture grille in aspect space.
    float aspc = u_resolution.x / u_resolution.y;
    float g = fract(uv.x * aspc / (max(u_lineSize, 0.003) * 1.5));
    vec3 mask = vec3(
        smoothstep(0.5, 0.16, abs(g - 0.16)),
        smoothstep(0.5, 0.16, abs(g - 0.5)),
        smoothstep(0.5, 0.16, abs(g - 0.84))
    );
    col *= mix(vec3(1.0), 0.5 + 0.5 * mask, u_scanline * 0.6);

    // Vignette + brightness compensation.
    col *= clamp(1.0 - u_vignette * dot(cc, cc) * 0.6, 0.0, 1.0);
    col *= 1.0 + u_scanline * 0.4;
    fragColor0 = vec4(clamp(col, 0.0, 1.0), 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_amount;
uniform float u_radius;
uniform float u_softness;
uniform float u_roundness;

void main() {
    vec3 col = texture(u_image0, v_texCoord).rgb;
    float aspc = u_resolution.x / u_resolution.y;
    vec2 d = v_texCoord - 0.5;
    d.x *= mix(aspc, 1.0, u_roundness);   // elliptical → circular
    float r = length(d) * 2.0;
    float soft = max(u_softness, 0.001);
    float v = smoothstep(u_radius + soft, u_radius - soft, r);
    col *= mix(1.0, v, u_amount);
    fragColor0 = vec4(col, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_pass;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_radius;

// Separable Gaussian: pass 0 blurs horizontally, pass 1 vertically.
void main() {
    vec2 texel = 1.0 / u_resolution;
    vec2 dir = (u_pass < 0.5) ? vec2(texel.x, 0.0) : vec2(0.0, texel.y);
    float sigma = max(u_radius * u_resolution.y, 1.0);
    int K = int(clamp(sigma * 2.0, 1.0, 24.0));

    vec3 sum = texture(u_image0, v_texCoord).rgb;
    float wsum = 1.0;
    for (int i = 1; i <= 24; i++) {
        if (i > K) break;
        float w = exp(-0.5 * float(i * i) / (sigma * sigma));
        sum += texture(u_image0, clamp(v_texCoord + dir * float(i), 0.0, 1.0)).rgb * w;
        sum += texture(u_image0, clamp(v_texCoord - dir * float(i), 0.0, 1.0)).rgb * w;
        wsum += 2.0 * w;
    }
    fragColor0 = vec4(sum / wsum, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform sampler2D u_source;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_pass;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_threshold;
uniform float u_radius;
uniform float u_intensity;

vec3 sampleBlur(vec2 dir, float sigma) {
    int K = int(clamp(sigma * 2.0, 1.0, 24.0));
    vec3 sum = texture(u_image0, v_texCoord).rgb;
    float wsum = 1.0;
    for (int i = 1; i <= 24; i++) {
        if (i > K) break;
        float w = exp(-0.5 * float(i * i) / (sigma * sigma));
        sum += texture(u_image0, clamp(v_texCoord + dir * float(i), 0.0, 1.0)).rgb * w;
        sum += texture(u_image0, clamp(v_texCoord - dir * float(i), 0.0, 1.0)).rgb * w;
        wsum += 2.0 * w;
    }
    return sum / wsum;
}

// 4 passes: bright-pass → H-blur → V-blur → add blurred highlights to the original.
void main() {
    vec2 texel = 1.0 / u_resolution;
    float sigma = max(u_radius * u_resolution.y, 1.0);
    int p = int(u_pass + 0.5);
    if (p == 0) {
        vec3 c = texture(u_image0, v_texCoord).rgb;
        // Brightness from the max channel, not luma: saturated colour highlights
        // (esp. blue, which luma weights at only 0.114) must bloom on neon imagery.
        float l = max(max(c.r, c.g), c.b);
        float b = max(l - u_threshold, 0.0) / max(1.0 - u_threshold, 0.001);
        fragColor0 = vec4(c * b, 1.0);
    } else if (p == 1) {
        fragColor0 = vec4(sampleBlur(vec2(texel.x, 0.0), sigma), 1.0);
    } else if (p == 2) {
        fragColor0 = vec4(sampleBlur(vec2(0.0, texel.y), sigma), 1.0);
    } else {
        vec3 orig = texture(u_source, v_texCoord).rgb;
        vec3 glow = texture(u_image0, v_texCoord).rgb;
        fragColor0 = vec4(clamp(orig + glow * u_intensity, 0.0, 1.0), 1.0);
    }
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform sampler2D u_source;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_pass;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_threshold;
uniform float u_radius;
uniform float u_intensity;

vec3 sampleBlur(vec2 dir, float sigma) {
    int K = int(clamp(sigma * 2.0, 1.0, 24.0));
    vec3 sum = texture(u_image0, v_texCoord).rgb;
    float wsum = 1.0;
    for (int i = 1; i <= 24; i++) {
        if (i > K) break;
        float w = exp(-0.5 * float(i * i) / (sigma * sigma));
        sum += texture(u_image0, clamp(v_texCoord + dir * float(i), 0.0, 1.0)).rgb * w;
        sum += texture(u_image0, clamp(v_texCoord - dir * float(i), 0.0, 1.0)).rgb * w;
        wsum += 2.0 * w;
    }
    return sum / wsum;
}

// Like bloom but screen-blended and lower threshold — a soft dreamy glow over
// the whole image rather than just clipped highlights.
void main() {
    vec2 texel = 1.0 / u_resolution;
    float sigma = max(u_radius * u_resolution.y, 1.0);
    int p = int(u_pass + 0.5);
    if (p == 0) {
        vec3 c = texture(u_image0, v_texCoord).rgb;
        // Max-channel brightness so saturated colour highlights glow (luma buries blue).
        float l = max(max(c.r, c.g), c.b);
        float b = smoothstep(u_threshold - 0.2, u_threshold + 0.2, l);
        fragColor0 = vec4(c * b, 1.0);
    } else if (p == 1) {
        fragColor0 = vec4(sampleBlur(vec2(texel.x, 0.0), sigma), 1.0);
    } else if (p == 2) {
        fragColor0 = vec4(sampleBlur(vec2(0.0, texel.y), sigma), 1.0);
    } else {
        vec3 orig = texture(u_source, v_texCoord).rgb;
        vec3 g = clamp(texture(u_image0, v_texCoord).rgb * u_intensity, 0.0, 1.0);
        fragColor0 = vec4(1.0 - (1.0 - orig) * (1.0 - g), 1.0);   // screen blend
    }
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform sampler2D u_source;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_pass;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_radius;
uniform float u_focus;
uniform float u_width;

vec3 sampleBlur(vec2 dir, float sigma) {
    int K = int(clamp(sigma * 2.0, 1.0, 24.0));
    vec3 sum = texture(u_image0, v_texCoord).rgb;
    float wsum = 1.0;
    for (int i = 1; i <= 24; i++) {
        if (i > K) break;
        float w = exp(-0.5 * float(i * i) / (sigma * sigma));
        sum += texture(u_image0, clamp(v_texCoord + dir * float(i), 0.0, 1.0)).rgb * w;
        sum += texture(u_image0, clamp(v_texCoord - dir * float(i), 0.0, 1.0)).rgb * w;
        wsum += 2.0 * w;
    }
    return sum / wsum;
}

// 3 passes: H-blur → V-blur → keep a sharp horizontal focus band, blur the rest
// (miniature/tilt-shift look).
void main() {
    vec2 texel = 1.0 / u_resolution;
    float sigma = max(u_radius * u_resolution.y, 1.0);
    int p = int(u_pass + 0.5);
    if (p == 0) {
        fragColor0 = vec4(sampleBlur(vec2(texel.x, 0.0), sigma), 1.0);
    } else if (p == 1) {
        fragColor0 = vec4(sampleBlur(vec2(0.0, texel.y), sigma), 1.0);
    } else {
        vec3 sharp = texture(u_source, v_texCoord).rgb;
