// normal is taken from it by central differences, and refraction, dispersion and
// sheen all fall out of that normal. Adding a tenth pattern is one more case in
// heightAt() — no new refraction maths.
uniform float u_mode;        // pattern: 0 reeded, 1 concentric, 2 pillows, 3 brick,
                             //   4 raindrops, 5 zigzag, 6 hex, 7 wobble, 8 frost
uniform float u_count;       // cell size, as cells across the frame
uniform float u_refraction;  // depth: how far the surface bends the image
uniform float u_relief;      // how steep the height field reads (normal strength)
uniform float u_chromatic;   // dispersion: per-channel split, strongest off-axis
uniform float u_blur;        // smear along the ridge
uniform float u_sheen;       // specular highlight off the normal
uniform float u_lightAngle;  // where the sheen comes from, in degrees
uniform float u_angle;       // pattern rotation in degrees (90 = vertical flutes)
uniform float u_mortar;      // brick only: gap between bricks
uniform float u_rainSeed;    // raindrops only: reshuffles the drops
uniform float u_centerX;     // concentric only
uniform float u_centerY;

const float PI = 3.14159265359;
const int NMAX = 16;

float g_aspect;   // set once in main(); heightAt() needs it for the ring centre

// ---------------------------------------------------------------- noise utils

float hash21(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

vec2 hash22(vec2 p) {
    vec2 k = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return fract(sin(k) * 43758.5453123);
}

float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 4; i++) { v += a * vnoise(p); p *= 2.02; a *= 0.5; }
    return v;
}

// ------------------------------------------------------------ height profiles

// A half-cylinder lying across the axis: 1 down the middle of the cell, 0 at the
// seam. The square root is what makes it a true cylinder — the surface turns away
// fastest at the edges, which is where glass bends light hardest.
float cylProfile(float x) {
    float f = fract(x) - 0.5;
    return sqrt(max(0.25 - f * f, 0.0)) * 2.0;
}

// -0.5..0.5 triangle wave, period 1.
float triWave(float x) {
    return abs(fract(x) - 0.5) * 2.0 - 0.5;
}

// Flat face with a chamfer round it, rows offset by half a brick. Flat means no
// bend at all across the middle of a brick, which is what stops it reading as a grid.
float brickHeight(vec2 q) {
    vec2 c = vec2(q.x * 0.5, q.y);              // a brick is 2 cells wide, 1 tall
    c.x += 0.5 * mod(floor(c.y), 2.0);
    vec2 f = fract(c) - 0.5;
    // distance to the nearest brick edge, back in q units
    float e = min((0.5 - abs(f.x)) * 2.0, 0.5 - abs(f.y));
    return smoothstep(u_mortar, u_mortar + 0.22, e);
}

// Rounded blobs sitting on the pane, each one its own little lens. Drops are
// spherical caps on a jittered grid, combined with max() so they sit on top of
// each other rather than piling up.
float rainHeight(vec2 q) {
    vec2 base = floor(q);
    float h = 0.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 g = base + vec2(float(x), float(y));
            vec2 j = hash22(g + u_rainSeed * 7.31);
            vec2 c = g + 0.15 + j * 0.7;
            float rad = 0.16 + hash21(g * 1.37 + u_rainSeed * 3.7) * 0.30;
            float d = length(q - c) / max(rad, 1e-4);
            h = max(h, sqrt(max(1.0 - d * d, 0.0)));
        }
    }
    return h;
}

// Reeds whose lines zigzag as they go. The zigzag displaces the whole run rather
// than each reed on its own, so the reeds stay parallel and the run bends.
float zigzagHeight(vec2 q) {
    return cylProfile(q.x + triWave(q.y * 0.15) * 3.0);
}

// Three ridges at sixty degrees to each other. min() keeps the seams crisp, so
// they meet in hexagonal facets rather than blurring into bumps.
float hexHeight(vec2 q) {
    float a0 = cylProfile(q.x);
    float a1 = cylProfile(dot(q, vec2(0.5, 0.8660254)));
    float a2 = cylProfile(dot(q, vec2(-0.5, 0.8660254)));
    return min(min(a0, a1), a2);
}

// Noise pushed around by more noise, which is what turns blobs into something
// that flows.
float wobbleHeight(vec2 q) {
    vec2 w = vec2(fbm(q * 0.5 + 11.3), fbm(q * 0.5 + 41.7));
    return fbm(q * 0.5 + w * 2.0);
}

// The same texture at three sizes, the finest too small to read as a lens on its
// own. Not true frosting, which scatters rather than bends, but the same job.
float frostHeight(vec2 q) {
    return vnoise(q * 0.6) * 0.55 + vnoise(q * 1.7) * 0.30 + vnoise(q * 4.6) * 0.15;
}

// The height field, sampled in aspect-corrected square space.
float heightAt(vec2 s) {
    int mode = int(u_mode + 0.5);
    float n = max(u_count, 1.0);

    if (mode == 1) {                                       // concentric rings
        vec2 c = vec2(u_centerX * g_aspect, u_centerY);
        return cylProfile(length(s - c) * n);
    }

    float a = radians(u_angle);
    vec2 acrossUnit = vec2(-sin(a), cos(a));
    vec2 alongUnit = vec2(cos(a), sin(a));
    vec2 q = vec2(dot(s, acrossUnit), dot(s, alongUnit)) * n;

    if (mode == 2) return cylProfile(q.x) * cylProfile(q.y);   // pillows
    if (mode == 3) return brickHeight(q);
    if (mode == 4) return rainHeight(q);
    if (mode == 5) return zigzagHeight(q);
    if (mode == 6) return hexHeight(q);
    if (mode == 7) return wobbleHeight(q);
    if (mode == 8) return frostHeight(q);
    return cylProfile(q.x);                                    // 0: reeded
}

// -------------------------------------------------------------------- render

void main() {
    g_aspect = u_resolution.x / max(u_resolution.y, 1.0);
    vec2 s = vec2(v_texCoord.x * g_aspect, v_texCoord.y);
    float n = max(u_count, 1.0);

    // Slope by central differences. eps is a fraction of a CELL, not of a pixel,
    // so the surface reads the same at preview size and at bake size. It also
    // caps the slope at the seams, where a true cylinder's derivative runs away.
    float eps = 0.08 / n;
    vec2 grad = vec2(
        heightAt(s + vec2(eps, 0.0)) - heightAt(s - vec2(eps, 0.0)),
        heightAt(s + vec2(0.0, eps)) - heightAt(s - vec2(0.0, eps))
    ) / (2.0 * eps * n);   // /n keeps the slope scale-free as cell size changes

    vec3 nrm = normalize(vec3(-grad * u_relief, 1.0));

    // Refraction: push the sample along the surface tilt. depth/count reproduces
    // the old cylinder's displacement scale, so saved layers land where they were.
    vec2 moveS = nrm.xy * (u_refraction / n) * 0.5;
    vec2 base = v_texCoord + vec2(moveS.x / g_aspect, moveS.y);

    // Dispersion follows the same tilt, so it is strongest where the surface
    // turns away and vanishes flat-on — which is how glass actually behaves.
    vec2 crMove = nrm.xy * u_chromatic;
    vec2 crTex = vec2(crMove.x / g_aspect, crMove.y);

    // Smear runs perpendicular to the slope, i.e. ALONG the ridge. For reeded
    // flutes that is the flute axis, matching the old behaviour exactly.
    vec2 tang = (length(grad) > 1e-5) ? normalize(vec2(-grad.y, grad.x)) : vec2(1.0, 0.0);

    bool wantBlur = u_blur > 0.0005;
    bool wantDisp = u_chromatic > 0.0001;
    int taps = wantBlur ? NMAX : 1;

    vec3 col = vec3(0.0);
    for (int i = 0; i < NMAX; i++) {
        if (i >= taps) break;
        float t = (taps == 1) ? 0.0 : (float(i) / float(taps - 1) - 0.5);
        vec2 mS = tang * (t * u_blur);
        vec2 off = vec2(mS.x / g_aspect, mS.y);
        if (wantDisp) {
            col.r += texture(u_image0, clamp(base + off + crTex, 0.0, 1.0)).r;
            col.g += texture(u_image0, clamp(base + off, 0.0, 1.0)).g;
            col.b += texture(u_image0, clamp(base + off - crTex, 0.0, 1.0)).b;
        } else {
            col += texture(u_image0, clamp(base + off, 0.0, 1.0)).rgb;
        }
    }
    col /= float(taps);

    // Sheen: a specular glint off the same normal. Fixed viewer, light set by angle.
    if (u_sheen > 0.0001) {
        float la = radians(u_lightAngle);
        vec3 L = normalize(vec3(cos(la), sin(la), 0.85));
        vec3 H = normalize(L + vec3(0.0, 0.0, 1.0));
        col += pow(max(dot(nrm, H), 0.0), 48.0) * u_sheen;
    }

    fragColor0 = vec4(clamp(col, 0.0, 1.0), 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uint pcg(uint v) { v = v * 747796405u + 2891336453u; v = ((v >> ((v >> 28u) + 4u)) ^ v) * 277803737u; return (v >> 22u) ^ v; }
float hash2(vec2 ip, float seed) {
    uvec2 q = uvec2(ivec2(ip) + 32768);
    uint h = pcg(q.x ^ pcg(q.y ^ pcg(uint(int(seed)))));
    return float(h) * (1.0 / 4294967295.0);
}
float vnoise(vec2 p, float seed) {
    vec2 i = floor(p), f = fract(p);
    vec2 u2 = f * f * (3.0 - 2.0 * f);
    float a = hash2(i, seed), b = hash2(i + vec2(1, 0), seed);
    float c = hash2(i + vec2(0, 1), seed), d = hash2(i + vec2(1, 1), seed);
    return mix(mix(a, b, u2.x), mix(c, d, u2.x), u2.y);
}

uniform float u_amount;
uniform float u_scale;
uniform float u_warp;
uniform float u_detail;
uniform float u_speed;

// FBM with parameterized octave falloff, normalized so the output stays in
// [0,1] regardless of the falloff — keeps u_amount calibrated.
float fbmF(vec2 p, float seed, float falloff) {
    float v = 0.0, a = 0.5, norm = 0.0;
    for (int i = 0; i < 5; i++) {
        v += a * vnoise(p, seed + float(i) * 17.0);
        norm += a;
        p *= 2.03;
        a *= falloff;
    }
    return v / norm;
}

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    vec2 p = (v_texCoord - 0.5) * asp * u_scale;
    float t = u_time * u_speed * 0.2;
    float falloff = mix(0.35, 0.65, u_detail);

    // Two-stage domain warp (q feeds r) — the marbled wet-paint melt that
    // noise_distortion's single-stage offset can't reach.
    vec2 q = vec2(fbmF(p + vec2(0.0, t), u_seed, falloff),
                  fbmF(p + vec2(3.7, -t), u_seed + 5.0, falloff));
    vec2 r = vec2(fbmF(p + u_warp * q + vec2(1.7, 9.2) + t * 0.35, u_seed + 17.0, falloff),
                  fbmF(p + u_warp * q + vec2(8.3, 2.8) - t * 0.25, u_seed + 29.0, falloff));

    vec2 disp = (r - 0.5) * 2.0 * u_amount;
    fragColor0 = vec4(texture(u_image0, clamp(v_texCoord + disp, 0.0, 1.0)).rgb, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uint pcg(uint v) { v = v * 747796405u + 2891336453u; v = ((v >> ((v >> 28u) + 4u)) ^ v) * 277803737u; return (v >> 22u) ^ v; }
float hash2(vec2 ip, float seed) {
    uvec2 q = uvec2(ivec2(ip) + 32768);
    uint h = pcg(q.x ^ pcg(q.y ^ pcg(uint(int(seed)))));
    return float(h) * (1.0 / 4294967295.0);
}
float vnoise(vec2 p, float seed) {
    vec2 i = floor(p), f = fract(p);
    vec2 u2 = f * f * (3.0 - 2.0 * f);
    float a = hash2(i, seed), b = hash2(i + vec2(1, 0), seed);
    float c = hash2(i + vec2(0, 1), seed), d = hash2(i + vec2(1, 1), seed);
    return mix(mix(a, b, u2.x), mix(c, d, u2.x), u2.y);
}
float fbm3(vec2 p, float seed) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 3; i++) { v += a * vnoise(p, seed + float(i) * 17.0); p *= 2.03; a *= 0.5; }
    return v;
}

uniform float u_anchor;     // 0 none · 1 left · 2 right · 3 top · 4 bottom
uniform float u_amplitude;
uniform float u_frequency;
uniform float u_speed;
uniform float u_gust;
uniform float u_shading;

void main() {
    int anchor = int(u_anchor + 0.5);
    vec2 uv = v_texCoord;

    // s runs 0 at the anchored edge -> 1 at the free edge; displacement is
    // perpendicular to the wind axis. Horizontal anchors wave along x and
    // displace y; vertical anchors wave along y and displace x.
    float s, across;
    vec2 dispAxis, windAxis;
    if (anchor == 3 || anchor == 4) {
        s = (anchor == 3) ? 1.0 - uv.y : uv.y;
        across = uv.x;
        dispAxis = vec2(1.0, 0.0);
        windAxis = (anchor == 3) ? vec2(0.0, -1.0) : vec2(0.0, 1.0);
    } else {
        s = (anchor == 2) ? 1.0 - uv.x : uv.x;
        across = uv.y;
        dispAxis = vec2(0.0, 1.0);
        windAxis = (anchor == 2) ? vec2(-1.0, 0.0) : vec2(1.0, 0.0);
    }
    float env = (anchor == 0) ? 0.75 : smoothstep(0.0, 1.0, s);

    float t = u_time * u_speed;
    // Gust: slow FBM wobble travelling with the wind, so the wave never loops
    // robotically. Centered on 0.
    float gust = (fbm3(vec2(s * 2.0 - t * 0.7, across * 2.0), u_seed) - 0.5) * 2.0;
    float phase = s * u_frequency * 6.2831853 - t * 6.2831853
                + u_gust * gust * 2.0 + across * 0.9;
    // Primary wave + half-frequency harmonic; /1.5 keeps the sum in [-1,1].
    float wave = (sin(phase) + 0.5 * sin(phase * 0.5 + 1.7)) / 1.5;

    vec2 off = dispAxis * wave * env * u_amplitude;
    if (anchor != 0) {
        // Gravity sag toward the free edge (horizontal flags droop down;
        // vertical flags get a slight symmetric belly via the same term on x).
        float sag = 0.35 * u_amplitude * s * s;
        off += (anchor == 3 || anchor == 4) ? vec2(sag * 0.4, 0.0) : vec2(0.0, sag);
        // Fold compression: bunch the cloth along the wind on wave slopes.
        off += windAxis * (0.25 * u_amplitude * cos(phase) * env);
    }

    vec3 img = texture(u_image0, clamp(uv + off, 0.0, 1.0)).rgb;
    // Cloth shading from the wave slope — bright faces toward the light on
    // rising slopes, shadowed folds on falling ones.
    float light = 1.0 + u_shading * 0.45 * cos(phase) * env;
    fragColor0 = vec4(clamp(img * light, 0.0, 1.0), 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// Exposure / contrast / saturation / hue grade — the `color` post effect.
// Matches PostSettings' exposure, contrast, saturation, hue.
uniform float u_exposure;    // 0..3, 1 = neutral
uniform float u_contrast;    // 0..3, 1 = neutral
uniform float u_saturation;  // 0..3, 1 = neutral
uniform float u_hue;         // -1..1 turns, 0 = neutral

vec3 hueRotate(vec3 c, float turns) {
    float a = turns * 6.2831853;
    vec3 k = vec3(0.57735);
    float cs = cos(a);
    return c * cs + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - cs);
}

void main() {
    vec4 src = texture(u_image0, v_texCoord);
    vec3 c = src.rgb * u_exposure;
    c = (c - 0.5) * u_contrast + 0.5;
    float l = dot(c, vec3(0.2126, 0.7152, 0.0722));
    c = mix(vec3(l), c, u_saturation);
    if (abs(u_hue) > 0.0001) c = hueRotate(c, u_hue);
    // Alpha propagates untouched — colour grading must not affect transparency.
    fragColor0 = vec4(clamp(c, 0.0, 1.0), src.a);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// Film grain — the `grain` post effect. Ported from hashGrain in
// frontend/app/lib/gradientfx/shaders.ts:104-108 (Dave Hoskins "Hash without
// Sine") and its luminance-shaped midtone bias at shaders.ts:634-637, with the
// same canonical 0.16 coefficient, so Task 8's migrated Gradient documents
// render unchanged.
uniform float u_amount;      // 0..1, how strong the grain is
uniform float u_size;        // 1..8, how coarse the grain is (device px per cell)

float hashGrain(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

void main() {
    vec4 src = texture(u_image0, v_texCoord);

    // Sampled per DEVICE PIXEL (gl_FragCoord), same as the ported formula, so a
    // coarseness of 1 reproduces the original bit-for-bit. Larger u_size groups
    // pixels into coarser cells for a chunkier grain.
    vec2 coord = u_size > 1.0 ? floor(gl_FragCoord.xy / u_size) * u_size : gl_FragCoord.xy;
    float g = hashGrain(coord + u_seed) - 0.5;

    float lum = dot(src.rgb, vec3(0.299, 0.587, 0.114));
    float midtone = 0.35 + 0.65 * (lum * (1.0 - lum) * 4.0);   // 0.35 floor .. 1 at lum 0.5
    // Gated unconditionally on THIS pass's own input alpha — not a separate
    // uniform a caller has to remember to wire. An opaque catalog preview has
    // src.a == 1 (full grain, unaffected); a transparent pixel gets none;
    // a partially-transparent edge gets a proportionally scaled amount. This
    // makes every consumer of this frag (Shader Studio, shader-as-fill, the
    // ComfyUI node, and this chain) correct without any of them opting in.
    float gate = src.a;

    vec3 col = src.rgb + g * u_amount * 0.16 * midtone * gate;
    fragColor0 = vec4(clamp(col, 0.0, 1.0), src.a);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_amount;

// Screen-space UV warp — two decorrelated noise fields drive x/y, scaled to a
// pixel budget. Ported verbatim from shapefx/post.ts's POST_FRAG (its
// uDistort/uResolution/uSeed → this catalog's u_amount/u_resolution/u_seed).
float vhash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  float a = vhash(i), b = vhash(i + vec2(1.0, 0.0)), c = vhash(i + vec2(0.0, 1.0)), d = vhash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

void main() {
  vec2 uv = v_texCoord;
  if (u_amount > 0.0) {
    float n1 = vnoise(uv * 6.0 + u_seed);
    float n2 = vnoise(uv * 6.0 - u_seed + 17.3);
    vec2 px = (vec2(n1, n2) - 0.5) * (u_amount * 45.0);
    uv += px / max(u_resolution, vec2(1.0));
  }
  vec4 src = texture(u_image0, clamp(uv, 0.0, 1.0));
  fragColor0 = vec4(clamp(src.rgb, 0.0, 1.0), src.a);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_levels;     // number of contour lines
uniform float u_thickness;  // line thickness
uniform float u_mode;       // 0 over image, 1 dark lines on paper, 2 glow lines on dark
uniform float u_bands;      // hypsometric band tint amount

float luma(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }

// Topographic hypsometric ramp: low = teal, mid = green/olive, high = warm tan.
vec3 ramp(float t) {
    vec3 a = vec3(0.05, 0.18, 0.28), b = vec3(0.13, 0.42, 0.32);
    vec3 c = vec3(0.62, 0.55, 0.30), d = vec3(0.85, 0.80, 0.72);
    return (t < 0.5) ? mix(a, b, t * 2.0) : mix(c, d, (t - 0.5) * 2.0);
}

void main() {
    vec3 src = texture(u_image0, v_texCoord).rgb;
    float lum = luma(src);
    float lv = max(u_levels, 1.0);
    float f = lum * lv;

    // Iso-lines at integer crossings, anti-aliased via screen-space derivative.
    float aa = fwidth(f);
    float dEdge = abs(fract(f + 0.5) - 0.5);   // 0 at each level crossing
    float th = max(u_thickness, 0.01);
    float line = 1.0 - smoothstep(0.0, th * 0.5 + aa, dEdge);

    int m = int(u_mode + 0.5);
    vec3 bg = (m == 1) ? vec3(0.96, 0.94, 0.88)
            : (m == 2) ? vec3(0.03, 0.04, 0.06)
                       : src;

    if (u_bands > 0.0) {
        vec3 tint = ramp(clamp(floor(f) / lv, 0.0, 1.0));
        bg = mix(bg, tint, u_bands);
    }

    vec3 lineCol = (m == 2) ? vec3(0.55, 0.95, 0.75) : vec3(0.10, 0.12, 0.10);
    fragColor0 = vec4(mix(bg, lineCol, line), 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_density;   // dots across the short axis
uniform float u_jitter;    // 0..1 positional randomness
uniform float u_dotSize;   // radius multiplier
uniform float u_contrast;  // shapes darkness -> dot radius
uniform float u_mode;      // 0 ink on paper, 1 image color on white, 2 image color on black

vec2 hash22(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx + p3.yz) * p3.zy);
}

void main() {
    vec2 asp = vec2(u_resolution.x / u_resolution.y, 1.0);
    float dens = max(u_density, 4.0);
    vec2 g = v_texCoord * asp * dens;      // grid space
    vec2 cell = floor(g);
    vec2 f = fract(g);

    // Walk the 3x3 neighborhood so jittered dots can spill across cell borders.
    float ink = 0.0;                       // coverage of the winning dot
    vec3 dotCol = vec3(0.0);
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 nc = cell + vec2(float(x), float(y));
            vec2 jit = (hash22(nc + u_seed) - 0.5) * u_jitter;
            vec2 center = vec2(float(x), float(y)) + 0.5 + jit;
            vec2 uvc = (nc + 0.5 + jit) / dens / asp;   // where this dot samples the image
            vec3 col = texture(u_image0, clamp(uvc, 0.0, 1.0)).rgb;
            float lum = dot(col, vec3(0.299, 0.587, 0.114));
            float dark = pow(clamp(1.0 - lum, 0.0, 1.0), max(u_contrast, 0.001));
            float radius = sqrt(dark) * 0.5 * u_dotSize;
            float d = length(f - center);
            float aa = fwidth(d) + 1e-4;
            float cov = smoothstep(radius, radius - aa, d);
            if (cov > ink) { ink = cov; dotCol = col; }   // nearest/topmost dot wins
        }
    }

    int m = int(u_mode + 0.5);
    vec3 paper = (m == 2) ? vec3(0.0) : vec3(1.0);
    vec3 fill  = (m == 0) ? vec3(0.0) : dotCol;
    vec3 outc = mix(paper, fill, ink);
    fragColor0 = vec4(outc, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uniform float u_direction;  // 0 up, 1 down, 2 left, 3 right
uniform float u_low;        // threshold band low (luma)
uniform float u_high;       // threshold band high (luma)
uniform float u_length;     // max streak length (0..1 -> pixels)
uniform float u_mode;       // 0 brighten (carry lightest), 1 darken (carry darkest)

float luma(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }

void main() {
    vec2 texel = 1.0 / u_resolution;
    int dir = int(u_direction + 0.5);
    vec2 stp = (dir == 0) ? vec2(0.0, -texel.y)
             : (dir == 1) ? vec2(0.0,  texel.y)
             : (dir == 2) ? vec2(-texel.x, 0.0)
                          : vec2( texel.x, 0.0);
    vec2 march = -stp;   // walk against the streak to gather the span's extreme

    vec3 cur = texture(u_image0, v_texCoord).rgb;
    float curL = luma(cur);
    if (curL < u_low || curL > u_high) {   // pixels outside the band pass through
        fragColor0 = vec4(cur, 1.0);
        return;
    }

    int maxLen = int(clamp(u_length, 0.0, 1.0) * 252.0) + 4;
    bool darken = (u_mode >= 0.5);
    vec3 best = cur;
    float bestL = curL;
    vec2 uv = v_texCoord;
    for (int k = 0; k < 256; k++) {
        if (k >= maxLen) break;
        uv += march;
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) break;
        vec3 c = texture(u_image0, uv).rgb;
        float l = luma(c);
        if (l < u_low || l > u_high) break;              // span boundary
        if (darken ? (l < bestL) : (l > bestL)) { bestL = l; best = c; }
    }
    fragColor0 = vec4(best, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_hasInput;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uint pcg(uint v) { v = v * 747796405u + 2891336453u; v = ((v >> ((v >> 28u) + 4u)) ^ v) * 277803737u; return (v >> 22u) ^ v; }
float hash2(vec2 ip, float seed) {
    uvec2 q = uvec2(ivec2(ip) + 32768);
    uint h = pcg(q.x ^ pcg(q.y ^ pcg(uint(int(seed)))));
    return float(h) * (1.0 / 4294967295.0);
}
float vnoise(vec2 p, float seed) {
    vec2 i = floor(p), f = fract(p);
    vec2 u2 = f * f * (3.0 - 2.0 * f);
    float a = hash2(i, seed), b = hash2(i + vec2(1, 0), seed);
    float c = hash2(i + vec2(0, 1), seed), d = hash2(i + vec2(1, 1), seed);
    return mix(mix(a, b, u2.x), mix(c, d, u2.x), u2.y);
}
float fbmN(vec2 p, float seed, int oct) {
    float v = 0.0, a = 0.5, norm = 0.0;
    for (int i = 0; i < 8; i++) {
        if (i >= oct) break;
        v += a * vnoise(p, seed + float(i) * 1319.0); norm += a;
        p *= 2.0; a *= 0.5;
    }
    return v / max(norm, 1e-5);
}

// One band per ink, low to high; the stop positions are ignored.
#define MAXS 8
uniform vec3 u_ramp[MAXS];
uniform float u_rampPos[MAXS];
uniform float u_rampCount;

uniform float u_scale;
uniform float u_warp;
uniform float u_detail;
uniform float u_contrast;
uniform float u_balance;
uniform float u_grain;
uniform float u_block;
uniform float u_drift;
uniform float u_speed;
uniform float u_mix;

void main() {
    float W = u_resolution.x, H = u_resolution.y;
    float ar = H / W;
    vec2 dev = floor(v_texCoord * u_resolution);                       // device pixel (grain is per pixel)
    vec2 pxy = vec2(v_texCoord.x * W, (1.0 - v_texCoord.y) * H);       // canvas, y DOWN

    // Blockiness: the tool snaps to blocks of N preview pixels; scaled to the short side
    // so a 2400 px export carries the same block as the 700 px preview.
    float blk = floor(u_block + 0.5) * max(1.0, min(W, H) / 700.0);
    if (blk >= 1.0) pxy = floor(pxy / blk) * blk;
    vec2 uv = pxy / vec2(W, H);

    float u = uv.x * u_scale, v = uv.y * u_scale * ar;
    int oct = int(clamp(u_detail, 1.0, 7.0) + 0.5);
    // Drift: the tool walks a fourth noise axis on a circle; here the domain orbits.
    float ph = u_time * u_speed * 0.25;
    vec2 o = vec2(cos(ph), sin(ph)) * u_drift * 0.5;

    float wx = fbmN(vec2(u + 5.2, v + 1.3) + o, u_seed + 11.0, 2);
    float wy = fbmN(vec2(u + 9.1, v + 7.7) + o, u_seed + 29.0, 2);
    float val = fbmN(vec2(u + u_warp * (wx - 0.5) * 2.0, v + u_warp * (wy - 0.5) * 2.0) + o, u_seed, oct);
    val = clamp((val - 0.5) * u_contrast + 0.5, 0.0, 1.0);

    // Grain straight into the value, per device pixel, before the cut into bands.
    val = clamp(val + (hash2(dev, u_seed) - 0.5) * u_grain, 0.0, 1.0);
    // Spread skews the bands toward the low or the high inks.
    float q = pow(val, pow(2.0, -u_balance));

    int n = max(1, int(u_rampCount + 0.5));
    int idx = clamp(int(floor(q * float(n))), 0, n - 1);
    vec3 col = u_ramp[clamp(idx, 0, MAXS - 1)];

    if (u_hasInput > 0.5 && u_mix > 0.0) {
        col = mix(col, texture(u_image0, v_texCoord).rgb, u_mix);
    }
    fragColor0 = vec4(col, 1.0);
}

