// Ink ROLES by slot, as the tool does: 1 ground, 2 land, 3 coast A, 4 coast B. Slots past
// the inks provided wrap round, so a two-ink ramp still draws.
#define MAXS 8
uniform vec3 u_ramp[MAXS];
uniform float u_rampPos[MAXS];
uniform float u_rampCount;
vec3 ink(int role) {
    int n = max(1, int(u_rampCount + 0.5));
    return u_ramp[clamp(role - (role / n) * n, 0, MAXS - 1)];
}

uniform float u_level;
uniform float u_scale;
uniform float u_warp;
uniform float u_grid;
uniform float u_depth;
uniform float u_fringe;
uniform float u_spark;
uniform float u_tide;
uniform float u_speed;
uniform float u_mix;

// Is canvas-local point `l` (0..cw, 0..ch) inside a square of side k centred in the cell?
bool inSquare(vec2 l, float cw, float ch, float k) {
    vec2 c0 = vec2((cw - k) * 0.5, (ch - k) * 0.5);
    return l.x >= c0.x && l.x < c0.x + k && l.y >= c0.y && l.y < c0.y + k;
}

void main() {
    float W = u_resolution.x, H = u_resolution.y;
    float cols = max(12.0, floor(u_grid + 0.5));
    float cw = W / cols;
    float rows = max(6.0, floor(H / cw + 0.5));
    float ch = H / rows;
    float asp = W / H;
    float sc = max(0.5, u_scale);

    // Canvas pixel (y DOWN), its cell, and the position inside the cell.
    vec2 pxy = vec2(v_texCoord.x * W, (1.0 - v_texCoord.y) * H);
    float i = floor(pxy.x / cw), j = floor(pxy.y / ch);
    vec2 local = pxy - vec2(i * cw, j * ch);

    // The field at the cell centre, pushed around by a second field so blobs flow.
    float u = (i + 0.5) / cols, v = (j + 0.5) / rows;
    float x = u * sc * asp, y = v * sc;
    float wx = fbmN(vec2(x * 0.6 + 11.3, y * 0.6 + 3.7), u_seed + 7.0, 3) - 0.5;
    float wy = fbmN(vec2(x * 0.6 + 5.1, y * 0.6 + 19.9), u_seed + 13.0, 3) - 0.5;
    float fv = fbmN(vec2(x + wx * u_warp * 2.4, y + wy * u_warp * 2.4), u_seed, 4);

    // Tide breathes the cut level so the coast advances and retreats; still at Speed 0.
    float tide = sin(u_time * u_speed * 0.5) * 0.10 * min(1.6, u_tide);
    float lvl = clamp(u_level * 0.7 + 0.15 + tide, 0.05, 0.95);
    float band = 0.012 + u_fringe * 0.07;      // how far either side the coast breaks up
    float d = fv - lvl;

    vec3 col = ink(0);
    if (d > band) {
        // Inland: one land square per cell, growing with depth, so the fill carries the
        // field's shading instead of being flat.
        float t = min(1.0, (d - band) / (0.20 * (1.05 - u_depth * 0.85)));
        float k = cw * (0.30 + 0.68 * t);
        if (inSquare(local, cw, ch, k)) col = ink(1);
    } else if (d > -band) {
        // The coast: a speck appears more often the nearer the cell is to the cut, in one
        // of two colours used nowhere else.
        float near = 1.0 - abs(d) / band;
        if (hash2(vec2(i, j), u_seed + 53.0) < near * near * u_spark * 1.35) {
            float k = cw * (0.34 + 0.42 * near);
            if (inSquare(local, cw, ch, k)) col = (hash2(vec2(i, j), u_seed + 59.0) < 0.5) ? ink(2) : ink(3);
        }
    }

    if (u_hasInput > 0.5 && u_mix > 0.0) {
        col = mix(col, texture(u_image0, v_texCoord).rgb, u_mix);
    }
    fragColor0 = vec4(col, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_hasInput;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// Oddgrid: a fine grid of crisp cells. Three low-octave value-noise fields decide,
// per CELL (never per pixel), whether a cell is painted, which ink it takes, and
// where a mark goes. Every field is sampled at cell coordinates, so the look is
// blocks with pixel edges, not a smoothed noise.

// Integer hash: a multiply-xorshift mixer over (cell x, cell y, salted seed). Each
// decision below uses its own salt so the fields stay independent of one another.
uint mixbits(uint v) { v ^= v >> 16u; v *= 0x7feb352du; v ^= v >> 15u; v *= 0x846ca68bu; v ^= v >> 16u; return v; }
float hash2(vec2 ip, float seed) {
    uvec2 q = uvec2(ivec2(ip) + 32768);
    uint h = mixbits(q.x * 0x9e3779b1u ^ mixbits(q.y * 0x85ebca77u ^ mixbits(uint(int(seed)) * 0xc2b2ae3du)));
    return float(h) * (1.0 / 4294967295.0);
}
// Smooth value noise on the integer lattice, one lattice value per hash.
float vnoise(vec2 p, float seed) {
    vec2 i = floor(p), f = fract(p);
    vec2 u2 = f * f * (3.0 - 2.0 * f);
    float a = hash2(i, seed), b = hash2(i + vec2(1, 0), seed);
    float c = hash2(i + vec2(0, 1), seed), d = hash2(i + vec2(1, 1), seed);
    return mix(mix(a, b, u2.x), mix(c, d, u2.x), u2.y);
}
// Normalised fbm: `oct` octaves, halving amplitude, doubling frequency, a new
// lattice per octave. Few octaves on purpose - the tool keeps its regions coherent.
float fbmN(vec2 p, float seed, int oct) {
    float v = 0.0, a = 0.5, norm = 0.0;
    for (int i = 0; i < 4; i++) {
        if (i >= oct) break;
        v += a * vnoise(p, seed + float(i) * 977.0); norm += a;
        p *= 2.0; a *= 0.5;
    }
    return v / max(norm, 1e-5);
}
// Contrast about the midpoint, clamped: the tool's `stretch`.
float stretch(float v, float k) { return clamp((v - 0.5) * k + 0.5, 0.0, 1.0); }

// The palette is an ORDERED list of inks: a filled cell's field value picks an
// index into it, low to high. The order IS the stop position — both upload
// paths (shaderfx/params.ts cleanStops and the server's _shader_effects.py)
// sort stops by pos before filling u_ramp, so a user reorders inks by moving
// stops, not by list order.
#define MAXS 8
uniform vec3 u_ramp[MAXS];
uniform float u_rampPos[MAXS];
uniform float u_rampCount;
uniform vec3 u_bg;      // shows through every empty cell
uniform vec3 u_ink;     // the marks

uniform float u_cols;
uniform float u_scale;
uniform float u_density;
uniform float u_block;
uniform float u_bsize;
uniform float u_speck;
uniform float u_grain;
uniform float u_variety;
uniform float u_balance;
uniform float u_motif;     // 0 none, 1 dot, 2 ring, 3 square, 4 wedge, 5 mixed
uniform float u_motifAmt;
uniform float u_markSize;
uniform float u_mix;

// Pixel edge of grid line `i` for `n` cells over `len` pixels: the tool rounds every
// edge to a whole pixel, so cells differ by a pixel here and there and never blur.
float edgeAt(float i, float n, float len) { return floor(i * len / n + 0.5); }

// Does the mark of kind `shape` cover the pixel whose centre sits at `l` in a
// cell of cw x ch pixels? Dot and ring get a one-pixel soft edge (the tool draws
// them with an antialiased arc); square and wedge are hard, as fillRect/fill are.
float markCover(int shape, vec2 l, float cw, float ch) {
    float cs = min(cw, ch), ms = u_markSize;
    vec2 c = vec2(cw, ch) * 0.5;
    if (shape == 1) {                                   // dot: disc, diameter markSize x cell
        float r = cs * ms * 0.5;
        return clamp(r - length(l - c) + 0.5, 0.0, 1.0);
    }
    if (shape == 2) {                                   // ring: stroked circle
        float lw = max(1.0, cs * ms * 0.28);
        float r = max(lw * 0.6, cs * ms * 0.5 - lw * 0.5);
        return clamp(lw * 0.5 - abs(length(l - c) - r) + 0.5, 0.0, 1.0);
    }
    if (shape == 3) {                                   // square: side markSize x cell
        float hs = cs * ms * 0.5;
        vec2 d = abs(l - c);
        return (d.x < hs && d.y < hs) ? 1.0 : 0.0;
    }
    if (shape == 4) {                                   // wedge: the lower-right triangle
        return (l.x / cw + l.y / ch >= 1.0) ? 1.0 : 0.0;
    }
    return 0.0;
}

void main() {
    float W = u_resolution.x, H = u_resolution.y;
    float cols = max(2.0, floor(u_cols + 0.5));
    float rows = max(4.0, floor(cols * H / W + 0.5));
    float B = max(2.0, floor(u_bsize + 0.5));
    float sc = max(0.5, u_scale);
    int n = max(1, int(u_rampCount + 0.5));

    // The device pixel, y DOWN like the tool's canvas; its centre for the marks.
    vec2 pix = floor(vec2(v_texCoord.x * W, (1.0 - v_texCoord.y) * H));
    pix = clamp(pix, vec2(0.0), vec2(W, H) - 1.0);

    // Which snapped cell holds this pixel: start from the even split, then step to
    // the neighbour if the rounded edges say so.
    float x = floor(pix.x * cols / W);
    if (pix.x < edgeAt(x, cols, W)) x -= 1.0; else if (pix.x >= edgeAt(x + 1.0, cols, W)) x += 1.0;
    float y = floor(pix.y * rows / H);
    if (pix.y < edgeAt(y, rows, H)) y -= 1.0; else if (pix.y >= edgeAt(y + 1.0, rows, H)) y += 1.0;
    x = clamp(x, 0.0, cols - 1.0); y = clamp(y, 0.0, rows - 1.0);
    float x0 = edgeAt(x, cols, W), y0 = edgeAt(y, rows, H);
    float cw = edgeAt(x + 1.0, cols, W) - x0, ch = edgeAt(y + 1.0, rows, H) - y0;
    vec2 local = pix - vec2(x0, y0) + 0.5;

    // ── the cell's decisions (everything below is a function of the cell, not the pixel)
    vec2 cell = vec2(x, y);
    vec2 blk = floor(cell / B);                          // the block this cell belongs to
    vec2 centre = cell + 0.5;

    // 1. Coordinates slide toward the block centre as blockiness rises, so colour
    //    regions square off.
    vec2 bc = mix(centre, blk * B + B * 0.5, u_block);

    // 2. Colour field: a coherent 2-octave field, then each block takes on its own
    //    tone in proportion to blockiness, and the result is pushed apart.
    float smoothF = fbmN(bc / sc, u_seed, 2);
    float blockTone = smoothF * 0.5 + hash2(blk, u_seed + 404.0) * 0.5;
    float base = stretch(mix(smoothF, blockTone, u_block), 2.0);

    // 3. Coverage field: decides what gets painted at all (3 octaves, offset domain).
    float mask = stretch(fbmN(centre / (sc * 1.15) + vec2(91.0, -17.0), u_seed + 9111.0, 3), 1.8);

    // 4. Fine field: much smaller features that chew the region edges into pixels.
    float det = fbmN(centre / (sc * 0.26) + vec2(37.0, -11.0), u_seed + 7717.0, 2);

    // 5. Each block gets its own coverage bias and its own grain strength - that is
    //    what makes the patchwork.
    float bias = (hash2(blk, u_seed + 808.0) - 0.5) * u_variety * 0.6;
    float level = 0.5 + (u_density - 0.5) * 1.1 + bias;
    float grainLocal = u_grain * mix(1.0, 0.15 + hash2(blk, u_seed + 909.0) * 2.1, clamp(u_variety * 0.8, 0.0, 1.0));

    // 6. Filled or empty.
    bool filled = mask + (det - 0.5) * grainLocal * 1.15 < level;

    vec3 col = u_bg;
    if (filled) {
        // 7. Field value -> palette index (order = ramp); balance skews the mapping.
        //    Specks swap in a random ink from the same palette.
        float v = pow(base, pow(2.0, -u_balance));
        int ci = min(n - 1, int(floor(v * float(n))));
        if (u_speck > 0.0 && hash2(cell, u_seed + 21.0) < u_speck) {
            ci = int(floor(hash2(cell, u_seed + 33.0) * float(n)));
            ci = ci - (ci / n) * n;
        }
        col = u_ramp[clamp(ci, 0, MAXS - 1)];

        // 8. Some filled cells also carry a mark in the ink colour. Mixed picks a
        //    shape per cell.
        int motif = int(u_motif + 0.5);
        if (motif != 0 && u_motifAmt > 0.0 && hash2(cell, u_seed + 64.0) < u_motifAmt) {
            int shape = motif;
            if (motif == 5) {
                float k = hash2(cell, u_seed + 4009.0);
                shape = k < 0.4 ? 1 : k < 0.65 ? 3 : k < 0.85 ? 2 : 4;
            }
            col = mix(col, u_ink, markCover(shape, local, cw, ch));
        }
    }

    if (u_hasInput > 0.5 && u_mix > 0.0) {
        col = mix(col, texture(u_image0, v_texCoord).rgb, u_mix);
    }
    fragColor0 = vec4(col, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_hasInput;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// Static: a low-res ONE-BIT poster. The picture is a tiny grid of cells, every cell
// either ink or paper. The grid splits into stacked horizontal BANDS, each running
// its own 1-bit pattern engine (moire, bars, static, blocks, rings, zigzag); some of
// the time an INSET panel punches in on top with its own engine. A glitch pass then
// shifts row segments sideways, smears rows down over their neighbours, and punches
// rectangular dropouts. Drawn as hard, scaled-up pixels - no smoothing anywhere.
//
// Everything is decided per CELL, and every random choice comes from one seeded
// stream read by index, so a seed always gives the same poster in the browser, on
// the server, and at any output size (the cell grid itself is what changes).

uniform vec3 u_ink;       // the 1 bits
uniform vec3 u_bg;        // the 0 bits
uniform float u_res;      // cells across
uniform float u_regions;  // stacked bands
uniform float u_glitch;   // 0..1 glitch amount
uniform float u_mix;

// ── randomness ─────────────────────────────────────────────────────────────────
// A permuted-congruential mixer (the "pcg" one-liner) over 32-bit state; three
// inputs fold in one after another. Own construction, not the tool's.
uint pcg(uint v) {
    uint s = v * 747796405u + 2891336453u;
    uint w = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u;
    return (w >> 22u) ^ w;
}
uint fold3(uint a, uint b, uint c) { return pcg(pcg(pcg(a) + b * 0x9E3779B9u) + c * 0x85EBCA6Bu); }
// 24 mantissa bits -> a float in [0,1) that is exact on every GPU.
float unit(uint h) { return float(h >> 8u) * (1.0 / 16777216.0); }

// The seeded STREAM: value k of stream `s` is a pure function of (s, k), so the
// layout can address its draws by index instead of replaying a generator - the
// same order and ranges the tool draws in, without the sequential dependence.
uint streamU(uint s, int k) { return fold3(s, uint(k) + 1u, 0x27D4EB2Fu); }
float stream(uint s, int k) { return unit(streamU(s, k)); }

// Per-cell hash for the pattern engines: (u, v, salt, region seed).
float cellHash(float u, float v, uint salt, uint rs) {
    uint hu = uint(int(u) + 65536), hv = uint(int(v) + 65536);
    return unit(fold3(hu, hv, pcg(rs + salt * 0x632BE5ABu)));
}

// ── layout ──────────────────────────────────────────────────────────────────────
#define MAXR 6
#define RDRAWS 18     // draws per region: type + 17 params, in the order below
#define T_MOIRE 0
#define T_BARS 1
#define T_STATIC 2
#define T_BLOCKS 3
#define T_RINGS 4
#define T_ZIGZAG 5

struct Region {
    int type;
    float x0, x1, y0, y1;
    float a, b, warp, th, cx, cy, rk, ph, dens, grad, q, duty, p, slope;
    bool vert;
    uint rs;
};

// Draw a region's parameters from the layout stream starting at index `k`. Same
// order and ranges as the tool: type, a, b, warp, th, cx, cy, rk, ph, dens, grad,
// q, duty, p, slope (sign then size), vert, region seed.
Region mkRegion(uint s, int k, float x0, float x1, float y0, float y1, float gw, float gh) {
    Region R;
    R.type = int(stream(s, k) * 6.0);
    R.x0 = x0; R.x1 = x1; R.y0 = y0; R.y1 = y1;
    R.a = 0.15 + stream(s, k + 1) * 0.75;
    R.b = 0.06 + stream(s, k + 2) * 0.4;
    R.warp = stream(s, k + 3) * 6.0;
    R.th = (stream(s, k + 4) - 0.5) * 0.8;
    R.cx = (stream(s, k + 5) * 1.6 - 0.3) * gw;
    R.cy = (stream(s, k + 6) * 1.6 - 0.3) * gh;
    R.rk = 0.12 + stream(s, k + 7) * 0.4;
    R.ph = stream(s, k + 8) * 6.28318530718;
    R.dens = 0.2 + stream(s, k + 9) * 0.5;
    R.grad = (stream(s, k + 10) - 0.5) * 0.9;
    R.q = 2.0 + floor(stream(s, k + 11) * 5.0);
    R.duty = 0.35 + stream(s, k + 12) * 0.35;
    R.p = 5.0 + floor(stream(s, k + 13) * 10.0);
    R.slope = (stream(s, k + 14) < 0.5 ? 1.0 : -1.0) * (0.3 + stream(s, k + 15) * 1.2);
    R.vert = stream(s, k + 16) < 0.35;
    R.rs = streamU(s, k + 17);
    return R;
}

// ── one bit per cell, by engine ────────────────────────────────────────────────
bool cellOn(Region R, float u, float v) {
    if (R.type == T_MOIRE) {
        float w1 = sin(u * R.a + sin(v * R.b) * R.warp + R.ph);
        float w2 = sin(length(vec2(u - R.cx, v - R.cy)) * R.rk);
        return (w1 + w2) > R.th;
    }
    if (R.type == T_RINGS) {
        return sin(length(vec2(u - R.cx, v - R.cy)) * R.rk + R.ph) > R.th;
    }
    if (R.type == T_BARS) {
        if (R.vert) {
            float vv = v - R.y0;
            float seg = cellHash(u, floor(vv / R.q), 1u, R.rs);
            bool colOn = cellHash(u, 0.0, 7u, R.rs) < 0.8;
            return colOn && seg < R.duty + sin(vv * 0.2) * 0.1;
        }
        float uu = u - R.x0;
        float seg = cellHash(floor(uu / R.q), v, 1u, R.rs);
        bool rowOn = cellHash(0.0, v, 7u, R.rs) < 0.8;
        return rowOn && seg < R.duty + sin(u * 0.15) * 0.08;
    }
    if (R.type == T_STATIC) {
        // density runs from dens-grad at the top of the band to dens+grad at the bottom
        float t = (v - R.y0) / max(1.0, R.y1 - R.y0);
        float d = clamp(R.dens + R.grad * (t - 0.5) * 2.0, 0.02, 0.95);
        return cellHash(u, v, 0u, R.rs) < d;
    }
    if (R.type == T_BLOCKS) {
        // XOR of a coarse and a coarser block grid
        bool a = cellHash(floor(u / (R.q * 2.0)), floor(v / (R.q * 2.0)), 0u, R.rs) < 0.5;
        bool b = cellHash(floor(u / (R.q * 5.0)), floor(v / (R.q * 5.0)), 3u, R.rs) < 0.5;
        return a != b;
    }
    // zigzag: a diagonal stripe, its duty cycle across a period of p cells
    float uu = u + floor(v * R.slope);
    float m = uu - floor(uu / R.p) * R.p;       // positive modulo
    return m < R.p * R.duty;
}

// The bit BEFORE the glitch pass: the band owning row v, unless the inset panel
// covers the cell.
bool originalBit(uint s, int n, float u, float v, float gw, float gh) {
    // band heights from weights 0.5 + r*1.2 (draws 0..n-1); the last band snaps to gh
    float sum = 0.0;
    for (int i = 0; i < MAXR; i++) { if (i >= n) break; sum += 0.5 + stream(s, i) * 1.2; }
    float y = 0.0, y0 = 0.0, y1 = gh; int band = 0;
    for (int i = 0; i < MAXR; i++) {
        if (i >= n) break;
        float h = floor((0.5 + stream(s, i) * 1.2) / sum * gh + 0.5);
        float yb = (i == n - 1) ? gh : min(gh, y + h);
        if (v >= y && v < yb) { band = i; y0 = y; y1 = yb; }
        y = yb;
    }
    // rows below every band (none, since the last snaps to gh) fall to band 0 like the tool
    int k = n + band * RDRAWS;
    Region R = mkRegion(s, k, 0.0, gw, y0, y1, gw, gh);

    // 40% of seeds: an inset panel with its own engine punches in on top
    int ki = n + n * RDRAWS;
    if (stream(s, ki) < 0.4) {
        float ix0 = floor(gw * (0.1 + stream(s, ki + 1) * 0.25) + 0.5);
        float ix1 = floor(gw * (0.65 + stream(s, ki + 2) * 0.3) + 0.5);
        float iy0 = floor(gh * (0.15 + stream(s, ki + 3) * 0.3) + 0.5);
        float iy1 = floor(gh * (0.55 + stream(s, ki + 4) * 0.35) + 0.5);
        if (u >= ix0 && u < ix1 && v >= iy0 && v < iy1) {
            R = mkRegion(s, ki + 5, ix0, ix1, iy0, iy1, gw, gh);
        }
    }
    return cellOn(R, u, v);
}

// ── the glitch pass, resolved per cell ─────────────────────────────────────────
// The tool runs a fixed list of seeded ops over the whole bit buffer: shifts, then
// smears, then drops. A cell finds its final bit by walking those lists BACKWARDS:
// a later op decides where an earlier op's result is read from, so undoing them
// from the last to the first maps this cell to the source cell whose original bit
// it shows. Loop caps: 64 shifts, 16 smears, 8 drops (the counts are 0.3*rows,
// 0.08*rows and 6 at full glitch; rows only pass 213 on a tall grid at max res).
#define MAXSHIFT 96
#define MAXSMEAR 26
#define MAXDROP 8

// Pixel edge of grid line `i` for `n` cells over `len` pixels: rounded to a whole
// pixel so cells differ by a pixel here and there and never blur.
float edgeAt(float i, float n, float len) { return floor(i * len / n + 0.5); }

void main() {
    float W = u_resolution.x, H = u_resolution.y;
    float gw = clamp(floor(u_res + 0.5), 8.0, 320.0);
    float gh = max(8.0, floor(gw * H / W + 0.5));
    int n = clamp(int(u_regions + 0.5), 1, MAXR);
    float amt = clamp(u_glitch, 0.0, 1.0);
    uint seed = uint(max(u_seed, 0.0) + 0.5);
    uint sLayout = pcg(seed * 0x9E3779B1u + 0x1B873593u);
    uint sGlitch = pcg(seed * 0xC2B2AE35u + 0x165667B1u);

    // The device pixel, y DOWN like the tool's canvas, and the snapped cell holding it.
    vec2 pix = floor(vec2(v_texCoord.x * W, (1.0 - v_texCoord.y) * H));
    pix = clamp(pix, vec2(0.0), vec2(W, H) - 1.0);
    float u = floor(pix.x * gw / W);
    if (pix.x < edgeAt(u, gw, W)) u -= 1.0; else if (pix.x >= edgeAt(u + 1.0, gw, W)) u += 1.0;
    float v = floor(pix.y * gh / H);
    if (pix.y < edgeAt(v, gh, H)) v -= 1.0; else if (pix.y >= edgeAt(v + 1.0, gh, H)) v += 1.0;
    u = clamp(u, 0.0, gw - 1.0); v = clamp(v, 0.0, gh - 1.0);

    int nShift = min(MAXSHIFT, int(floor(gh * 0.3 * amt + 0.5)));
    int nSmear = min(MAXSMEAR, int(floor(gh * 0.08 * amt + 0.5)));
    int nDrop = min(MAXDROP, int(floor(6.0 * amt + 0.5)));
    int kSmear = nShift * 4;            // stream index where the smear draws begin
    int kDrop = kSmear + nSmear * 2;    // ... and the drop draws

    bool bit;
    bool dropped = false;
    float dropVal = 0.0;

    // 3. Drops (last op wins): a rect x0,y0 w,h filled with a random 0 or 1.
    for (int i = 0; i < MAXDROP; i++) {
        if (i >= nDrop) break;
        int k = kDrop + i * 5;
        float x0 = floor(stream(sGlitch, k) * gw);
        float y0 = floor(stream(sGlitch, k + 1) * gh);
        float w = 2.0 + floor(stream(sGlitch, k + 2) * gw * 0.2);
        float h = 1.0 + floor(stream(sGlitch, k + 3) * gh * 0.06);
        float val = stream(sGlitch, k + 4) < 0.5 ? 0.0 : 1.0;
        if (u >= x0 && u < min(gw, x0 + w) && v >= y0 && v < min(gh, y0 + h)) { dropped = true; dropVal = val; }
    }

    if (dropped) {
        bit = dropVal > 0.5;
    } else {
        // 2. Smears, undone last-to-first: a row inside [y, y+reps) shows row y-1 as it
        //    stood when that op ran, so the walk carries on from y-1 through the earlier
        //    ops. That follows a smear-of-a-smear chain exactly, with no hop bound.
        float sv = v;
        for (int i = MAXSMEAR - 1; i >= 0; i--) {
            if (i >= nSmear) continue;
            int k = kSmear + i * 2;
            float y = 1.0 + floor(stream(sGlitch, k) * (gh - 1.0));
            float reps = 1.0 + floor(stream(sGlitch, k + 1) * 3.0);
            if (sv >= y && sv < min(gh, y + reps)) sv = y - 1.0;
        }
        // 1. Shifts, undone last-to-first: inside a shifted segment of row y the cell
        //    shows the row's earlier state at (x+dx) mod gw.
        float su = u;
        for (int i = MAXSHIFT - 1; i >= 0; i--) {
            if (i >= nShift) continue;
            int k = i * 4;
            float y = floor(stream(sGlitch, k) * gh);
            if (y != sv) continue;
            float x0 = floor(stream(sGlitch, k + 1) * gw);
            float len = 1.0 + floor(stream(sGlitch, k + 2) * gw * 0.5);
            float dx = 1.0 + floor(stream(sGlitch, k + 3) * 7.0);
            if (su >= x0 && su < min(gw, x0 + len)) su = mod(su + dx, gw);
        }
        bit = originalBit(sLayout, n, su, sv, gw, gh);
    }

    // 4. Ink where the bit is set, paper elsewhere. Hard cell edges, no smoothing.
    vec3 col = bit ? u_ink : u_bg;
    if (u_hasInput > 0.5 && u_mix > 0.0) {
        col = mix(col, texture(u_image0, v_texCoord).rgb, u_mix);
    }
    fragColor0 = vec4(col, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_hasInput;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// Culture: a plate of colonies. Each of `count` cells contributes one round, soft
// hump to a SINGLE field — added, never maxed or layered. Two cells that overlap
// therefore push the total above what either reaches alone, and the pair reads as
// one grown-together blob. That field is then inked by a RING LADDER: the first ink
// paints the ground; each later ink takes a ring one step nearer the middle. Every
// boundary is chosen as a RADIUS — the reason the rings stay comparable in width
// rather than collapsing into one fat centre behind a thread-thin outline.
//
// Ported rule for rule from the playgrnd generator (reference line numbers below);
// every hash, every draw and every line of GLSL here is our own.
//
//  1. ONE field, bumps SUMMED, profile (1-d^2)^2, nothing outside d<1   [ref 87-94]
//       -> the cell loop in main(), `field += t * t`
//  2. `fuse` is a radius multiplier only: the seeded centres are fixed,   [ref 68-74]
//     and a bigger radius means more of the summed bumps overlap. That is
//     why the dial reads as "how joined-up the colonies are" while the
//     layout of the plate stays put.
//       -> the (0.75 + fuse*0.8) factor in `baseR`; positions never see fuse
//  3. the radius follows sqrt(AREA) * 0.87 — area, not width — so       [ref 71-74]
//     reshaping the frame keeps roughly the coverage it had, instead of
//     packing a wide frame solid
//       -> `baseR` carries sqrt(aspect): in frame-width units,
//          sqrt(FW*FH)/FW == sqrt(FH/FW) == sqrt(H/W)
//  4. centres are scattered past all four borders, so blobs get cut by  [ref 77-78]
//     the frame instead of tidily fitting inside it
//       -> centres drawn over [-0.15, 1.15] of each side
//  5. each cell has its own radius factor 0.55..1.45 and its own wobble [ref 79-80]
//     phase
//       -> draws 53u and 37u
//  6. ring boundaries are chosen as radii and pushed back through the   [ref 112-127]
//     bump profile into field values: `cover` fixes the outermost one
//     (t0 -> dEdge) and `spread` raises the inner radii to a power, so
//     above 1 the middle ink takes more room and the centre ink less;
//     the top of the ladder is pinned at 1.55
//       -> `t0`, `dEdge`, the `TH` ladder
//  7. a pixel's place is measured in WHOLE RINGS (ring index plus the   [ref 149-157]
//     fraction across it), so one notch of grain moves a pixel the same
//     share of a ring however thick that ring is
//       -> `band`
//  8. grain lands twice, from two unrelated noise fields: on the ring   [ref 129-130,
//     position (grain*1.05), which frays the boundaries, and on the         158-161,
//     finished RGB (grain*46 of 255), which speckles every pixel            173-177]
//       -> `gq` / `gl`
//  9. `tex` fine | stipple: the grain reads a SNAPPED pixel, (x/dot|0), [ref 131-132,
//     so stipple is a coarse grain that never beats against the grid       159, 174]
//       -> `gp`
// 10. the change from one ink to the next is squeezed into the LAST     [ref 165-170]
//     `soft` of a band and smoothed, so the colour turns over right at
//     the ring's edge: a small `soft` cuts a stencil-hard border, a big
//     one spreads the turnover across most of the ring
//       -> `fr`
// 11. motion, one loop long: drift moves each cell on its own wobble    [ref 64-67,
//     (amount*0.05 of the width), grow breathes its radius                 80-82,
//     (amount*0.22), cycle rolls the palette in WHOLE steps,               100-105]
//     max(1, round(amount*2)) turns per loop
//       -> `drift`, `grow`, `roll`

// ── the inks ────────────────────────────────────────────────────────────────────
// The stops are ORDERED ROLES, not a smooth ramp: stop 0 is the ground the blobs
// sit on, and each stop after it takes the next ring inward, the last one the very
// middle of a blob. The order IS the stop position — both upload paths
// (shaderfx/params.ts cleanStops and the server's _shader_effects.py) sort stops by
// pos before filling u_ramp, so a person reorders the roles by moving stops.
#define MAXS 8
uniform vec3 u_ramp[MAXS];
uniform float u_rampPos[MAXS];
uniform float u_rampCount;   // how many inks: one for the ground, one per ring

uniform float u_count;    // cells dropped on the plate
uniform float u_size;     // cell size
uniform float u_fuse;     // how much they melt together
uniform float u_cover;    // how much of a blob the outermost ink keeps
uniform float u_spread;   // how far the inner boundaries are pulled toward the middle
uniform float u_soft;     // width of the crossing between rings
uniform float u_tex;      // 0 fine, 1 stipple
uniform float u_grain;
uniform float u_dot;      // stipple cell, in pixels
uniform float u_motion;   // 0 still, 1 drift, 2 grow, 3 cycle
uniform float u_amount;
uniform float u_speed;
uniform float u_mix;

#define MAXCELLS 64
#define TAU 6.28318530718

// ── randomness ─────────────────────────────────────────────────────────────────
// A permuted-congruential mixer over 32-bit state; three inputs fold in one after
// another. Own construction, not the tool's.
uint pcg(uint v) {
    uint s = v * 747796405u + 2891336453u;
    uint w = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u;
    return (w >> 22u) ^ w;
}
uint fold3(uint a, uint b, uint c) { return pcg(pcg(pcg(a) + b * 0x9E3779B9u) + c * 0x85EBCA6Bu); }
// 24 mantissa bits -> a float in [0,1) that is exact on every GPU.
float unit(uint h) { return float(h >> 8u) * (1.0 / 16777216.0); }

// Cell k's draw for `salt`: a pure function of (seed, index, salt), so the cells are
// addressed by index instead of replaying a generator in order — same independent
// draws per cell (centre x, centre y, wobble, radius), no sequential dependence.
float cellDraw(int k, uint salt, uint seed) { return unit(fold3(seed, uint(k) + 1u, salt)); }
// Grain: one value per (pixel or stipple cell, salted seed).
float pixHash(vec2 p, uint salt, uint seed) {
    uvec2 q = uvec2(ivec2(p) + 65536);
    return unit(fold3(q.x, q.y, pcg(seed + salt)));
}

void main() {
    float W = max(u_resolution.x, 1.0), H = max(u_resolution.y, 1.0);
    float A = H / W;                     // the frame's height in units of its width
    int n = clamp(int(u_rampCount + 0.5), 2, MAXS);
    int cells = clamp(int(u_count + 0.5), 1, MAXCELLS);
    uint seed = uint(max(u_seed, 0.0) + 0.5);
    int mode = int(u_motion + 0.5);

    // 11. The tool's loop is frames/fps = 3 s long and T is that loop's phase, so the
    // clock is SCALED (never a raw u_time) and every mode returns to where it began.
    float T = (mode == 0) ? 0.0 : fract(u_time * max(u_speed, 0.0) * (1.0 / 3.0));
    float ph = T * TAU;
    float drift = (mode == 1) ? u_amount * 0.05 : 0.0;
    float grow  = (mode == 2) ? u_amount * 0.22 : 0.0;

    // The device pixel, y DOWN like the tool's canvas, and the same point in
    // frame-width units (x over 0..1, y over 0..A) — the space the plate is built in.
    // The tool reads its field at x*(FW/W), i.e. at the pixel's index, so we do too.
    vec2 pix = clamp(floor(vec2(v_texCoord.x * W, (1.0 - v_texCoord.y) * H)), vec2(0.0), vec2(W, H) - 1.0);
    vec2 P = pix / W;

    // 1-5. Every cell adds its bump into the same running total, so overlaps compound.
    float baseR = (0.05 + u_size * 0.20) * (0.75 + u_fuse * 0.8) * 0.87 * sqrt(A);
    float field = 0.0;
    for (int k = 0; k < MAXCELLS; k++) {
        if (k >= cells) break;
        vec2 c = vec2((-0.15 + cellDraw(k, 11u, seed) * 1.3),
                      (-0.15 + cellDraw(k, 23u, seed) * 1.3) * A);
        float wob = cellDraw(k, 37u, seed) * TAU;
        float r = max(baseR * (0.55 + cellDraw(k, 53u, seed) * 0.9) * (1.0 + sin(ph + wob) * grow), 1e-5);
        c += vec2(cos(ph + wob), sin(ph + wob * 1.7)) * drift;
        vec2 d = P - c;
        float d2 = dot(d, d) / (r * r);
        if (d2 < 1.0) { float t = 1.0 - d2; field += t * t; }
    }

    // 6. The ring ladder. The bump profile drops away quickly near a cell's rim and
    // barely moves near its middle, so cutting the field at equal VALUE steps would hand
    // nearly the whole blob to the innermost ink and leave the outer ring a thread wide.
    // Pick each boundary as a radius D and push it back through the profile ((1-D^2)^2)
    // to get the value to compare against; the inks then divide a blob into bands of
    // comparable thickness.
    float t0 = clamp((1.0 - u_cover) * 0.9, 0.002, 0.998);
    float dEdge = sqrt(max(0.0, 1.0 - sqrt(t0)));
    float TH[MAXS + 1];
    TH[0] = 0.0;
    float prev = 0.0;
    for (int k = 1; k <= MAXS; k++) {
        float val;
        if (k < n) {
            float D = dEdge * pow(float(n - k) / float(n - 1), max(u_spread, 0.001));
            float e = 1.0 - D * D;
            val = e * e;
        } else if (k == n) {
            val = max(prev + 1e-4, 1.55);      // the ceiling the innermost band runs to
        } else {
            val = 2.0;
        }
        TH[k] = val;
        prev = val;
    }

    // 7. Locate this pixel on the ladder, measured in whole rings.
    float band;
    if (field < TH[1]) {
        band = TH[1] > 0.0 ? field / TH[1] : 0.0;
    } else {
        int kk = 1;
        float lo = TH[1], hi = TH[2];
        for (int k = 1; k < MAXS - 1; k++) {
            if (k >= n - 1) break;             // the innermost band runs to TH[n]
            if (field < TH[k + 1]) break;
            kk = k + 1; lo = TH[k + 1]; hi = TH[k + 2];
        }
        band = float(kk) + (hi > lo ? (field - lo) / (hi - lo) : 0.0);
    }

    // 8-9. Grain on the band position, read at a snapped pixel when stippling.
    float dotPx = max(1.0, floor(u_dot + 0.5));
    vec2 gp = (u_tex > 0.5) ? floor(pix / dotPx) : pix;
    float gq = u_grain * 1.05;
    if (gq > 0.002) band += (pixHash(gp, 1301u, seed) - 0.5) * gq;

    // 10. Mix the two neighbouring roles, the turnover squeezed into the band's last `soft`.
    band = clamp(band, 0.0, float(n - 1));
    int i0 = min(int(floor(band)), n - 2);
    float fr = band - float(i0);
    float soft = max(u_soft, 0.001);
    fr = clamp((fr - (1.0 - soft)) / soft, 0.0, 1.0);
    fr = fr * fr * (3.0 - 2.0 * fr);

    // 11. Cycle rolls the whole ladder of roles by whole steps.
    int roll = 0;
    if (mode == 3) {
        float turns = max(1.0, floor(u_amount * 2.0 + 0.5));
        roll = int(floor(T * float(n) * turns));
    }
    int ia = i0 + roll;      ia -= (ia / n) * n;
    int ib = i0 + 1 + roll;  ib -= (ib / n) * n;
    vec3 col = mix(u_ramp[clamp(ia, 0, MAXS - 1)], u_ramp[clamp(ib, 0, MAXS - 1)], fr);

    // 8. ...and a second time on the finished RGB, every pixel, from an unrelated field.
    float gl = u_grain * 46.0;
    if (gl > 0.002) col += vec3((pixHash(gp, 7919u, seed) - 0.5) * gl * (1.0 / 255.0));
    col = clamp(col, 0.0, 1.0);

    if (u_hasInput > 0.5 && u_mix > 0.0) {
        col = mix(col, texture(u_image0, v_texCoord).rgb, u_mix);
    }
    fragColor0 = vec4(col, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_seed;
uniform float u_hasInput;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

uint pcg(uint v) { v = v * 747796405u + 2891336453u; v = ((v >> ((v >> 28u) + 4u)) ^ v) * 277803737u; return (v >> 22u) ^ v; }
